window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-23"]={"block":"med:med-clinica-medica-med-clm-23","label":"MED · MED CLM 23","count":447,"questions":[{"id":"med-clinica-medica-med-clm-23-345451","number":"345451","sourceNumber":"345451","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Por velocidade de redução da pressão ventricular, a segunda bulha cardíaca pode\napresentar hipofonese por:","options":{"A":"Estado de baixo débito cardíaco (choque e miocardiopatia).","B":"Enfisema pulmonar.","C":"Edema Agudo de Pulmão.","D":"Hipertensão arterial sistêmica."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-281102","number":"281102","sourceNumber":"281102","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 46 anos, hipertenso e tabagista, refere dor na região anterior do tórax, que\npiora com decúbito, de início há 6 horas.\nSinais vitais na admissão: PA 160/100mmHg, FV 100bpm,\nTemp.axilar 37,5ºC, FR 30mrpm. Com base nos dados clínicos e no ECG abaixo, qual seria a\nhipótese diagnóstica mais provável?","options":{"A":"Pericardite aguda","B":"Cardiomiopatia hipertrófica","C":"Disseção aórtica","D":"Taquiarritmia supraventricular por reentrada","E":"Síndrome coronariana aguda"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-281103","number":"281103","sourceNumber":"281103","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 55 anos de idade com história de infarto do miocárdio há 3 meses, com\ndieta de estágio II, exercitando-se\nregularmente em programa de reabilitação cardíaca. Não fuma e\na pressão arterial é de 120/80 mmHg sob terapia com betabloqueador e AAS. Apresenta colesterol\ntotal = 240 mg/dl, HDL col. = 55 mg/dl, LDL col. = 165 mg/dl e triglicérides = 100 mg/dl. Sua\nconduta no tratamento desse paciente é:","options":{"A":"Recomendar dieta de estágio III.","B":"Iniciar sinvastatina, 20 mg/dia.","C":"Avaliar membros da família para descartar hipercolesterolemia familiar.","D":"Encaminhar a um especialista em lipídeos.","E":"Iniciar niacina, 2.000 mg/dia."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-251871","number":"251871","sourceNumber":"251871","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual dessas condutas não fazem parte do tratamento no atendimento inicial do infarto\nagudo do miocárdio:","options":{"A":"Aspirina.","B":"Beta-bloqueador.","C":"Morfina.","D":"Digitálico."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-251874","number":"251874","sourceNumber":"251874","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Não é contraindicação absoluta para uso de betabloqueador:","options":{"A":"Bloqueio atrioventricular de 3º grau.","B":"Pressão arterial sistólica menor que 80 mmHg.","C":"Frequência cardíaca de 49 batimentos por minuto.","D":"Asma."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-247161","number":"247161","sourceNumber":"247161","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 56 anos, com antecedentes de hipertensão e dislipidemia,\nprocura o ambulatório com dor torácica\nretroesternal tipo aperto que iniciou há cerca de dois\nmeses, de forma esporádica, durante suas caminhadas matinais, associada a períodos de aumento\nde intensidade do exercício. Os episódios de dor tinham duração de 5 minutos e melhoravam com\nrepouso. Há duas semanas refere que toda vez que caminha apresenta episódio de dor\ndesencadeada por esforço menor que o habitual. Assinale a alternativa CORRETA, que classifica a\ndor torácica apresentada pelo paciente.","options":{"A":"Angina típica e estável.","B":"Angina atípica e estável.","C":"Angina atípica e instável.","D":"Angina típica e instável.","E":"Angina de Prinzmetal."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182600","number":"182600","sourceNumber":"182600","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Correlacione CORRETAMENTE as características da dor torácica descritas abaixo com\nas respectivas doenças cardiovasculares. I. Dor\nretroesternal que irradia para a região cervical,\nmandíbula, epigástrio, ombros ou braços (mais comum do lado esquerdo), em opressão,\nqueimação, aperto ou peso, com duração menor do que 2-10 minutos, desencadeada pelo esforço,\nfrio ou \"stress\" emocional, aliviada pelo repouso. II. Dor que geralmente inicia sobre o esterno, ou\nem direção ao ápice cardíaco e pode irradiar-se para o pescoço ou ombro esquerdo, muitas vezes,\nmais localizada que a dor do infarto do miocárdio, tipo aguda em \"facada\", que pode durar muitas\nhoras até dias, pode alternar períodos de maior e menor intensidade, piora com a inspiração\nprofunda, rotação do tórax, ou posição supina, aliviada na posição supina, sentada ou com a\ninclinação anterior do tórax. III. Dor no tórax anterior, que pode irradiar-se para o dorso,\nlancinante\nem \"facada\", de início súbito, que geralmente ocorre na vigência de hipertensão ou em pacientes\ncom predisposição, como na síndrome de Marfan. IV. Dor subesternal ou localizada, pleurítica ou\nem opressão, de início súbito, com duração de minutos e menor do que 1 hora, que pode piorar\ncom a respiração. A. Pericardite; B. Angina pectoris; C. Embolia pulmonar; D. Dissecção aórtica.","options":{"A":"I-A, II-B, III-C e IV-D.","B":"I-B, II-A, III-D e IV-C.","C":"I-C, II-D, III-A e IV-B.","D":"I-D, II-C, III-B e IV-A."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183132","number":"183132","sourceNumber":"183132","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem hipertenso de 65 anos de idade chega a seu consultório devido a início recente\nde desconforto torácico, que você suspeita ser\nangina. A pressão arterial foi devidamente\ncontrolada com tiazídico e, agora, é de 150/96 mmHg. Qual das seguintes medicações é a menos\napropriada?","options":{"A":"Ácido acetilsalicilico.","B":"Betabloqueador.","C":"Nitrato sublingual.","D":"Diidropiridina de ação curta.","E":"Diltiazem."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-37100","number":"37100","sourceNumber":"37100","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O sinal de Homans está classicamente descrito:","options":{"A":"Na oclusão arterial crônica.","B":"Na oclusão arterial aguda.","C":"Na trombose venosa aguda.","D":"No linfedema.","E":"Na Síndrome de Leriche."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-29411","number":"29411","sourceNumber":"29411","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Púrpura Trombocitopênica (PTI) caracteriza-se por:","options":{"A":"desenvolvimento de anticorpos antiplaquetários, com preservação do quadro medular normal,\ncom aumento ou normalidade do setor megacariocítico.","B":"A relação de incidência mulher-homem é de 1:8.","C":"Na maioria dos casos de PTI crônica, o anticorpo é IgM.","D":"Hemartroses no exame físico.","E":"Tendência maior à cronificação quando incide na infância do que na idade adulta."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-343222","number":"343222","sourceNumber":"343222","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O teste de caminhada de 6 minutos (TC6min):","options":{"A":"Não é avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na\navaliação perioperatória.","B":"É avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes, em\npatologias crônicas, mas não na avaliação perioperatória.","C":"É avaliação validada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na avaliação\nperioperatória.","D":"É avaliação invalidada da reserva cardiorrespiratória em adultos de alto risco e não gestantes,\ntanto em patologias crônicas quanto na avaliação\nperioperatória."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-343223","number":"343223","sourceNumber":"343223","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O estabelecimento de intervalos de referência para o TC6min em mulheres grávidas\nsaudáveis:","options":{"A":"Não permite a avaliação individual da capacidade funcional e pode ajudar a personalizar os\nprogramas de exercícios.","B":"Permite a avaliação individual da capacidade funcional e pode ajudar a personalizar os\nprogramas de exercícios.","C":"Permite a avaliação individual da capacidade funcional, mas não pode ajudar a personalizar os\nprogramas de exercícios.","D":"Permite a avaliação individual da capacidade não funcional e pode ajudar a personalizar os\nprogramas de exercícios."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-314191","number":"314191","sourceNumber":"314191","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Podem acontecer resultados falso-positivos, em que a CK-MB é positiva e a troponina é\nnegativa em cerca de 4% dos pacientes. Sendo correto que:","options":{"A":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, deve-se basear a decisão clínica no resultado da CK-MB.","B":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, deve-se basear a decisão clínica no resultado da troponina.","C":"Nos casos em que a CK-MB está elevada e a troponina está anormal, ambas dentro de sua\njanela cinética, deve-se basear a decisão clínica nunca no resultado da troponina.","D":"Nos casos em que a CK-MB está elevada e a troponina está normal, ambas dentro de sua janela\ncinética, nunca se deve basear a decisão clínica no resultado da troponina."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-314195","number":"314195","sourceNumber":"314195","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Pacientes com dor torácica no setor de emergência, identificados como de risco baixo\nou intermediário, tem como adequado o item:","options":{"A":"Nunca podem ser submetidos ao teste ergométrico (TE), apesar do resultado normal confere\nrisco anual baixo de eventos cardiovasculares,\npermitindo a alta hospitalar mais precoce e segura.","B":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado anormal confere risco anual\nbaixo de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura.","C":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado normal confere risco anual\nbaixo de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura.","D":"Podem ser submetidos ao teste ergométrico (TE), cujo resultado normal confere risco anual\nelevado de eventos cardiovasculares, permitindo a alta hospitalar mais precoce e segura."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-314198","number":"314198","sourceNumber":"314198","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Comparada ao escore de cálcio, a angiotomografia de coronárias está de acordo com o\nitem correto:","options":{"A":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose luminal.","B":"É um exame que apresenta como desvantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose luminal.","C":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e não\nestimativas do grau de estenose luminal.","D":"É um exame que apresenta como vantagens a visualização de placas não calcificadas e\nestimativas do grau de estenose extra-luminal."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-314200","number":"314200","sourceNumber":"314200","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O uso da angiotomografia de coronárias apresenta claros benefícios, no item correto:","options":{"A":"Em pacientes assintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas.","B":"Em pacientes sintomáticos de baixo risco para DAC, na emergência, mas não no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas.","C":"Em pacientes sintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque não afasta a doença como causadora dos sintomas.","D":"Em pacientes sintomáticos de baixo risco para DAC, tanto na emergência como no âmbito\nambulatorial. Isso porque afasta a doença como causadora dos sintomas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-313474","number":"313474","sourceNumber":"313474","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à Síndrome Metabólica, Diabetes Mellitus e o Corolário Contínuo da\nDoença Arterial Coronária, pode-se considerar\nadequado que:","options":{"A":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que não contribuem\ndramaticamente para a progressão dos substratos fisiopatológicos\nda DAC.","B":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que contribuem pouco para a progressão dos substratos fisiopatológicos da DAC.","C":"A SM e o DM não compõem um espectro de doenças multissistêmicas, em particular do\nendotélio vascular, e que contribuem dramaticamente para a progressão dos substratos\nfisiopatológicos da DAC.","D":"A SM e o DM compõem um espectro de doenças multissistêmicas, em particular do endotélio\nvascular, e que contribuem dramaticamente para a progressão dos substratos fisiopatológicos da\nDAC."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278609","number":"278609","sourceNumber":"278609","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O critério eletrocardiográfico para IAMCST inclui elevação do segmento ST em duas\nderivações contíguas, sendo CORRETO de acordo com a Sociedade Brasileira de Cardiologia, a\nalternativa:","options":{"A":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 60 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações.","B":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações.","C":"Acima de 1,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 2 mm nas demais derivações.","D":"Acima de 2,5 mm em mulheres, acima de 2 mm em homens ? 40 anos e acima de 2,5mm em\nhomens < 40 anos nas derivações V2-V3 e/ou\nacima de 1 mm nas demais derivações."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-279030","number":"279030","sourceNumber":"279030","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica é o principal sintoma sugestivo de Síndrome Coronária Aguda (SCA) com\ncaracterísticas da dor torácica sugestivas de isquemia miocárdica. Sendo correto que:","options":{"A":"Pacientes com dor anginosa em repouso com mais de 60 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA.","B":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor não são sugestivas de SCA.","C":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de ambulatório\nde cardiologia, já que essas características da dor são sugestivas de SCA.","D":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278614","number":"278614","sourceNumber":"278614","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Os critérios para diagnóstico de IAM são aumento e/ou queda de marcadores de\nnecrose miocárdica, preferencialmente a\ntroponina, com pelo menos um valor acima do percentil 99\ndo método, indique o item correto:","options":{"A":"Associado a pelo menos duas das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","B":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) antigo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","C":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia ou em autópsia.","D":"Associado a pelo menos uma das seguintes alterações: sintomas sugestivos de isquemia, novas\nalterações do segmento ST, onda T ou Bloqueio de Ramo Esquerdo (BRE) novo, aparecimento de\nondas Q patológicas no ECG, exame de imagem com perda de miocárdio viável ou nova alteração\nna contratilidade segmentar e identificação de trombo intracoronário na angiografia exceto em\nautópsia."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278616","number":"278616","sourceNumber":"278616","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica pode não estar presente durante um episódio de SCA em até cerca de\num terço dos casos. Estes pacientes podem\napresentar dispneia isoladamente, náuseas, vômitos,\npalpitações, síncope, ou mesmo parada cardíaca. Podemos indicar como correto que:","options":{"A":"Sintomas denominados equivalentes não isquêmicos normalmente acometem idosos, mulheres\ne pacientes diabéticos.","B":"Sintomas denominados equivalentes isquêmicos normalmente acometem idosos, mulheres e\npacientes diabéticos.","C":"Sintomas denominados equivalentes isquêmicos nunca acometem idosos, mulheres e pacientes\ndiabéticos.","D":"Sintomas denominados equivalentes isquêmicos normalmente acometem somente pacientes\ndiabéticos."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278681","number":"278681","sourceNumber":"278681","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"No Brasil, país de dimensão continental e grande diversidade social e econômica,\ndentre as inúmeras barreiras ao acesso à\nReabilitação Cardiovascular - RCV, podemos assim\naceitar a alternativa abaixo como correta.","options":{"A":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, não são alternativas aos programas\ntradicionais, nos quais as sessões são sempre realizadas sob supervisão direta ou presencial.","B":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob\nsupervisão indireta, surgem como complemento ou alternativa\naos programas tradicionais, nos quais as sessões são sempre realizadas sob supervisão direta ou\npresencial.","C":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, surgem como complemento ou alternativa\naos programas tradicionais, nos quais as sessões são sempre realizadas sob supervisão indireta.","D":"Programas de Reabilitação Cardiovascular Domiciliar (RCVD), em que a maioria das sessões\nocorre no ambiente domiciliar sob supervisão\nindireta, surgem como complemento, mas nunca\ncomo uma alternativa aos programas tradicionais, nos quais as sessões são sempre realizadas sob\nsupervisão direta ou presencial."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-252879","number":"252879","sourceNumber":"252879","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 66 anos de idade, da entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde Diabetes Mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200x120mmHg, FC: 100bpm, SatO? 94%, IMC: 33Kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Diante do quadro, indique o diagnóstico mais adequado\npara este paciente nesse momento.","options":{"A":"Emergência hipertensiva associada a síndrome coronariana aguda sem supra de ST.","B":"Angina instável associada a pseudocrise hipertensiva, devido à dor.","C":"Urgência hipertensiva associada a infarto agudo do miocárdio sem supra de ST.","D":"Emergência hipertensiva associada a dissecção aguda de aorta."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-252880","number":"252880","sourceNumber":"252880","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 66 anos de idade, dá entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde diabetes mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200 x 120 mmHg, FC: 100 bpm, SatO? 94%, IMC: 33 kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Indique a conduta diagnóstica mais adequada nesse\ncaso.","options":{"A":"Teste ergométrico, dentro das próximas 6 horas.","B":"Cintilografia de perfusão miocárdica, dentro de 72 horas.","C":"Cineangiocoronariografia, nas próximas 48 horas.","D":"Cineangiocoronariografia, nos próximos 30 minutos."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-252881","number":"252881","sourceNumber":"252881","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 66 anos de idade, da entrada na UPA queixando-se de desconforto precordial\nem aperto, há cerca de três semanas,\ninicialmente aos grandes esforços e, nos últimos dias,\nmesmo aos pequenos esforços. No momento, queixa-se de dor grau 7/10 em repouso. É portador\nde Diabetes Mellitus tipo 2 e de hipertensão, em uso de metformina, losartana e ácido\nacetilsalicílico, além de tabagista de 20 anos/maço. Ao exame físico, encontra-se em regular estado\ngeral, com fácies de dor. PA: 200x120mmHg, FC: 100bpm, SatO? 94%, IMC: 33Kg/m². Ausculta\ncardiorrespiratória e exame abdominal sem alterações. Extremidades bem perfundidas, sem\nedemas, com pulsos simétricos. Realizado eletrocardiograma com achado de alterações da\nrepolarização ventricular em V1 a V3 e ondas T positivas e simétricas em V5 e V6. Marcadores de\nnecrose miocárdica da entrada negativos. Indique o tratamento farmacológico mais adequado para\nesse paciente.","options":{"A":"Ácido acetilsalicílico, clopidogrel, nitroglicerina, morfina, metoprolol, atorvastatina.","B":"Ácido acetilsalicílico, clopidogrel, nitroglicerina, heparina não fracionada, alteplase,\nmetoprolol.","C":"Clopidogrel, nitroprussiato de sódio, heparina não fracionada, abciximab, metoprolol,\natorvastatina.","D":"Ácido acetilsalicílico, nitroprussiato de sódio, morfina, heparina não fracionada, metoprolol,\nenalapril."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-249193","number":"249193","sourceNumber":"249193","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Nos pacientes com alto risco de sangramento e baixo risco isquêmico, deve-se\nintroduzir diretamente dupla terapia com anticoagulante e clopidogrel desde o início. Nesse\ncontexto, o item com erro é:","options":{"A":"Quando houver alto risco isquêmico e também alto risco hemorrágico, recomenda-se que se use\ntripla terapia por, no máximo, um mês ou inicie-se diretamente dupla terapia com anticoagulante e\nclopidogrel.","B":"O uso de inibidores de bombas de prótons como profilaxia de úlcera de estresse nesse grupo de\npacientes nunca deve ser considerado como primeira escolha devido ao risco elevado de\nsangramento gastrintestinal.","C":"A descontinuação do tratamento antiplaquetário deve ser considerada após 12 meses.","D":"A avaliação da necessidade de manutenção da anticoagulação e o cálculo do risco de\nsangramento devem ser realizados em todos os\npacientes através dos escores de CHA2DS2-VASc\ne HAS-BLED."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-249399","number":"249399","sourceNumber":"249399","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Escolar, sexo masculino, 8 anos, está frequentando a escolinha de futebol de areia do\nPelezão. A principal orientação durante a atividade física é hidratar com:","options":{"A":"Energéticos a cada 30 minutos.","B":"Isotônicos a cada 30 minutos.","C":"Água normal a cada 20 minutos.","D":"Guaraná com açaí a cada 30 minutos."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-249216","number":"249216","sourceNumber":"249216","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"Sintomas são as queixas apresentadas pelo paciente, relativas à doença. São dados subjetivos\ncomo dor de ouvido, dor de garganta, etc.","B":"Consideramos os sinais as queixas subjetivas apresentadas pelo paciente, aquilo que o paciente\nrefere e não são avaliados no exame\nfísico.","C":"Síndrome é definida como o conjunto de sinais e sintomas ligados a uma entidade mórbida que\nconsta no quadro geral de uma doença.","D":"É considerado sinal tudo que podemos avaliar no paciente através dos nossos sentidos."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215198","number":"215198","sourceNumber":"215198","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O estudo que comparou clopidogrel versus AAS em pacientes com risco de isquemia,\ntendo demonstrado uma redução significativa do\nnúmero total de readmissões para eventos\nisquêmicos. NÃO podemos, apenas, concordar que:","options":{"A":"Naqueles pacientes que apresentam alergia ao AAS ou intolerância gástrica, o clopidogrel pode\nser considerado uma alternativa.","B":"Redução de novas hospitalizações foi consistente em todos os resultados individuais de angina,\nataque isquêmico transitório, isquemia de membros e sangramento.","C":"Clopidogrel não resultou em diminuição em desfecho combinado de morte vascular, AVC, infarto\ndo miocárdio ou nova hospitalização para\neventos isquêmicos ou sangramento em comparação\ncom o AAS.","D":"Dessa forma clopidogrel pode ser usado como alternativa ao AAS em intolerantes."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215272","number":"215272","sourceNumber":"215272","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quanto à indicação da terapia antiplaquetária nos pacientes de muito alto risco,\nincluindo aqueles com Doença Aterosclerótica\nClínica (DACL) e eventos cardiovasculares prévios\n(prevenção secundária), o benefício é estabelecido em diversos estudos, o AAS (ou outro\nantiplaquetário):","options":{"A":"Foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","B":"Não foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","C":"Foi protetor na maioria dos pacientes com risco aumentado de eventos não vasculares, incluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias.","D":"Foi protetor na maioria dos pacientes com risco aumentado de eventos vasculares, excluindo\naqueles com IAM ou AVC isquêmico, bem como outras doenças vasculares prévias."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-212227","number":"212227","sourceNumber":"212227","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 58 anos, sexo feminino, portadora de hipertensão, dislipidemia e\nobesidade, evoluiu de forma súbita com quadro de\ndor torácica, em aperto, de forte intensidade,\nnáuseas e sudorese. Atendida imediatamente ao chegar ao hospital de emergência, realizou\neletrocardiograma e foi colhido o sangue para avaliação dos marcadores de necrose miocárdica.\nCardiologista avaliou o resultado do eletrocardiograma e a paciente foi diagnosticada com infarto\nagudo do miocárdio com supradesnível de ST (IAMST). As primeiras medidas terapêuticas foram\niniciadas e a reperfusão coronariana indicada. Uma das medidas terapêuticas na fase aguda do\nIAMST consiste em iniciar o inibidor da enzima conversora de angiotensina (IECA). Assinale a\nalternativa que apresenta uma contraindicação ao uso dos IECAS.","options":{"A":"Hemofilia.","B":"DPOC grave.","C":"Úlcera péptica em atividade.","D":"Estenose bilateral da artéria renal.","E":"Uso de inibidores da fosfodiesterase nas últimas 24 h."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-219902","number":"219902","sourceNumber":"219902","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 48 anos queixa-se de fraqueza generalizada e dispneia. Ao exame físico,\nausculta-se desdobramento da segunda bulha que é constante, mas aumenta quando o paciente\ninspira. O ritmo cardíaco é regular, a primeira bulha é normal e não há sopros. Qual das seguintes\nalterações eletrocardiográficas é MAIS COMPATÍVEL com os achados auscultatórios observados\nno paciente?","options":{"A":"Bloqueio completo do ramo direito do feixe de His.","B":"Elevação do segmento ST nas derivações anteriores.","C":"Redução da duração do intervalo PR.","D":"Repolarização precoce."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183029","number":"183029","sourceNumber":"183029","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em discussão com amigos nesse final de semana, você foi questionado sobre\ntreinamento de emergência para pessoal que\nnão fosse da saúde. Assim, explicou que a\nimportância da FV como mecanismo de óbito precoce e a habilidade na ressuscitação e na\ndesfibrilação foram os fatores que propiciaram o desenvolvimento de programas de tratamento\npré-hospitalar do IAM. Estando INCORRETO, apenas, que","options":{"A":"se estima que a desfibrilação salve cerca de seis vezes mais vidas que o tratamento\ntrombolítico, mas depende de sua rápida aplicação ao paciente.","B":"o impacto potencial, em termos de benefício, ao se intervir na fase pré-hospitalar no IAM,\nreforça\na necessidade de programas.","C":"identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma\nnova estratégia de grande difusão na população.","D":"fornecer maior informação à população quanto aos sintomas de IAM e a importância de uma\nbusca rápida por auxílio médico. Realizar\ntreinamento restrito, apenas à saúde, para atendimento\nde urgência nos moldes do BLS, a fim de evitar erros."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182733","number":"182733","sourceNumber":"182733","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A fisiopatologia do IAM perioperatório difere um pouco da do IAM espontâneo.\nConsiderando os Testes Não Invasivos para\nDetecção de Isquemia Miocárdica, o entendimento do\nEletrocardiograma de Esforço apenas NÃO é compatível com a seguinte alternativa.","options":{"A":"No IAM perioperatório, a ruptura de placa ocorre em aproximadamente 90% dos casos.","B":"No IAM perioperatório se dá, também, por um desequilíbrio prolongado entre a redução da oferta\nde oxigênio para o miocárdio (anemia, baixo\nfluxo etc.) e o aumento da demanda arterial\ncoronariana (taquicardia e hipertensão).","C":"O TE é uma ferramenta segura, útil e eficaz para a detecção de isquemia miocárdica, tendo\njustamente como mecanismo produzir este desbalanço entre oferta e demanda.","D":"A detecção de anormalidades durante sua execução dos testes de esforços possa ser\nreprodutível durante o perioperatório e seus variados níveis de estresse."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183053","number":"183053","sourceNumber":"183053","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Órgãos governamentais de saúde e o sistema privado de saúde suplementar devem\ncriar e manter um plano regional de\natendimento emergencial integrado de pacientes com IAMCST,\ncomo o já existente em vários países. Podemos apenas concordar que, as terapias recomendadas\nna fase pré-hospitalar","options":{"A":"são baseadas em estudos realizados em pacientes pré-hospitalares. Desse modo, deve ser feita\npor equipe capacitada e treinada.","B":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja diferente, a circunstância clínica é a mesma: IAM. Trata-se, desse modo, de\numa extrapolação coerente, que, naturalmente,\ndeve ser feita por equipe capacitada e treinada.","C":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja diferente, a circunstância clínica é a mesma: IAM. Trata-se, desse modo, de\numa extrapolação incoerente, que, naturalmente,\nnão deve ser feita por equipe capacitada e\ntreinada.","D":"são quase todas empíricas e baseadas em estudos realizados em pacientes hospitalizados.\n\nEmbora o cenário seja igual, a circunstância clínica é diferente do IAM. Trata-se, desse modo, de\numa extrapolação coerente, que, naturalmente, deve\nser feita por equipe capacitada e treinada."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182742","number":"182742","sourceNumber":"182742","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O Teste de Esforço TE é uma ferramenta segura, útil e eficaz para a detecção de\nisquemia miocárdica, tendo justamente como mecanismo produzir este desbalanço entre oferta e\ndemanda. Somente sendo INCORRETO que,","options":{"A":"assim, é razoável pensar que a detecção de anormalidades durante sua execução possa ser\nreprodutível durante o perioperatório e seus variados níveis de estresse.","B":"não há evidências de que usar esta estratégia para todos os pacientes resulte na redução de\neventos cardiovasculares perioperatórios.","C":"também deve se considerar que, quanto maior a prevalência da doença coronária em\ndeterminada população, menor será também o valor preditivo positivo do TE.","D":"considerando que o objetivo da estratificação do risco é reduzir o risco perioperatório, não\nseria\nlógica a realização do teste em uma população já estratificada como de baixo risco pelos algoritmos\nrecomendados."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183060","number":"183060","sourceNumber":"183060","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A administração de oxigênio é rotineira no atendimento a um paciente com IAM,\ngarantindo, assim, uma melhor chance de sobrevida aos pacientes. Somente podemos\nCONCORDAR que","options":{"A":"administração de oxigênio é indicada somente em pacientes com saturação de oxigênio < 90%,\ncongestão pulmonar ou na presença de desconforto respiratório.","B":"quando utilizada de forma necessária, a administração de oxigênio por tempo prolongado pode\ncausar vasoconstrição sistêmica, e aumento da\nresistência vascular sistêmica e da pressão arterial,\nreduzindo o débito cardíaco, sendo, portanto, prejudicial.","C":"quando utilizada de forma desnecessária, a administração de oxigênio por tempo prolongado\npode causar vasoconstrição sistêmica e aumento da\nresistência vascular sistêmica e da pressão\narterial, reduzindo o débito cardíaco, sendo, portanto, prejudicial.","D":"quando utilizada de forma desnecessária, a administração de oxigênio por tempo prolongado\npode causar vasoconstrição sistêmica e redução\nda resistência vascular sistêmica e da pressão\narterial, aumentando o débito cardíaco, sendo, portanto, prejudicial."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182749","number":"182749","sourceNumber":"182749","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A ecocardiografia sob estresse é precisa e segura em identificar pacientes com doença\narterial coronária, com importante papel como preditor de eventos cardíacos. Somente sendo\nINCORRETO que,","options":{"A":"as ecocardiografias sob estresse pela dobutamina e pelo exercício apresentam acurácia\ndiagnóstica semelhantes e superiores ao estresse com dipiridamol.","B":"caso um ecocardiograma sob estresse pela dobutamina demonstre isquemia residual no\npaciente com infarto prévio, o prognóstico é bom, e a probabilidade de reinfarto, morte e edema\nagudo pulmonar é baixa no período transoperatório de uma cirurgia não cardíaca.","C":"o uso da ecocardiografia sob estresse pela dobutamina na avaliação do risco perioperatório já\nestá bem documentado na literatura.","D":"comparando a cintilografia de perfusão miocárdica e a ecocardiografia sob estresse pela\ndobutamina na estratificação de risco vascular antes cirurgia, foi demonstrado que o valor\nprognóstico das anormalidades em ambas as modalidades de imagens para eventos isquêmicos\nperioperatórios é semelhante."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183067","number":"183067","sourceNumber":"183067","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O diagnóstico e a caracterização das regiões de IAM pela Ressonância Magnética\nCardiovascular RMC baseiam-se na técnica do\n\nrealce tardio. Podemos, apenas, concordar que","options":{"A":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-nfarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, não apenas na avaliação diagnóstica, mas também na\navaliação prognóstica dos pacientes.","B":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação diagnóstica.","C":"a capacidade de identificação da presença e da extensão das regiões de infarto, da presença ou\nnão de obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação prognóstica dos pacientes.","D":"a incapacidade de identificação da extensão das regiões de infarto, mas sim da presença ou não\nde obstrução microvascular, da área\nperi-infarto e da contratilidade regional faz da RMC uma\nferramenta cada vez mais importante, apenas na avaliação\n\ndiagnóstica, mas não na avaliação prognóstica dos pacientes."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182758","number":"182758","sourceNumber":"182758","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quando analisamos a Angiografia Coronária por Tomografia Computadorizada,\npodemos apenas CONCORDAR com o seguinte:","options":{"A":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes sem suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda.","B":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta baixa sensibilidade para a detecção\nde estenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda.","C":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, excluindo doença multiarterial e lesão em tronco de coronária esquerda.","D":"A angiotomografia (angio-TC) de coronárias tem sido utilizada de forma crescente na avaliação\nde pacientes com suspeita de coronariopatias. Ela\napresenta alta sensibilidade para a detecção de\nestenose coronariana, incluindo doença multiarterial e lesão em tronco de coronária esquerda."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182769","number":"182769","sourceNumber":"182769","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O aumento da sensibilidade dos kits disponíveis das troponinas propiciou uma maior\nacurácia e rapidez no diagnóstico ou não do IAM em pacientes com dor torácica na sala de\nemergência. Somente NÃO sendo correto que,","options":{"A":"no perioperatório de operações não cardíacas, as evidências científicas disponíveis não incluem\ntodas as troponinas (I e T) e nem todos os métodos utilizados para sua dosagem apresentam\nlimites de detecção e valores de referência diferentes.","B":"o limite de detecção significa o máximo valor que é detectado pelo método.","C":"o valor de referência da normalidade é determinado utilizando o percentil 99, que é obtido\nrealizando-se o exame em uma população normal e, significa que, 99% dos indivíduos normais\napresentam valores abaixo deste cut-off.","D":"os kits de troponina podem ser classificados em baixa (convencionais), média (contemporâneos\nou sensíveis) ou alta sensibilidade. Esta\nclassificação é baseada na porcentagem de indivíduos\nsaudáveis em que a troponina pode ser detectada."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182819","number":"182819","sourceNumber":"182819","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Na Pericardite, o processo inflamatório decorrente da epicardite subjacente nos\nventrículos é o responsável pelas seguintes alterações eletrocardiográficas, EXCETO","options":{"A":"pela onda T: na fase inicial, apresenta-se pouco aumentada e assimétrica.","B":"pela onda T: caracteristicamente não apresenta inversão enquanto ocorrem manifestações de\nelevação do ST.","C":"que pode apresentar inversão de T na fase crônica da doença, após a normalização do ST.","D":"quando esta ocorre inversão de T, raramente é profunda o suficiente para assemelhar-se ao\npadrão da onda T isquêmica."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182738","number":"182738","sourceNumber":"182738","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Amostra de sangue para avaliação do perfil lipídico deve ser obtida nas primeiras 24\nhoras da admissão de todos os pacientes com síndrome coronariana aguda (SCA). Sendo\nINADEQUADO, apenas, o seguinte:","options":{"A":"após este período, comumente ocorre aumento de TG e diminuição do LDL-C e do HDL-C,\nmodificações que podem permanecer por cerca de um a três meses.","B":"recomenda-se a instituição precoce do tratamento com altas doses de estatina entre o primeiro e\no quarto dia da SCA, preferencialmente\natorvastatina na dose 80 mg.","C":"pacientes indicados para intervenção percutânea e angioplastia podem experimentar benefício\nadicional quando a dose de estatina for administrada até 12 horas antes do procedimento.","D":"a dose de estatina apropriada para manter o LDL-C na meta terapêutica (< 100 mg/dl) deverá\nser mantida ."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183101","number":"183101","sourceNumber":"183101","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As doenças e as respostas inflamatórias do pericárdio podem ocorrer de distúrbios\ncomuns e incomuns. Das patologias citadas abaixo, qual não entra nas possíveis etiologias de\npericardite e derrame pericárdico?","options":{"A":"Artrite reumatóide.","B":"Granulomatose de Wegener.","C":"Diabetes insipidus.","D":"Hipotireoidismo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-187849","number":"187849","sourceNumber":"187849","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerando a terapia clinica do infarto agudo do miocárdio com\nsupra-desnivelamento do segmento-ST, assinale a alternativa ERRADA:","options":{"A":"O ácido acetilsalicílico deve ser utilizado com dose de ataque de 200mg a 300mg e o clopidogrel\ncom dose de ataque de 300mg a 600mg, não sendo\nnecessária a suspensão para execução da\ntrombólise.","B":"Os betabloqueadores reduzem o consumo miocárdico de oxigênio pela redução da frequência\ncardíaca, da pressão arterial e pela\ncontratilidade. Podem ser utilizados por via oral ou venosa,\ndevendo ser evitado na presença de sinais de choque.","C":"Os bloqueadores dos canais de cálcio, verapamil e diltiazem, podem ser utilizados em\nassociação aos betabloqueadores para melhor controlar a resposta ventricular de arritmias.","D":"Os inibidores da enzima conversora de angiotensina não devem ser utilizados em pacientes com\npressão sistólica menor que 100mmHg ou com redução de 30mmHg em relação ao valor basal"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182746","number":"182746","sourceNumber":"182746","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O sistema Renina-Angiotensina-Aldosterona (SRAA) desempenha um papel importante\nna fisiopatologia da IC, sendo INCORRETO apenas que:","options":{"A":"A ativação do sistema Renina-Angiotensina-Aldosterona (SRAA) piora o remodelamento.","B":"A inibição desse sistema leva à melhora da evolução dos pacientes com IC tanto em\nremodelamento, mas não em mortalidade.","C":"DM causa ativação do SRAA, com aumento de renina, angiotensina II e aldosterona.","D":"A importância do sistema adrenérgico na IC é conhecida e sua ativação piora o prognóstico dos\npacientes."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161318","number":"161318","sourceNumber":"161318","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino, 47 anos de idade, apresentou dor torácica em aperto\nacompanhado de mal-estar, diaforese e dispneia\nde início há duas horas, nessa manhã de\nsegunda-feira. Podemos assim determinar que:","options":{"A":"ácido acetilsalicílico é o único anti-inflamatório indicado rotineiramente para todos os\npacientes\ncom suspeita de IAM, eventualmente como\nautomedicação.","B":"pacientes com maior risco de doença coronária devem ser instruídos a tomar ácido\nacetilsalicílico (AAS) tamponado em\n\nsituações emergenciais.","C":"é o antiplaquetário de eleição a ser utilizado no IAM, tendo sido demonstrado que sua redução\nna mortalidade é muito menor que o da trombólise\nquímica.","D":"não tem ação sinérgica com o próprio fibrinolítico, levando à associação de ambos ao aumento\nda mortalidade."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161275","number":"161275","sourceNumber":"161275","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente procurou Pronto-socorro com intensa dor torácica e dispneia de início nesta\nmanhã. Refere ser hipertenso e tabagista. Seu ECG demonstra supra de segmento ST de 3 mm\nnas derivações D2 e D3. Marque a opção que NÃO influencia na mortalidade, nesse caso.","options":{"A":"Ausculta cardíaca.","B":"Ausculta pulmonar.","C":"Alterações à direita.","D":"Local da dor torácica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161325","number":"161325","sourceNumber":"161325","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A abordagem de pacientes acometidos por Insuficiência Coronariana Aguda deve\ncontemplar diversos tratamentos coadjuvantes a fim de melhorar o prognóstico da lesão em\nevolução. Sobre isso, assinale a alternativa CORRETA.","options":{"A":"A recomendação atual é de se utilizar o betabloqueador por via oral nas primeiras 24 horas.","B":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 50 batimentos por\nminutos.","C":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 70 batimentos por\nminutos.","D":"A utilização de betabloqueador endovenoso deve ser feita sem maiores critérios ou cuidados,\npois é pouco associada com\n\ncomplicações."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-158813","number":"158813","sourceNumber":"158813","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente J.T.A., 25 anos, sexo masculino, deu entrada na emergência com quadro de\ndispneia aos pequenos esforços, ascite e edema de membros inferiores. Ao exame físico: ausculta\npulmonar normal; avaliação cardiológica: ritmo cardíaco regular e um ruído diastólico mitral de\n\n+++/4+, definido como estalido protodiastólico (?Knock? pericárdico); Fc: 92bpm; PA: 110 x 60\nmmHg. Presença de turgência de jugular. Abdome: globoso, flácido, doloroso à palpação de\nhipocôndrio direito, sem sinais de irritação peritoneal. Piparote positivo. Fígado palpável 5 cm do\nrebordo costal direito. Extremidades: presença de edema (+/4+) em membros inferiores. Realizou\nraio-X de tórax que evidenciou área cardíaca normal e calcificação por todo o pericárdio, que\npermitiu realizar o diagnóstico de pericardite constritiva. No nosso meio, qual a principal causa de\npericardite constritiva?","options":{"A":"Tuberculose.","B":"Esclerodermia.","C":"Artrite reumatoide.","D":"Infarto agudo do miocárdio.","E":"Lúpus eritematoso sistêmico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161208","number":"161208","sourceNumber":"161208","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente foi atendido, no setor de emergência nesta manhã, de acordo com a última\natualização a respeito de IAM. Diante dessa situação, indique a opção CORRETA.","options":{"A":"É indicada administração de oxigênio rotineira em pacientes com saturação de oxigênio < 90%,\ncongestão pulmonar ou na presença de desconforto respiratório.","B":"A analgesia deve ser feita de preferência com sulfato de morfina endovenosa, exceto para\npacientes alérgicos a esse fármaco, na dose\ninicial de 2 a 8 mg (geralmente suficiente para aliviar a\ndor e a ansiedade). Com a monitorização da pressão arterial, essas doses podem ser repetidas em\nintervalos de 3 minutos.","C":"Os Anti-inflamatórios Não Esteroides (AINES) não devem ser utilizados na vigência de IAM e, se\no paciente que apresenta esse diagnóstico\nfizer uso crônico de AINES, este deve ser suspenso. O\núnico anti-inflamatório indicado rotineiramente para todos os pacientes com suspeita de IAM é o\nÁcido Acetilsalicílico.","D":"Nitratos podem ser utilizados somente na formulação sublingual (nitroglicerina, mononitrato de\nisossorbida ou dinitrato de isossorbida), para reversão de eventual espasmo e/ou para alívio da dor\nanginosa. Também estão recomendados para controle da hipertensão arterial ou alívio da\ncongestão pulmonar, se presentes."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161126","number":"161126","sourceNumber":"161126","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino, 59 anos de idade, internado, na sala de emergência do hospital\nonde você se encontra de plantão, com\ndiagnóstico de Insuficiência Coronariana. Ele apresentou,\nnovamente de madrugada, intensa dor torácica, sendo então solicitado que você o avaliasse\nnovamente. Diante de tal quadro clínico, aponte a conduta CORRETA.","options":{"A":"Tratamento da dor não diminui o consumo de oxigênio pelo miocárdio isquêmico, provocado pela\nativação do sistema nervoso simpático.","B":"A analgesia deve ser feita de preferência com sulfato de morfina oral, exceto para pacientes\nalérgicos a esse fármaco, na dose inicial\nde 2 a 8 mg (geralmente suficiente para aliviar a dor e a\nansiedade). Com a monitorização da pressão arterial, essas doses podem ser repetidas em\nintervalos de 5 a 15 minutos.","C":"Analgesia com morfina pode ser substituído pelo sulfato de Meperidina.","D":"Alguns estudos iniciais sugerem que a atividade dos novos antiplaquetários, prasugrel e\nticagrelor, tenham sua atividade aumentada em pacientes que receberam morfina."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161136","number":"161136","sourceNumber":"161136","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Logo ao chegar ao Hospital, você foi solicitado para avaliar um paciente que já estava\ninternado há 5 dias com diagnóstico de Infarto Agudo do Miocárdio; já havia sido liberado da\nUnidade Coronariana, mas como apresentava ainda dificuldade de controle da Pressão Arterial,\nnecessitava de constante intervenção, mesmo estando na enfermaria. Relacionado a essa\nsituação, aponte a alternativa contendo a conduta CORRETA.","options":{"A":"Nitratos não podem ser utilizados na formulação sublingual (nitroglicerina, mononitrato de\nisossorbida ou dinitrato de isossorbida)\npara reversão de eventual espasmo e/ou para alívio da dor\nanginosa, nesse caso somente venosos.","B":"Nitratos estão recomendados para controle da hipertensão arterial ou alívio da congestão\npulmonar, se presentes.","C":"Estão contraindicados (nitratos) na presença de hipotensão arterial (Pressão Arterial Sistólica\n?\n\nPAS < 110 mmHg).","D":"Estão contraindicados (nitratos) quando houver suspeita de comprometimento de Parede\nInferior."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152657","number":"152657","sourceNumber":"152657","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A angina pectoris instável é conhecida como angina de:","options":{"A":"Korotkoff.","B":"Prinzmetal.","C":"Simmers.","D":"Blomberg.","E":"NDA."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161400","number":"161400","sourceNumber":"161400","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentro da análise estatística e epidemiológica das relações da sobreposição de\ndoenças como o Diabetes, a Hipertensão Arterial e\na Arteriosclerose, aponte a alternativa\nINCORRETA.","options":{"A":"A frequência de hipertensão mascarada pode ser maior no DM do que em indivíduos sem DM, e\na incidência de desfechos cardiovasculares é\nmaior nesses pacientes, quando não tratados.","B":"A apresentação clínica da DAC pode ser de dor anginosa típica ou atípica, mas a ausência de\nsintomas é muito raro.","C":"Além disso, a DAC nesses pacientes tem pior prognóstico, com menor sobrevida em curto\nprazo, maior risco de recorrência e pior resposta aos tratamentos propostos.","D":"A letalidade do Infarto Agudo do Miocárdio (IAM) em pacientes com DM é duas vezes maior do\nque naqueles sem DM, em razão da maior\nfrequência de complicações como IC, reinfarto e morte\nsúbita."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161194","number":"161194","sourceNumber":"161194","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O impacto estatístico de um Eletrocardiograma (ECG), executado no local de\natendimento inicial do Infarto Agudo do\nMiocárdio (IAM) e interpretado por um médico habilitado (no\nlocal ou em local remoto), mostrou ser um método que","options":{"A":"reduz em 70% o tempo porta-agulha.","B":"reduz em 50% o tempo porta-balão.","C":"proporciona menores taxas de tempo porta-balão ideal.","D":"leva a tendência à redução de mortalidade intra-hospitalar em pacientes com IAMCST."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161412","number":"161412","sourceNumber":"161412","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Existem razões pelas quais se devem desenvolver uma estratégia preventiva para a\nprática clínica, promovendo a reabilitação cardiovascular. Aponte a alternativa INCORRETA\nreferente a esse caso.","options":{"A":"A aterosclerose se desenvolve de forma insidiosa durante décadas e suas manifestações\nclínicas só se fazem notar nos estágios avançados da\ndoença.","B":"Em sua maior parte, as DCVs possuem uma estreita relação com estilo de vida, assim como\ncom fatores fisiológicos e bioquímicos não\nmodificáveis.","C":"As modificações dos fatores de risco, promovidas pela RCV, reduzem a morbimortalidade por\nDCV, sobretudo para os indivíduos classificados como de alto risco.","D":"A carga das DCVs tem crescido nas últimas décadas, paralelamente ao incremento da\nprevalência de fatores de risco."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-110535","number":"110535","sourceNumber":"110535","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A PTI aguda na infância caracteriza-se por apresentar:","options":{"A":"plaquetopenia severa acompanhada de quadro hemorrágico grave que evolui geralmente a\nóbito;","B":"plaquetopenia severa com ausência de megacariócitos na medula óssea;","C":"plaquetas normais em quantidade, mas funcionalmente deficientes;","D":"plaquetopenia aguda, de início abrupto, que geralmente evolui para cura espontânea;","E":"plaquetopenia com disfunção plaquetária."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109733","number":"109733","sourceNumber":"109733","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com relação à Trombocitopenia Induzida pela Heparina (TIH), assinale a alternativa\nCORRETA:","options":{"A":"A incidência de TIH independe do tipo de heparina utilizada.","B":"A TIH pode se manifestar clinicamente com trombose venosa profunda.","C":"A TIH ocorre, geralmente, meses após o uso de heparina.","D":"A TIH cursa com níveis extremamente baixos de plaquetas."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-86655","number":"86655","sourceNumber":"86655","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As afirmativas abaixo referem-se ao uso de hemotransfusão em pacientes com perda\nsanguínea elevada. I ? A infusão de concentrado de hemácias em alta velocidade e em grande\nquantidade pode ter como complicação uma coagulopatia maciça; II ? A infusão de concentrado de\nhemácias em alta velocidade e grande quantidade pode levar o paciente a ter uma arritmia por\nhipocalcemia; III ? A infusão de concentrado de hemácias em alta velocidade pode ter como\ncomplicação hipomagnesemia grave.","options":{"A":"Apenas afirmativa III está correta.","B":"Apenas afirmativa II está correta.","C":"Apenas afirmativas II e III estão corretas.","D":"Apenas afirmativas I e II estão corretas.","E":"Todas as afirmativas estão erradas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-86859","number":"86859","sourceNumber":"86859","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Criança com dois meses apresentou hematoma local após ter recebido a vacina DPT. A\nmãe relata sangramento prolongado após queda do coto umbilical. Exames: Hemoglobina 11 g/dl,\nleucócitos normais e plaquetas 480.000/mm3 , TAP 90% e TTPA alargado e tempo de\nsangramento 7 segundos. O provável diagnóstico é","options":{"A":"Hemofilia B;","B":"Deficiência do fator Von Willebrand;","C":"Deficiência do fator V ;","D":"Hemofilia A;","E":"Leucemia linfoide aguda."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-286704","number":"286704","sourceNumber":"286704","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação a Hipertensão arterial em situações especiais, é CORRETO afirmar:","options":{"A":"A pressão arterial na criança deve ser aferida em todas as consultas nas crianças acima de 3\nanos.","B":"A pressão arterial na criança deve ser aferida em todas as consultas nas crianças acima de 5\nanos.","C":"No obeso e com mais de 50cm de circunferência do braço deve-se aferir a pressão arterial com\naparelho automático de punho.","D":"No idoso sempre nas aferições não devo me preocupar com o hiato auscultatório."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-176046","number":"176046","sourceNumber":"176046","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 65 anos, tabagista, sedentário e obeso, chega no pronto-socorro em 28 de\nagosto com dor precordial típica. Seu ECG na admissão revelou supradesnivelamento do seg ST\nde 0,3 mV em V4R, V5R e V6R. Neste cenário, qual o diagnóstico e tratamento imediato? Escolha\ndentre as opções abaixo:","options":{"A":"Infarto de ventrículo direito e o tratamento deve ser feito com expansão de volume.","B":"Infarto de ventrículo direito e o tratamento deve ser feito com nitrato endovenoso.","C":"Infarto de parede anterior localizada e tratamento com betabloqueadores endovenosos.","D":"Infarto de parede anterosseptal e tratamento com betabloqueadores endovenosos."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-87392","number":"87392","sourceNumber":"87392","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente se apresenta com anemia hemolítica microangiopática, insuficiência renal\naguda, febre, alteração neurológica e\ntrombocitopenia. A doença que pode explicar este quadro é:","options":{"A":"Nefrite lúpica.","B":"Granulomatose de Wegener.","C":"Púrpura trombocitopênica trombótica.","D":"Amiloidose secundária.","E":"Púrpura trombocitopênica idiopática."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-61515","number":"61515","sourceNumber":"61515","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 30 anos procura o pronto-socorro devido à epistaxe e gengivorragia.\nReferindo também lesões avermelhadas puntiformes\nem membros inferiores há mais de 6 meses.\nNega comorbidades e infecções prévias. Apresenta-se em bom estado geral, afebril, estável\nhemodinamicamente, com petéquias em membros inferiores, não apresentando lesões de\ncontinuidade na mucosa nasal ou na cavidade oral. Observam-se vesículas hemorrágicas em\nmucosa jugal. Exame cardiorrespiratório normal e abdome com ausência de visceromegalia.\n\nHemograma evidenciou trombocitopenia isolada de 30.000 mm³. Qual a hipótese diagnóstica e\nconduta terapêutica?","options":{"A":"Lúpus eritematoso sistêmico e azatioprina.","B":"Púrpura trombocitopênica idiopática e corticoterapia oral.","C":"Leucemia linfocítica crônica e encaminhar para quimioterapia.","D":"Púrpura trombocitopênica idiopática e transfusão de plaquetas.","E":"Púrpura trombocitopênica idiopática e pulsoterapia metilprednisolona."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-46694","number":"46694","sourceNumber":"46694","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Analise as afirmativas quanto às Hemofilias e assinale a CORRETA:","options":{"A":"A hemofilia B apresenta hereditariedade, quadro clínico e classificação idêntica ao da hemofilia\nA, da qual difere quanto ao fator plasmático\ndeficiente.","B":"Os sangramentos decorrem por defeitos na hemostasia primária.","C":"São coagulopatias hereditárias de herança dominante ligada ao cromossomo Y, porém 30 a\n40% não têm história familiar e não há diferenças raciais.","D":"Quando o nível plasmático do fator deficiente é > 10% não há manifestações hemorrágicas.","E":"Há de se pesquisar história de sangramentos nos indivíduos do sexo masculino na família\npaterna."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-34135","number":"34135","sourceNumber":"34135","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual fator da coagulação é dependente da Vitamina K?","options":{"A":"III.","B":"VIII.","C":"X.","D":"I.","E":"XI."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-26477","number":"26477","sourceNumber":"26477","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Lactente de 12 meses, sexo masculino, apresenta subitamente hemartrose de joelho\nesquerdo. Pais negam febre, estado geral excelente e não há outras alterações ao exame físico.\nQual exame complementar pode auxiliar no diagnóstico?","options":{"A":"Hemograma.","B":"Tempo de Tromboplastina Parcial ativado (PTT).","C":"Tempo de sangramento.","D":"Contagem de plaquetas.","E":"Prova do laço."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-62831","number":"62831","sourceNumber":"62831","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente idosa, desnutrida, com sangramento de mucosa bucal e petéquias com\ndistribuição perifolicular, principalmente em membros inferiores, tem como principal suspeita:","options":{"A":"amiloidose.","B":"Síndrome de Kasabach-Merritt.","C":"macroglobulinemia de Waldenstrom.","D":"escorbuto.","E":"crioglobulinemia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-49344","number":"49344","sourceNumber":"49344","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente no quinto dia pós-operatório de cirurgia bariátrica, evolui com embolia\npulmonar maciça e choque circulatório obstrutivo.\nA conduda correta indicada, nesse caso, deve\nser:","options":{"A":"administrar fibrinolítico endovenoso.","B":"implantar filtro de veia cava.","C":"administrar anticoagulação plena com heparina não fracionada.","D":"administrar anticoagulação plena com heparina de baixo peso molecular.","E":"administrar anticoagulação oral com cumarinico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-49396","number":"49396","sourceNumber":"49396","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, quatro anos de idade, apresenta queixa de sangramento nasal em episódios\nagudos, sem febre ou dor. Fez uso de vacina tríplice viral há quatro semanas. Ao exame físico,\nnota-se bom estado geral, eutrófico, presença de petéquias em abdome e MMII. Ausculta\ncardiopulmonar normal. Abdome plano sem visceromegalias. Exames laboratoriais mostram\nhemograma com anemia, plaquetas: 50000/mm³. Presença de macroplaquetas no sangue\nperiférico. Mielograma com o setor megacariocítico hiperplasiado. Sumário de urina com hemácias\n\n+. O diagnóstico mais provável é:","options":{"A":"leucemia mieloide aguda.","B":"púrpura trombocitopênica imune.","C":"hiperesplenismo.","D":"calazar.","E":"dengue hemorrágica."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-34934","number":"34934","sourceNumber":"34934","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 3 anos de idade, apresenta história de sangramento nasal em episódios\nrepetidos há três dias, sem febre ou dor. Nos\nantecedentes, a genitora refere um resfriado há duas\nsemanas. Ao exame, bom estado geral, presença de petéquias em abdome e MMII. Ausculta\ncardiopulmonar normal. Abdome plano sem visceromegalias. Hemograma com anemia discreta\nnormocítica hipocrômica, plaquetas de 50000/mm³. Presença de macroplaquetas no sangue\nperiférico. Mielograma com o setor megacariocítico hiperplasiado. A suspeita diagnóstica mais\nprovável é de:","options":{"A":"leucemia linfocítica aguda.","B":"púrpura trombocitopênica imune.","C":"dengue hemorrágico.","D":"CIVD.","E":"púrpura de Henoch-Schönlein."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-34938","number":"34938","sourceNumber":"34938","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 3 anos de idade, apresenta história de sangramento nasal em episódios\nrepetidos há três dias, sem febre ou dor. Nos\nantecedentes, a genitora refere um resfriado há duas\nsemanas. Ao exame, bom estado geral, presença de petéquias em abdome e MMII. Ausculta\ncardiopulmonar normal. Abdome plano sem visceromegalias. Hemograma com anemia discreta\nnormocítica hipocrômica, plaquetas de 50000/mm³. Presença de macroplaquetas no sangue\nperiférico. Mielograma com o setor megacariocítico hiperplasiado. Em relação a essa patologia, é\nincorreto afirmar:","options":{"A":"Os corticoides e a imunoglobulina são os alicerces da terapia medicamentosa e essas\nindicações dependem da condição clínica do paciente.","B":"Crianças que têm contagem de plaquetas > 30000/mm³ e são assintomáticas ou têm pouco\nsangramento não requerem tratamento de rotina.","C":"As plaquetas são revestidas com anticorpos para antígenos de membrana das plaquetas,\nresultando em sequestro esplênico e fagocitose por macrófagos mononucleares.","D":"A maioria dos casos são graves e ocasionam complicações severas.","E":"O diagnóstico é clínico e de exclusão."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-281902","number":"281902","sourceNumber":"281902","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Além de esfigmomanômetros e estetoscópios, há vários recursos disponíveis, como\ncardiofrequencímetros e aplicativos de celulares para monitoramento da frequência cardíaca (FC),\nglicosímetros e oxímetros digitais na Reabilitação Cardiovascular. Sendo correto que:","options":{"A":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares favoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e durante o exercício.","B":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e durante o exercício.","C":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, não\né desejável o monitoramento\neletrocardiográfico no repouso e durante o exercício.","D":"Dependendo da complexidade clínica e do risco de eventos cardiovasculares desfavoráveis, é\ndesejável o monitoramento eletrocardiográfico no repouso e nunca durante o exercício."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-249968","number":"249968","sourceNumber":"249968","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre o risco de trombose de stent em pacientes que foram submetidos à ICP com\nstents convencionais nos primeiros dias e semanas\napós o procedimento, podemos concordar que:","options":{"A":"Uma dupla Antiagregação Plaquetária é recomendada por um semestre.","B":"Os stents convencionais foram reservados, idealmente, para os pacientes com risco muito alto\nde sangramento e que necessitam de um período mais curto (ao menos um mês) de dupla\nAntiagregação.","C":"No Brasil, o stent convencional metálico não é utilizado principalmente em serviços públicos.","D":"Trombose de stent em pacientes com stents metálicos é muito mais raro nos primeiros dias e\nsemanas após o procedimento."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157706","number":"157706","sourceNumber":"157706","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Aponte a alternativa que contém a principal causa de coagulação intravascular\ndisseminada na gestação.","options":{"A":"Placenta prévia.","B":"Descolamento prematuro de placenta.","C":"Polidramnia severa.","D":"Aborto infectado."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157668","number":"157668","sourceNumber":"157668","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Idoso, 68 anos de idade, procura hospital com quadro de dor torácica, provavelmente\ncardiogênica, possuindo algumas características que não são compatíveis com insuficiência\ncoronária. Ao ser realizado eletrocardiograma, foram encontradas alterações de repolarização\nventricular causada por patologias não isquêmicas, que podem ser exemplificados pelas opções\nseguintes, com EXCEÇÃO de uma delas. Indique-a:","options":{"A":"Supradesnivelamento do segmento ST em todas as derivações no caso da pericardite.","B":"Inversão de ondas T no caso de embolia pulmonar.","C":"Aumento de amplitude de ondas no caso de derrame pericárdico.","D":"Ondas T gigantes causadas por hipercalemia."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-111826","number":"111826","sourceNumber":"111826","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"No intraoperatório de um paciente que recebeu grande volume de infusão sanguínea, o\ncirurgião percebe que por diversos pontos começam a ?brotar? sangue. Essa hemorragia tem,\nneste caso, como causas principais:","options":{"A":"Trombocitopenia de diluição, falta de fatores de coagulação, coagulação intravascular\ndisseminada e uremia.","B":"Trombocitopenia de diluição, falta de fatores de coagulação, coagulação intravascular\ndisseminada e reação hemolítica.","C":"Uremia, falta de fatores de coagulação, coagulação intravascular disseminada e reação\nhemolítica.","D":"Reação hemolítica, falta de fatores de coagulação e uremia."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-350876","number":"350876","sourceNumber":"350876","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 67 anos, masculino, procurou atendimento na UPA devido quadro de dor\ntorácica iniciado há 2 horas, descreve a dor como sensação de mal-estar, não conseguindo definir\num local específico do peito, associado à sensação de queimação, com irradiação para membro\nsuperior esquerdo e sudorese. Refere que a dor se iniciou após retirar o lixo de seu domicílio,\ncomeçando de maneira leve, porém, devido a piora da dor, procurou atendimento. Faz\nacompanhamento na UBS devido quadro de hipertensão arterial e Diabetes Mellitus, em uso\nirregular de insulina NPH, enalapril e alopurinol. Fuma 01 carteira de cigarros por dia, desde os 15\nanos de idade. Ao exame físico, consciente, orientado, sudoreico, pálido, com fácies de dor, PA\n120x80 mmHg em ambos os membros, FC 90 bpm, f 16 irpm, SpO? 94% em ar ambiente. Ausculta\ncardíaca e pulmonar normais. Abdome flácido. Pulsos periféricos simétricos e palpáveis. Devido\nquadro de dor, foi medicado com morfina venosa, com melhora dos sintomas, além de realizar o\nECG a seguir. Dentro do contexto do caso, assinale o item que demonstra o melhor planejamento\ndiagnóstico nesse momento.","options":{"A":"Solicitar dosagem de CK-MB e mioglobina.","B":"Realizar ECG e dosagem de troponinas de maneira seriada.","C":"Realizar ECG apenas na chegada e solicitar dosagem de TGO, LDH e CK-MB.","D":"Transferir paciente para tratamento invasivo percutâneo (cateterismo) de imediato."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-199702","number":"199702","sourceNumber":"199702","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 52 anos, piloto de aviação comercial, chega ao consultório para avaliar\nquadro de dor torácica. O quadro iniciou há\n3 meses, se caracteriza por dor retroesternal, em\naperto, que surge geralmente quando está caminhando em esteira, na academia. Necessita parar a\natividade e a dor cede em cerca de 3 minutos. O quadro está estável desde o início. É portador de\nhipertensão arterial sistêmica e tabagista. Usa olmesartana. Tem irmão falecido por infarto aos 50\nanos. Traz radiografia de tórax normal e tem eletrocardiograma com bloqueio de ramo esquerdo.\n\nNo exame físico, a pressão arterial é 140 x 90 mmHg. Qual dos testes abaixo é o mais adequado\npara esse paciente?","options":{"A":"Coronariografia.","B":"Teste ergométrico.","C":"Ecocardiograma de estresse com dipiridamol.","D":"Escore de cálcio pela tomografia computadorizada."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-172990","number":"172990","sourceNumber":"172990","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente feminina, 45 anos, portadora de hipertensão arterial, ex-tabagista, procura\nambulatório com queixa de dor torácica\nprecordial em queimação, que irradia para pescoço. Refere\nque a dor aparece ao esforço moderado nos últimos 3 meses, dura em torno de 5 minutos e\nmelhora espontaneamente. Realizou o seguinte eletrocardiograma: Qual exame deve ser realizado\ncomo próximo passo na investigação?","options":{"A":"Teste ergométrico.","B":"Tomografia coronária com escore de cálcio.","C":"Cateterismo com coronariografia diagnóstica.","D":"Cintilografia miocárdica de estresse farmacológico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-150883","number":"150883","sourceNumber":"150883","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 65 anos, com dor precordial que irradia para mandíbula, associada a\nnáuseas e diaforese, de início há 30\nminutos. Filho refere que o paciente já apresentara dor de\ncaráter semelhante há 2 semanas. É portador de hipertensão arterial sistêmica, diabetes mellitus e\ndislipidemia, tomando medicações prescritas de forma irregular. Realizou o seguinte\neletrocardiograma na entrada: (VER IMAGEM) Evoluiu com sinais de hipotensão, congestão\npulmonar e má perfusão periférica. Qual a conduta a ser realizada no momento, além do controle\nhemodinâmico, uso de dupla antiagregação plaquetária e anticoagulante parenteral?","options":{"A":"Trombolítico.","B":"Intervenção coronária percutânea.","C":"Cirurgia de revascularização do miocárdio.","D":"Tratamento clínico e teste provocativo de isquemia."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-126943","number":"126943","sourceNumber":"126943","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 55 anos, paraplégico por acidente automobilístico há 15 anos, é\ninternado por pneumonia adquirida na comunidade. Está no oitavo dia de internamento hospitalar\n(DIH), com boa resposta ao antibiótico endovenoso, quando foi observado edema isolado de\nperna esquerda. Ultrassonografia com doppler evidenciou trombose venosa profunda na perna\nedemaciada, mesmo com uso diário de enoxaparina 40mg via SC. Os exames da admissão\nmostravam plaquetas: 300.000/mm3. O exame de hoje (8º DIH) evidencia plaquetas: 60.000/mm3.\nPaciente não fez uso de quaisquer medicamentos nos 12 meses prévios ao internamento.\n\nQual conduta deve ser adotada nesse momento?","options":{"A":"Suspender enoxaparina e iniciar warfarin.","B":"Trocar enoxaparina por fondoparinux.","C":"Manter enoxaparina em 1mg/kg de peso 2x/dia.","D":"Trocar enoxaparina por heparina não fracionada."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-81249","number":"81249","sourceNumber":"81249","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, diabético e hipertenso, comparece ao\n\npronto-socorro com uma hora de dor precordial constritiva com irradiação para o membro superior\nesquerdo. Encontra-se ansioso e sudoreico. Realizado ECG com imagem. (VER IMAGEM) Qual o\nmelhor tipo de tratamento para esse paciente?","options":{"A":"Cardioversão elétrica, sob sedação.","B":"Intervenção percutânea coronariana imediata.","C":"Administração de ativador de plasminogênio tecidual.","D":"Amiodarona em bolus, seguida de administração intravenosa contínua."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-65758","number":"65758","sourceNumber":"65758","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 23 anos sofreu ferimento por arma branca na fossa antecubital direita.\nFoi socorrido por populares e levado a uma\nemergência com o relato de que, durante o transporte,\nhouve grande perda de sangue em jato pela ferida. No momento do atendimento inicial, foi notado\nferimento na artéria braquial, prontamente controlado. No entanto, o paciente persistiu com\nsangramento profuso pelos bordos da ferida, sugerindo uma coagulopatia aguda. Com base no\ncaso descrito, qual dos seguintes fatores é determinante na indução de coagulopatia por meio de\nativação sistêmica das vias fibrinolítica e anticoagulante?","options":{"A":"Choque.","B":"Acidose.","C":"Anemia.","D":"Hipotermia.","E":"Diluição dos fatores de coagulação."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-36988","number":"36988","sourceNumber":"36988","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 45 anos, internado há 10 dias por fratura complexa de fêmur. Está em uso\nde Heparina não fracionada (Heparina sódica)\npara profilaxia de Trombose Venosa Profunda desde\no início do internamento. Seus exames iniciais revelam Hb = 12,4 g/dl, Leucócitos = 12.350/mm³ e\nPlaquetas 190.000/mm³. No décimo dia do internamento, um novo hemograma mostrou Hb = 9,5\ng/dl, Leucócitos = 7.200/mm³ e Plaquetas = 65.000/mm³. Não há sangramentos nem sinais de\ntrombose venosa. Além de suspender o uso de heparina o que mais deve ser feito?","options":{"A":"Iniciar argatroban.","B":"Transfundir plaquetas.","C":"Associar prednisona.","D":"Iniciar warfarina."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-37031","number":"37031","sourceNumber":"37031","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Recém-nascido com 4 dias de vida, nascido em seu próprio domicílio, sem assistência\nperinatal, começou a apresentar sangramento\npelo coto umbilical. Desde o nascimento vem sendo\nalimentado exclusivamente no seio. O achado laboratorial mais provável é de:","options":{"A":"contagem de plaquetas diminuídas.","B":"tempo de protrombina prolongado.","C":"fibrinogênio aumentado.","D":"fator V diminuído."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-30938","number":"30938","sourceNumber":"30938","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente sexo feminino, 23 anos, é atendida com queixas de pintas vermelhas na pele.\nAo exame, foram identificadas petéquias.\nRefere virose há 15 dias sem qualquer repercussão\nclínica significativa. O hemograma apresentava Hb = 14 g/dl, leucócitos = 6.400/mm³ (2% bastões,\n78% segmentados e 20% de linfócitos), plaquetas = 13.000/mm³. O melhor diagnóstico clínico é de:","options":{"A":"Leucemia aguda.","B":"Púrpura trombocitopênica trombótica (PTT).","C":"Dengue hemorrágica.","D":"Púrpura trombocitopênica idiopática (PTI).","E":"Plaquetopenia secundária ao HIV."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-27695","number":"27695","sourceNumber":"27695","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 70 anos, sexo feminino, procura atendimento por sangramento gengival\napós extração dentária. Refere que, pela segunda\nvez em dois meses, apresentou o referido fato\napesar de compressas geladas e aplicação com compressão do local por até 4 horas. Não faz uso\nde quaisquer medicamentos. Realizou alguns exames que evidenciaram: tempo de protrombina\nnormal, tempo de tromboplastina parcial ativada = 50s (normal de 20 a 35s), hemograma normal.\nEletrólitos e provas de função hepática, tireoidiana e renal estavam normais. Com base nestes\ndados, qual o diagnóstico, entre os abaixo, mais provável para esta paciente?","options":{"A":"Deficiência de Fator VII.","B":"Deficiência de Vitamina K.","C":"Deficiência de Fator V.","D":"Doença de von Willebrand.","E":"Deficiência de Fator X."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-27720","number":"27720","sourceNumber":"27720","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 79 anos, sexo masculino, foi internado por pneumonia comunitária em uma\nenfermaria de hospital secundário. Com base nos dados obtidos na admissão, foi considerado\ncomo de risco moderado para embolia pulmonar, sendo anticoagulado com enoxaparina 60 mg SC\n12/12h e solicitada TC helicoidal de tórax, que foi realizada no dia seguinte. Após saber que o\nresultado deste último exame foi normal, qual dos itens abaixo representa a conduta mais\nadequada?","options":{"A":"Manter enoxaparina da mesma forma e iniciar anticoagulação oral.","B":"Suspender totalmente a enoxaparina.","C":"Reduzir enoxaparina para 40 mg SC 1x/dia.","D":"Manter enoxaparina da mesma forma e solicitar angiografia pulmonar.","E":"Manter enoxaparina da mesma forma e solicitar cintilografia pulmonar."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-29487","number":"29487","sourceNumber":"29487","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Testemunha de Jeová, em internamento hospitalar, com hemopatia grave, não\nconsente a realização de transfusão de sangue sob hipótese alguma, pede alta depois do\ndiagnóstico e, no momento da elaboração do termo da alta, sangra copiosamente, com risco\niminente de vida. Atitude a ser esperada do médico assistente:","options":{"A":"Continuar os procedimentos normais da alta hospitalar;","B":"Deixar o paciente chocar e morrer no leito hospitalar;","C":"Contactar o chefe da sua seita religiosa para que venha ajudar a resolver o problema;","D":"Realizar sem demora a transfusão preconizada."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-17825","number":"17825","sourceNumber":"17825","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale o distúrbio eletrolítico mais frequentemente associado à alcalose metabólica\nprolongada.","options":{"A":"Hipocalcemia","B":"Hipocalemia","C":"Hiponatremia","D":"Hipocloremia","E":"Hipomagnesemia"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-349738","number":"349738","sourceNumber":"349738","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação ao uso de trombolíticos em paciente com infarto agudo do miocárdio com\nsupra de ST no eletrocardiograma, é considerado(a) contraindicação absoluta","options":{"A":"uso crônico de AAS 100 mg diário.","B":"trauma cranioencefálico importante nos últimos 3 meses.","C":"histórico de úlcera péptica mesmo sem evidência de sangramento ativo.","D":"acidente vascular encefálico isquêmico há 1 ano.","E":"gestação."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-349712","number":"349712","sourceNumber":"349712","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A boa prática médica está associada à promoção da saúde, além de práticas\nterapêuticas e diagnósticas. A atividade\nfísica vem se tornando o centro da promoção à saúde em\ndecorrência de seus inúmeros benefícios de curto, médio e longo prazo. Assinale a alternativa que\napresenta a quantidade recomendada de atividade física para pessoas entre 6 e 17 anos.","options":{"A":"Realização de atividade física variada, envolvendo atividades lúdicas e recreativas.","B":"Realização de 60 minutos de atividades físicas moderadas a vigorosas por dia, sendo estas\nadequadas para cada idade.","C":"Realização, no máximo, de 150 minutos por semana de atividades físicas vigorosas, devido ao\nrisco de acidentes.","D":"Realização de 40 minutos de atividades físicas de reforço muscular por dia, sendo estas\nadequadas para cada idade.","E":"Realização de 60 minutos de atividades físicas moderadas a vigorosas, no máximo 3x por\nsemana devido ao risco de lesões."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-337517","number":"337517","sourceNumber":"337517","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 80 anos foi encontrado em rua pública, e testemunhas disseram que ele\nestava caminhando quando subitamente caiu no chão, perdendo a consciência. No hospital, foi\nrealizado eletrocardiograma mostrado a seguir. Ao exame físico, sua pressão arterial era de\n80x40mmHg, havia estertores pulmonares em todos os segmentos pulmonares com turgência\njugular; sua glicemia estava normal. Durante seu atendimento, o paciente demonstrou ritmo\ncardíaco no monitor. Com base nos conhecimentos clínicos e nos eletrocardiogramas\napresentados, julgue o item a seguir: O eletrocardiograma número 1 denota um eletrocardiograma\ncom supradesnivelamento do segmento ST, compatível com infarto agudo do miocárdio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-322165","number":"322165","sourceNumber":"322165","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma mulher de 78 anos procura atendimento médico de urgência com queixa de dor no\nestômago e náuseas há aproximadamente 2 horas, obtendo-se o seguinte ECG da paciente: Nesse\ncaso, considerando as informações apresentadas, é correto afirmar que","options":{"A":"se trata de uma colecistite aguda, e a paciente deve ser internada aos cuidados da cirurgia\ngeral.","B":"uma opção de reperfusão coronariana deve ser indicada imediatamente.","C":"o uso de morfina e nitrato está indicado.","D":"uma endoscopia digestiva alta é prioritária.","E":"a paciente deve ser encaminhada para avaliação ambulatorial com um cardiologista."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-284272","number":"284272","sourceNumber":"284272","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. Trata-se de um infarto agudo do miocárdio\nsem supra de ST.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-284273","number":"284273","sourceNumber":"284273","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. A classificação da apresentação clínica é\nKillip 2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-284274","number":"284274","sourceNumber":"284274","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de dor\ntorácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. A trombólise é contraindicada para o\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-284276","number":"284276","sourceNumber":"284276","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 54 anos de idade, com história de hipertensão arterial e dislipidemia,\ndeu entrada no pronto-socorro com queixa de\ndor torácica retroesternal irradiada para a mandíbula\nhá uma hora. Sinais vitais na entrada: pressão arterial de 140 x 90 mmHg; frequência cardíaca de\n92; saturação de O? de 94%; e frequência respiratória de 20. Exame cardiopulmonar: ritmo\ncardíaco regular, sem sopros; e presença de B3 e B4. Murmúrio vesicular audível bilateralmente,\ncom estertores finos em ambas as bases. Eletrocardiograma revelou infradesnivelamento de ST.\nCom base nesse caso hipotético, julgue o item a seguir. Está indicada a suplementação de oxigênio\npor cateter nasal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261228","number":"261228","sourceNumber":"261228","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre\n(38,5ºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente, o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. Trata-se provavelmente de\npericardite aguda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261229","number":"261229","sourceNumber":"261229","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. Em geral, início súbito dos\nsintomas é associado ao pior prognóstico em relação a início subagudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261230","number":"261230","sourceNumber":"261230","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. É comum associação dessa\npatologia com edema agudo de pulmão e, consequentemente, insuficiência ventricular esquerda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261231","number":"261231","sourceNumber":"261231","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou com dor torácica de início súbito, febre (38,5\nºC) e dor pleurítica dependente. Foi\nsolicitado um eletrocardiograma que demonstrou infra do\nsegmento PR e supra do segmento ST difuso. Laboratorialmente o paciente apresentava troponina\nnegativa e 10.000 leucócitos. Considerando esse caso clínico e com base na imagem apresentada\ne nos conhecimentos médicos correlatados, julgue o item a seguir. É necessário internar o\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261232","number":"261232","sourceNumber":"261232","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente com história de dor torácica aos esforços comparece à consulta por estar\nmais cansado do que o normal. Refere que vem\napresentando ortopneia e dispneia paroxística\nnoturna. Foram realizados investigação laboratorial, Holter, ecocardiograma e cateterismo cardíaco.\nO ecocardiograma e o cateterismo estão representados a seguir. Tendo em vista esse caso clínico,\nas imagens apresentadas e os conhecimentos médicos correlatos, julgue o item a seguir. Na\nimagem do cateterismo, observa-se lesão em artéria descendente anterior.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261235","number":"261235","sourceNumber":"261235","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade, com miocardiopatia isquêmica dilatada com fração\nde ejeção prévia de 30%, encaminha-se à\nemergência com dor torácica em aperto há sete horas,\ndispneia importante e sudorese. Foram solicitados exames laboratoriais que demonstram\nhemograma normal, função renal e eletrólitos normais. Seu peptídeo natriurético cerebral (BNP) era\nde 300 pg/mL (valor de referência até 150 pg/dL). Solicitou-se, então o eletrocardiograma\nrepresentado na figura a seguir. Considerando esse caso clínico, a figura apresentada e os\nconhecimentos médicos correlatos, julgue o item a seguir. O paciente apresenta-se com infarto\nagudo do miocárdio anterior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-261236","number":"261236","sourceNumber":"261236","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 35 anos de idade, com miocardiopatia isquêmica dilatada com fração\nde ejeção prévia de 30%, encaminha-se à\nemergência com dor torácica em aperto há sete horas,\ndispneia importante e sudorese. Foram solicitados exames laboratoriais que demonstram\nhemograma normal, função renal e eletrólitos normais. Seu peptídeo natriurético cerebral (BNP) era\nde 300 pg/mL (valor de referência até 150 pg/dL). Solicitou-se, então o eletrocardiograma\nrepresentado na figura a seguir. Considerando esse caso clínico, a figura apresentada e os\nconhecimentos médicos correlatos, julgue o item a seguir. Ao avaliar o valor de BNP para esse\npaciente, pode-se afirmar que ele está com insuficiência cardíaca descompensada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-274371","number":"274371","sourceNumber":"274371","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino, 70 anos, hipertenso, diabético e obeso, dá entrada no pronto\natendimento com quadro de dor torácica de\ninício súbito há cerca de 2 horas, de forte intensidade,\ncom irradiação para região dorsal. Na admissão, está com PA: 200/110, FC: 95 bpm, FR: 16 irpm,\nSO2: 95%, com ausculta cardíaca mostrando sopro aórtico sistólico +++/IV, pulsos periféricos\nassimétricos, finos e palidez cutânea com pele fria. Foi realizada tomografia da aorta com contraste\ncom diagnóstico de dissecção aguda de aorta. Sobre esse quadro, assinale a alternativa\nCORRETA.","options":{"A":"O controle da dor do paciente deve ser feito com anti-inflamatório não esteroidal, como\ndipirona.","B":"O uso de nitroprussiato de sódio deve ser iniciado imediatamente para controle pressórico em\nmonoterapia.","C":"Deve-se iniciar anticoagulação do paciente.","D":"Deve-se ter como alvo o betabloqueio efetivo do paciente, com a FC oscilando entre 60 e 75.","E":"O tratamento inicial deve ser com administração de betabloqueadores por via endovenosa,\nvisando diminuir a frequência cardíaca e a\npressão arterial."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-274378","number":"274378","sourceNumber":"274378","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A pericardite é uma doença inflamatória de etiologia autoimune ou infecciosa que\nacomete o pericárdio e faz parte do\ndiagnóstico diferencial de dor torácica. Atualmente, cerca de\n1% dos casos de infarto agudo do miocárdio que têm elevação do segmento ST são, na verdade,\npericardite. Sobre esse tema, é correto afirmar que","options":{"A":"a pericardite bacteriana é a forma infecciosa mais comum.","B":"o citomegalovírus é um agente comum em imunodeprimidos e soropositivos.","C":"A síndrome de Marfan é uma causa autoimune comum.","D":"a forma que ocorre pós-infarto do miocárdio deve ser aventada em sintomas que ocorrem após 3\nsemanas do evento.","E":"a dosagem de BNP e NT-proBNP deve ser rotineira porque indica o prognóstico da doença."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239365","number":"239365","sourceNumber":"239365","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma paciente de 58 anos de idade, hipertensa, com história de mau controle,\nobesidade grau 1, dislipidêmica, tabagista\n40 anos/maços, com histórico de participação sem\nsucesso em programa de abandono ao tabagismo, é atendida em consulta de acolhimento em\nUnidade de Saúde da Família, após dois anos da última consulta agendada. Alega que procura\natendimento em razão da dor de intensidade grau quatro em hemitórax anterior esquerdo há dois\ndias, contínua, sem irradiações, realizando \"sinal do apontamento\" para demonstrar local exato da\ndor, sem fator gatilho ou fator de piora notados. Além disso, relata que vem apresentando tosse\nnão produtiva frequente há um mês, sem febre, dispneia, emagrecimento ou demais\ncomemorativos. Não vem fazendo uso das respectivas medicações, alegando que se esquece de\nadministrá-las. Leva boletim de atendimento em consulta realizada há duas semanas em unidade\nde pronto atendimento em razão da dor lombar, mostrando receita de corticoide intramuscular\nfornecida na alta, medicação da qual admite fazer uso com certa frequência, afirmando que esta\nsempre lhe é prescrita quando consulta na UPA. Mostra também exames realizados, há dois\nmeses, solicitados em consulta médica em clínica popular, com os seguintes resultados: Hb = 13,2\ng/dl, Ht = 37,1%, leucócitos = 7,2 mil, plaquetas = 148 mil, Cr = 1,1 mg/dl, Ur = 42 mg/dl,\ncolesterol\ntotal = 270 mg/dl, HDL = 38 mg/dl, LDL =192 mg/dl, triglicerídeos = 198 mg/dl e glicemia de jejum =\n123 mg/dl. Com relação a esse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. As características da dor torácica apresentadas pela paciente resultam em\nbaixo valor preditivo positivo para dor torácica por etiologia cardíaca.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-211982","number":"211982","sourceNumber":"211982","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente comparece ao consultório do cardiologista para exames de rotina.\nSegundo o médico, nos exames não se\nobservou qualquer alteração, mas o paciente foi ao\nambulatório de clínica médica, pois desejava saber o significado do número 1 no exame de imagem\necocardiográfica que foi realizado. Considerando que a imagem apresentada é obtida na incidência\nlongitudinal paraesternal durante a sístole, nesse caso clínico, o médico informou corretamente ao\npaciente que, na imagem, o número 1 corresponde ao (à):","options":{"A":"Ventrículo direito.","B":"Ventrículo esquerdo.","C":"Aorta.","D":"Átrio esquerdo.","E":"Átrio direito."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-196643","number":"196643","sourceNumber":"196643","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 65 anos de idade, diabético, vem apresentando dor torácica de forte\nintensidade há 30 dias. Foi então submetido a um cateterismo cardíaco, demonstrando lesão grave\nem artéria descendente anterior, lesão grave em artéria descendente posterior e lesão grave em\nprimeiro ramo marginal. Em relação a esse caso clínico e aos conhecimentos médicos correlatos,\njulgue o item a seguir. Se o caso foi passível de cirurgia, pode-se utilizar a artéria radial como\num\ndos enxertos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-211961","number":"211961","sourceNumber":"211961","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 72 anos de idade realizou TC de abdome total para estadiamento de\ncâncer colorretal e teve achado casual de\naneurisma de aorta abdominal de 7 cm de diâmetro, com\n5 cm de colo em relação à emergência das artérias renais e 12 cm de comprimento. Quanto a esse\ncaso clínico e aos conhecimentos médicos correlatos, a respeito dos aneurismas de aorta, assinale\na alternativa correta.","options":{"A":"A reparação cirúrgica do aneurisma de aorta é igual para todos os indivíduos, com relação ao\ntamanho e à extensão da prótese, seja ela endovascular ou não, não necessitando de um plano\nparticular para cada paciente.","B":"O paciente do caso descrito não tem indicação cirúrgica, pois apresenta um aneurisma < 7,5 cm\ne é do sexo masculino.","C":"A síndrome de Marfan não constitui um fator de risco para o desenvolvimento de aneurismas de\naorta torácica.","D":"A progressão natural de um aneurisma aórtico é manter-se estável, mesmo em pacientes com\nhistórico de hipertensão primária mal-controlada.","E":"A dissecção aórtica proximal é um transtorno ameaçador da vida; por isso, necessita de\nreparação cirúrgica imediata."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152059","number":"152059","sourceNumber":"152059","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O paciente J. O. C., de 75 anos de idade, chega ao serviço de pronto atendimento com\ndor aguda, cansaço, fraqueza muscular e\nsensação de câimbra nos pés após caminhada de duas\nquadras, obrigando-o a parar, sem melhora após alguns minutos em repouso. Relata histórico\ncirúrgico por dissecção aguda da aorta torácica. Ao exame: REG, corado, hidratado, TAX = 37 °C,\nFC = 100 bpm, FR = 21 irpm, índice tornozelo-braquial (ITB) 0,26. Lesão ulcerosa em MID sem\nsinais de infecção. Exames indicam leucócitos 8.000 células/mm³ sem desvio. O paciente foi\nsubmetido a operação vascular, evoluindo com febre no POI e infecção do sítio cirúrgico (ISC),\nposteriormente. Com relação a esse caso clínico, julgue o item a seguir. Se a dissecção aórtica na\nfase aguda, mencionada no caso clínico, é de diagnóstico inferior a 30 dias, é invariável a conduta\ncirúrgica no tipo B da classificação de Stanford.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152122","number":"152122","sourceNumber":"152122","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 55 anos de idade, hipertenso e diabético, chega ao\npronto-socorro com intensa dor torácica, em\naperto, irradiada para membro superior direito. Relata\ndispneia concomitante. Ao exame físico, observava-se bulhas normofonéticas, ritmo regular. Na\nausculta, havia estertores em bases pulmonares bilaterais Sat O2 = 90% com óculos nasal\ncomplementar. Foi realizado eletrocardiograma que demonstrou supra de ST em D2, D3 e AVF,\nsendo que o supra D3 é maior que o de D2, e D1 é isoelétrico. Com base neste caso clínico, e\nconsiderando os conhecimentos médicos a ele relacionados, julgue o item a seguir. A artéria\nacometida provavelmente é a artéria coronária direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-154341","number":"154341","sourceNumber":"154341","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente T. A. G., 55 anos de idade. tabagista, hipertenso, chega ao pronto-socorro\napresentando dor torácica com irradiação para\no dorso, além de dissociação de pulsos de 30\nmmHg entre membros superiores. O exame físico revela FC = 112 bpm; PA = 176 mmHg x 100\nmmHg; SatO? = 96%. Considerando o quadro apresentado, assinale a alternativa que indica a\nmelhor conduta a ser adotada.","options":{"A":"Tomografia computadorizada e controle pressórico.","B":"Arteriografia com cirurgia imediata.","C":"Eletrocardiograma com protocolo MONAB.","D":"Radiografia de tórax e antibioticoterapia.","E":"Cintilografia e analgesia."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-64633","number":"64633","sourceNumber":"64633","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação às respectivas drogas e dosagens para tratamento de pacientes com\npúrpura trombocitopênica idiopática (PTI), assinale a alternativa incorreta.","options":{"A":"Prednisona 1 a 2 mg/Kg/dia.","B":"Metilprednisolona 30 mg/Kg/dia.","C":"Imunoglobulina hiperimune humano 0,4 g/Kg/dia.","D":"Imunoglobulina anti-D 30 mg/Kg/dia.","E":"Prednisolona 1 a 2 mg/Kg/dia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-19248","number":"19248","sourceNumber":"19248","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 74 anos de idade está internada para investigação de massa abominal.\nAntecedente de tabagismo (20 anos/maço). No\nplantão noturno apresentou agitação psicomotora\nintensa. Recebeu duas ampolas de halperidol intramuscular e 5 mg de diazepan por via oral, com\nmelhora significativa. Pela manhã, mostrava-se muito sonolenta, sendo que, entre outras medidas,\nfoi solicitada uma gasometria arterial. Qual dos parâmetros abaixo pode explicar a atual situação da\npaciente?","options":{"A":"pH= 7,42; pCO2= 22; pO2= 80; HCO3= 18","B":"pH= 7,50; pCO2= 20; pO2= 82; HCO3= 23","C":"pH= 7,10; pCO2= 40; pO2= 65; HCO3= 10","D":"pH= 7,20; pCO2= 65; pO2= 50; HCO3= 32","E":"pH= 7,55; pCO2= 38; pO2= 65; HCO3= 35"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-343391","number":"343391","sourceNumber":"343391","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Acerca do manuseio de pacientes com dor torácica, é CORRETO afirmar:","options":{"A":"A pericardite pode ser confundida com angina, pois costuma causar dor precordial em aperto,\naliviada pelo repouso e pela nitroglicerina, mas que piora com a respiração profunda.","B":"A dor torácica que acompanha a pneumonia é bastante variável, tanto em intensidade quanto\nem característica, refletindo geralmente\nacometimento pulmonar periférico, com estimulação das\nterminações nervosas da pleura.","C":"Os transtornos psiquiátricos não podem e não devem ser diagnosticados como a causa de dor\ntorácica em um paciente, pelo risco de uma desordem orgânica de base ser negligenciada.","D":"A dor torácica causada por patologia esofágica é localizada na região central do tórax, dura de\nsegundos a poucos minutos, sendo\nfrequentemente descrita pelo paciente como pontada."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-334883","number":"334883","sourceNumber":"334883","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 61 anos de idade, sedentário, obeso e tabagista, há duas horas iniciou\nepigastralgia em queimação de forte intensidade após o almoço. O exame físico mostrou uma\nfrequência cardíaca igual a 60 bpm, frequência respiratória = 25 irpm, SatO2 = 92% e PA = 100\nmmHg x 60 mmHg, com ausculta cardíaca e pulmonar normais e sem edema de membros\ninferiores. Na admissão em uma unidade de pronto atendimento, ele realizou o eletrocardiograma\n(ECG) a seguir. Qual é a principal hipótese de diagnóstico?","options":{"A":"Bloqueio de ramo direito.","B":"Infarto agudo do miocárdio","C":"Síndrome de Wolf Parkinson White","D":"Hipertonia vagal","E":"Fibrilação atrial"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-291558","number":"291558","sourceNumber":"291558","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma mulher com 55 anos de idade procura a unidade de emergência referenciada com\nqueixa de dor precordial em aperto há 12 horas. Antecedentes pessoais: diabética tipo 2, há 12\nanos, em uso de metformina 1.500 mg ao dia e glicazida 30 mg ao dia, hipertensão arterial, há 8\nanos, em uso de captopril 150 mg ao dia. Exame físico da admissão: PA = 100 x 60 mmHg, FC =\n70 bpm, FR = 18 irpm, Sat = 92%. Ritmo cardíaco regular em 2 tempos sem sopros, murmúrio\nvesicular presente e simétrico com estertores crepitantes em base, abdome globoso, fígado a 4 cm\ndo rebordo costal direito, baço não percutível. Extremidades: pulsos periféricos diminuído, edema\n3+/4+. ECG a seguir: Diante do quadro apresentado, o diagnóstico e tratamento são:","options":{"A":"Infarto agudo do miocárdio e trombólise com ateplase.","B":"Infarto do miocárdio evoluído e cateterismo.","C":"Síndrome coronariana aguda e balão intra-aórtico.","D":"Pericardite aguda e colchicina."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-230548","number":"230548","sourceNumber":"230548","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerada recomendação para uso de antiagregantes plaquetários e anticoagulantes\nem pacientes oncológicos com trombocitopenia o\nitem:","options":{"A":"Uso do ácido acetilsalicílico em pacientes com doença coronária.","B":"O ácido acetilsalicílico deve ser usado sempre em dose máxima, preferencialmente ? 500 mg ao\ndia.","C":"Uso de terapia antiplaquetária e/ou anticoagulante em pacientes com síndrome coronária aguda,\nexceto caso com plaquetopenia.","D":"Uso de dose reduzida de enoxaparina e heparina não fracionada em pacientes com contagem\nde plaquetas < 150.000."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-230556","number":"230556","sourceNumber":"230556","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A morfologia da Placa Aterosclerótica (PC) tem um papel importante na ocorrência de\neventos cerebrovasculares e pode também ser um importante preditor de evento. Assim podemos\nAPENAS aceitar que:","options":{"A":"O reconhecimento das características ultrassonográficas da placa pode atrapalhar a\nidentificação de uma placa instável.","B":"O reconhecimento das características ultrassonográficas da placa não altera a identificação de\numa placa instável.","C":"O reconhecimento das características ultrassonográficas da placa não facilita a identificação de\numa placa estável.","D":"O reconhecimento das características ultrassonográficas da placa pode facilitar a identificação\nde uma placa instável."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-206086","number":"206086","sourceNumber":"206086","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As categorias de risco baixo e intermediário cardiovascular são baseadas apenas na\nidade e nos Estratificadores de Risco (ER). Doença aterosclerótica subclínica não está presente\nnestes grupos de risco. Determine qual dos itens abaixo não se enquadra no seu quadro:","options":{"A":"Escore de cálcio arterial coronário > 10 U Agatston.","B":"Placa carotídea (espessura íntima média > 1,5 mm)14.","C":"Angiotomografia coronária computadorizada com presença de placa 15?.","D":"Índice tornozelo braquial < 0,7"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-206135","number":"206135","sourceNumber":"206135","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Calcificação Arterial Coronariana (CAC) está associada a eventos cardiovasculares e\nmortalidade em pacientes com diabetes. Podemos apenas ACEITAR que:","options":{"A":"O rastreamento de aterosclerose clínica, não se utilizando o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor discriminar o\nrisco cardiovascular em prevenção primária.","B":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da terceira idade, para pior discriminar o\nrisco cardiovascular em prevenção primária.","C":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio endotelial, pode ser\ndesconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor\ndiscriminar o risco cardiovascular em prevenção primária.","D":"O rastreamento de aterosclerose subclínica, utilizando-se o escore de cálcio coronário, pode ser\nconsiderado em indivíduos com fatores de risco no início da idade adulta, para melhor discriminar o\nrisco cardiovascular em prevenção primária."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-206147","number":"206147","sourceNumber":"206147","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considere a investigação de isquemia miocárdica em pacientes com diabetes,\nassintomáticos e na presença dos achados abaixo descritos, indique o INCORRETO:","options":{"A":"Alterações de ECG de repouso.","B":"Pacientes que apresentam sintomas atípicos.","C":"Pacientes que apresentam dispneia inexplicada, dor torácica atípica ou desconforto.","D":"Calcificação arterial coronariana CAC muito alta (> 100)."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-206151","number":"206151","sourceNumber":"206151","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em indivíduos com diabetes, o SPECT tem maior sensibilidade e especificidade do que\no teste ergométrico. Estando de acordo com o\nseguinte item:","options":{"A":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla\n\ngama de informações, incluindo localização e extensão da isquemia e função ventricular esquerda.","B":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\n\nTc-99m sestamibi fornecem informações restritas, excluindo localização e extensão da isquemia e\nfunção ventricular esquerda.","C":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla gama de informações, incluindo localização e extensão da\nisquemia, mas não a função ventricular esquerda.","D":"A cintilografia do miocárcio (SPECT) com tálio ou a cintilografia miocárdica de perfusão com\nTc-99m sestamibi fornecem ampla gama de informações, excluindo localização e extensão da\nisquemia e função ventricular esquerda."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-203106","number":"203106","sourceNumber":"203106","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 60 anos de idade é internado em razão de dor torácica típica de\nsíndrome coronariana com duração de duas horas.\nEle apresenta frequência cardíaca de 42 bpm,\ncom bradicardia sinusal observada e confirmada no ECG, associada ao supradesnivelamento do\nsegmento ST nas derivações DII, DIII e AVF. No que se refere a esse caso clínico, assinale a\nalternativa correta.","options":{"A":"O paciente provavelmente tem um aneurisma de ventrículo esquerdo como complicação do\ninfarto agudo do miocárdio.","B":"O paciente apresenta quadro de infarto agudo do miocárdio de parede inferior, pois a artéria\ncoronária direita irriga a parede inferior do ventrículo esquerda e o nó sinusal.","C":"A bradicardia sinusal apresentada pelo paciente é fator protetor do aumento da área de\nisquemia. Assim, não deve ser considerada como fenômeno patológico.","D":"O paciente apresenta infarto agudo do miocárdio de ventrículo direito, pois as derivações\ndescritas são da artéria circunflexa e coronária direita.","E":"O ECG com supradesnivelamento do segmento ST, bem como o tempo de dor torácica, indicam\nque esse paciente não é candidato a terapia trombolítica ou angioplastia primária no momento."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-212077","number":"212077","sourceNumber":"212077","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. As informações apresentadas\nnesse caso clínico podem sugerir o diagnóstico de infarto agudo do miocárdio em parede anterior.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175089","number":"175089","sourceNumber":"175089","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Durante seu último plantão, foi solicitada sua avaliação para um paciente que deu\nentrada no hospital com queixa de dor torácica, e que referia ser diabético. Foi feito exame de\nECG. Dentre os possíveis achados do exame e sobre os conceitos diagnósticos, qual das\nalternativas se mostra INCORRETA?","options":{"A":"Sobrecarga ventricular esquerda miocárdica ao eletrocardiograma (ECG) indica baixa de\neventos cardiovasculares no DM.","B":"Ondas ?Q? ao eletrocardiograma (ECG) indicam risco elevado de eventos cardiovasculares no\nDM.","C":"Isquemia miocárdica ao eletrocardiograma (ECG) indica risco elevado de eventos\ncardiovasculares no DM.","D":"ECG, contudo é um exame pouco sensível."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175090","number":"175090","sourceNumber":"175090","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Enoxaparina apresenta grande indicação de ser administrada quando do diagnóstico\ndo IAMCST, não podemos, contudo, afirmar que:","options":{"A":"Em pacientes com idade < 75 anos: 30 mg por via Intravenosa (IV) em bolus seguidas de 1\nmg/kg de peso Subcutâneo (SC) a cada 12 horas até a alta hospitalar.","B":"Em pacientes com idade = 75 anos: não administrar o bolus e iniciar com 0,75 mg/kg SC a cada\n12 horas.","C":"A Enoxaparina não tem demonstrado redução de mortalidade.","D":"Uso de Enoxaparina demonstra que não houve redução do desfecho primário de morte ou\ninfarto do miocárdio não fatal sem um aumento importante de sangramento."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177262","number":"177262","sourceNumber":"177262","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 65 anos de idade, portador de diabetes e de hipertensão arterial\napresenta quadro doloroso precordial iniciado\nhá 2 dias , quando foi internado em unidade\nhospitalar em cidade remota , de modo a aguardar transferência para uma unidade de referência\nem cardiologia. O resultado do eletrocardiograma apresenta supra de ST e onda Q, embora o\npaciente se apresente hemodinamicamente estável. Ele chega a uma unidade terciária para vaga\nem UTI. Durante o transporte, houve piora súbita do estádo clínico do paciente , que apresentou\ndispneia, diaforese e edema agudo de pulmão. Na admissão na UTI, o paciente apresentava PA de\n98 mmHg x 72 mmHg (PA média de 81 mmHg), sopro meso-sistólico leve, mas audível, em ápice,\nirradiando-se para axila. além de edema agudo de pulmão. Considerando-se o referido caso clínico\ne os conhecimentos médicos relacionados a ele, é correto afirmar que, ao admitir o paciente, a\nequipe deverá realizar","options":{"A":"estabilização do quadro respiratório, com suporte ventilatório e ecocardiograma precoce, para\nplanejamento de plastia ou troca mitral.","B":"estudo hemodinârnico para reperfusão de resgate e iniciar imediatamente terapia com dupla\nantigregação plaquetária.","C":"o procedimento do balão intra-aórtico, em razão de tratar-se de sopro secundário à degeneração\nventricular esquerda, com reperfusão programada.","D":"intubação orotraquel e investigação de evento tromboembólico pulmonar para início da\nadministração trombolítico.","E":"infusão de agentes inotrópicos e vasopressores por se tratar de insuficiência ventricular\nesquerda decorrente de infarto agudo do miocárdio."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183930","number":"183930","sourceNumber":"183930","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de quarenta e oito anos de idade, sem doenças prévias, procurou\natendimento de emergência em um hospital de\nnível terciário, com quadro de dor retroesternal, de\ngrande intensidade, em aperto, com irradiação para o membro superior esquerdo (tipo\nformigamento), iniciada havia quatro horas. Com exceção da presença de quarta bulha cardíaca,\nnão apresentou outras alterações significativas no exame físico. O eletrocardiograma realizado na\nsala de emergência evidenciou ritmo sinusal, frequência ventricular média de 98 bpm, SÂQRS de +\n60°, presença de supradesnível do segmento ST de 5 mm nas derivações precordiais de V1 a V6 e\nnas derivações do plano frontal D1 e aVL. Os níveis de troponina T e de CKBM estavam elevados e\ncom valores acima do triplo do limite superior de referência. Com base nas informações clínicas e\nlaboratoriais do caso clínico precedente, julgue o item subsequente. O provável diagnóstico para\nesse paciente é de infarto do miocárdio transmural ? com supra do segmento ST do\neletrocardiograma ?, localizado na parede anterior extensa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175167","number":"175167","sourceNumber":"175167","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A decisão sobre a liberação para a atividade desportiva após IAM é baseada nas\navaliações clínicas e nos resultados dos exames complementares: teste ergométrico,\necocardiograma, ECG, Holter 24 horas, radiografia de tórax e exames laboratoriais. Sendo\ninadequado apenas que:","options":{"A":"É importante a avaliação do anseio do paciente e qual atividade e, principalmente, qual\ndesempenho ele espera atingir.","B":"Os pacientes, após submetidos à estratificação, devem ser classificados entre baixo, moderado\ne alto risco.","C":"Os pacientes de baixo risco são os que apresentaram alterações nos exames complementares e\nque permanecem assintomáticos, são orientados à\nrealização de quaisquer tipos de atividade\nfísica.","D":"Já os indivíduos de moderado e alto risco são contra indicados às atividades competitivas e\ndevem ser encaminhados para atividades físicas supervisionadas."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175169","number":"175169","sourceNumber":"175169","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentro da conduta médica frente à realização de exercícios físicos nos paciente\nInfartados em reabilitação, somente podemos considerar INCORRETO o seguinte item:","options":{"A":"A prática de natação e hidroginástica merece alguns cuidados. Apesar de ideal para os obesos,\npode gerar alguns problemas para o\ncoronariano, como bradicardia reflexa vagal e arritmias\ncomplexas.","B":"O choque térmico pode causar espasmos arteriais.","C":"Indivíduos que já estejam praticando atividade física no após IAM devem ser orientados às\nmínimas modificações nos sintomas e sinais, ou à alterações nos exames de reavaliação\nindicativas da progressão da doença aterosclerótica coronárias.","D":"Pacientes infartados que não possuam prévio domínio da técnica natatória devem ser\ndesaconselhados à hidroginástica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175172","number":"175172","sourceNumber":"175172","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentro das indicações da Emergência de Insuficiência Coronariana, podemos\nconsiderar completamente adequado somente a seguinte alternativa:","options":{"A":"Ácido acetilsalicílico é um dos muitos anti-inflamatórios indicados rotineiramente para todos os\npacientes com suspeita de IAM.","B":"Ácido acetilsalicílico é contraindicado na alergia ou intolerância ao medicamento, sangramento\nativo, hemofilia e úlcera péptica ativa.","C":"Pacientes com maior risco de doença coronária devem ser instruídos por seus médicos\nassistentes a tomar Ácido Acetilsalicílico (AAS) tamponado em situações emergenciais.","D":"É o antiplaquetários de eleição a ser utilizado no IAM, tendo sido demonstrado que reduz a\nmortalidade em 90%, isoladamente, quase tanto quanto a Estreptoquinase (SK)."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175177","number":"175177","sourceNumber":"175177","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com o uso de ensaios cada vez mais sensíveis para dosagem de troponinas, as\nmudanças absolutas e relativas de seus valores\nna fase aguda têm sido muito valorizadas para o\ndiagnóstico correto de IAM. Como a curva ou alteração da troponina (delta change), sendo\ninadequado que:","options":{"A":"Alguns estudos demonstraram que incrementos relativos de 20 a 50% em relação aos Valores\nBasais são insuficientes para detectar uma curva.","B":"Da mesma forma, incrementos absolutos (de uma vez o referencial de cada ensaio) também\ndemonstraram uma acurácia melhor que a dosagem isolada das troponinas na admissão.","C":"No entanto, não existe consenso de qual ponto de corte seja ideal.","D":"Os incrementos nas troponinas ultrassensíveis são muito sensíveis para infarto em evolução,\nmas pouco específicos."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175176","number":"175176","sourceNumber":"175176","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Para que ocorra melhora do prognóstico, a adesão aos programas de reabilitação\ncardiovascular é importante para o sucesso de\nqualquer intervenção de prevenção secundária, e\nestá diretamente relacionada à aderência ao tratamento. Somente uma das alternativas listadas se\nmostra inadequada dentro da atual abordagem, assinale-a:","options":{"A":"Os índices de aderência aos programas de reabilitação cardíaca após IAM excedem a 80% nos\n3 primeiros meses, caindo para 60 a 71% no\nsexto mês, para 60% aos 12 meses e para 30 a 40%\nentre o segundo e o quarto ano","B":"A insistência do Médico Assistente e a integração da equipe multidisciplinar ao atendimento aos\npacientes, por meio de esclarecimento e controle dos fatores de risco, não tem demonstrado\naumento na adesão ao tratamento.","C":"Aumento da capacidade funcional, redução de sintomas, benefício psicológico, auxílio no\ncontrole de fatores de risco, retorno mais precoce ao trabalho e aumento da sobrevivência\njustificam o emprego sistemático da reabilitação no tratamento do IAM, em todas as fases,\nconsiderando sua excelente relação custo/efetividade.","D":"A orientação fundamental a ser dada pelo cardiologista é a de que a reabilitação após o infarto\nnão se limita a programas formais e\nsofisticados, mas à mudança do estilo de vida, abrangente em\nrelação aos fatores de risco controláveis, e à marcada convivência com movimentos de qualquer\nespécie em relação às atividades cotidianas."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-159545","number":"159545","sourceNumber":"159545","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A respeito da dissecção aguda da aorta, afecção cardiovascular frequentemente\nassociada à hipertensão arterial sistêmica,\njulgue o item subequente. As complicações clínicas\nassociadas a essa moléstia aórtica incluem infarto do miocárdio, isquemia dos membros inferiores,\nacidente vascular cerebral, paraplegia, insuficiência renal aguda, infarto mesentérico,\ninsuficiência\naórtica, hemotórax e tamponamento cardíaco.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-159554","number":"159554","sourceNumber":"159554","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A respeito da dissecção aguda da aorta, afecção cardiovascular frequentemente\nassociada à hipertensão arterial sistêmica,\njulgue o item subequente. No caso de pacientes jovens\ncom dissecção aguda da aorta deve-se iniciar o tratamento clínico com a redução imediata da\npressão arterial sistólica para valores não inferiores a 150 mmHg, por meio de agentes redutores da\npós-carga de trabalho do coração, associada à administração de fármacos de efeito inotrópico\npositivo. Essas ações farmacológicas combinadas reduzem a tensão de cisalhamento aórtico e, por\nconseguinte, ajudam na proteção vascular contra a ruptura aórtica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-168434","number":"168434","sourceNumber":"168434","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem com 50 anos de idade, ao ser atendido em um Serviço de Emergência,\nrefere desconforto torácico descrito como sensação\nde aperto, com início há cerca de 90 minutos,\nsem fatores de alívio. Questionado a respeito da localização da dor, o paciente coloca a mão\nfechada sobre o lado esquerdo do peito. Informa, ainda, que o desconforto teve início após ter\nsubido escadas, tendo evoluído também com náuseas, palidez cutâneo-mucosa e sudorese fria. O\npaciente é portador de hipertensão arterial sistêmica e dislipidemia, estando em uso regular de\nenalapril - 20 mg/dia, de sinvastatina - 20 mg/dia e de ácido acetilsalicílico - 100 mg/dia.\nDurante o\natendimento, foi realizado eletrocardiograma, cujo resultado está reproduzido a seguir. (Conforme\nimagem no caderno de questões) Nessa situação, qual é o diagnóstico mais provável e o que se\nespera encontrar na curva enzimática do paciente no momento de sua chegada?","options":{"A":"Angina variante de Prinzmetal; troponina e CPK-MB positivas.","B":"Angina instável; marcadores de necrose miocárdica negativos.","C":"Infarto agudo do miocárdio inferolateral dorsal; mioglobina positiva.","D":"Infarto agudo do miocárdio de parede lateral alta; elevações séricas de mioglobina e CK-MB."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-97752","number":"97752","sourceNumber":"97752","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma mulher com 65 anos de idade apresenta o seguinte histórico: antecedentes de\nobesidade, hipertensão arterial e angioplastia coronariana prévia, em uso prévio de diltiazem - 90\nmg/dia, propranolol - 40 mg duas vezes ao dia, AAS - 100 mg/dia, dinitrato de isossorbida e\nsinvastatina - 20 mg/dia. A paciente, residente em uma cidade do interior, apresentou, há cerca de\n24 horas, quadro de infarto agudo do miocárdio com supradesnivelamento de ST de parede inferior\nassociado a infarto do ventrículo direito. Como não havia equipe de hemodinâmica disponível, foi\nadministrada estreptoquinase, com melhora apenas parcial da dor. Após estabilização clínica a\npaciente foi encaminhada para Serviço de Emergência de hospital terciário. Na admissão a\npaciente estava eupneica, orientada, ainda com queixas de dor precordial com as mesmas\ncaracterísticas, mas de menor intensidade e intermitente. A pressão arterial era de 100 x 60 mmHg,\nfrequência cardíaca = 78 bpm, frequência respiratória = 16 irpm. As auscultas cardíaca e pulmonar\nestavam normais. Enquanto eram colhidos os exames complementares e repetido o ECG, a\npaciente subitamente apresentou quadro de choque (pressão arterial = 60 x 20 mmHg), com\nrebaixamento do nível de consciência, palidez cutâneo-mucosa e insuficiência respiratória. A\nsaturação de 02 caiu para 75% em ar ambiente e a frequência cardíaca aumentou para 135 bpm. A\nperfusão periférica encontrava-se muito prejudicada e as extremidades frias e sudoreicas. O ictus\ncardíaco estava hiperdinâmico e a ausculta cardíaca revelava bulhas audíveis, com 3ª bulha e\nsopro holossistólico pancardíaco, mais audível em borda estrenal esquerda. Havia turgência jugular\na 45°. A ausculta pulmonar revelava estertores bolhosos até os ápices. Alem da intubação\norotraqueal, as medidas terapêuticas recomendadas são:","options":{"A":"iniciar noradrenalina e dobutamina e encaminhar para angioplastia de emergência.","B":"iniciar nitroprussiato de sódio e dopamina e realizar pericardiocentese de emergência.","C":"iniciar nitroprussiato de sódio e dobutamina e encaminhar para cirurgia cardíaca de emergência.","D":"iniciar noradrenalina e dopamina e encaminhar para instalação, de emergência, de balão\nintra-aórtico."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-97805","number":"97805","sourceNumber":"97805","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem com 35 anos de idade, obeso, sedentário, foi admitido no Serviço de\nEmergência com quadro agudo de dor\nretroesternal e epigástrica, em queimação, que o acordou no\nmeio da noite. Relata episódios pregressos semelhantes, porém de menor intensidade e\ngeralmente após refeições copiosas. No momento da consulta, estava extremamente ansioso,\nfrequência cardíaca = 104 bpm, pressão arterial = 150 x 110 mmHg e auscultas cardíaca e\npulmonar sem anormalidades. O paciente foi incluído em protocolo de avaliação de dor torácica e\nfoi indicada internação para observação e exames seriados por 12 horas. Qual dos seguintes\nachados de exames complementares afasta o diagnóstico de dor torácica não cardíaca?","options":{"A":"ECG normal após 12 horas.","B":"Ecocardiograma normal após 12 horas.","C":"EDA - hérnia hiatal com esofagite de refluxo moderada.","D":"Ausência de elevação de CK-MB e troponina em 12 horas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-75539","number":"75539","sourceNumber":"75539","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem com 54 anos de idade, com antecedentes de dislipidemia, hipertensão arterial\ne histórico de doença familiar cardiovascular\nprecoce (pai teve infarto do miocárdio aos 50 anos),\ndeu entrada na Emergência de um hospital com história de dor em região epigástrica há cerca de\ncinco horas, em aperto, de forte intensidade, sem relação com a alimentação e sem fatores de\nmelhora, acompanhada de náuseas e vômitos. Havia recebido 200 mg de AAS no hospital de\norigem. Ao exame, encontrava-se pálido, sudoreico e sonolento. Temperatura axilar = 35,8ºC;\npressão arterial = 80 x 50 mmHg; frequência cardíaca = 118 bpm; frequência respiratória = 16 irpm.\nPerfusão periférica diminuída. A ausculta cardíaca revelava bulhas normofonéticas, sem sopros.\n\nHavia turgência jugular a 45º. A ausculta pulmonar não revelava estertores. O eletrocardiograma da\nadmissão é apresentado abaixo: (VER IMAGEM) Diante do quadro clínico do paciente, a hipótese\ndiagnóstica, a provável causa do choque e o tratamento inicial recomendado são, respectivamente:","options":{"A":"Infarto do miocárdio com supra de ST de parede inferior; tamponamento cardíaco;\npericardiocentese.","B":"Infarto do miocárdio com supra de ST de parede anterior; resposta inflamatória sistêmica;\nnoradrenalina.","C":"Infarto do miocárdio com supra de ST de parede inferior; infarto de ventrículo direito;\nhidratação\ncom solução salina.","D":"Infarto do miocárdio com supra de ST de parede anterior; ruptura de músculo papilar; colocação\nde balão intra-aórtico.","E":"Infarto do miocárdio com supra de ST de parede anterosseptal; ruptura do septo interventricular;\ncirurgia cardíaca de emergência."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-137701","number":"137701","sourceNumber":"137701","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 48 anos, hipertenso, obeso, chega à Emergência com queixa de\nepisódios de dor torácica precordial, sem\nirradiação, iniciada nos últimos dois dias, com piora há 24\nhoras. A dor dura de 5 a 15 minutos, sendo precipitada por esforços intensos, como subir escadas,\ne é aliviada pelo repouso. O paciente informa não sentir a dor no momento da anamnese. Usa\ncaptopril e hipoglicemiante oral de forma regular. Nega antecedentes de doença coronariana e um\neletrocardiograma foi considerado normal pelo seu cardiologista na última consulta, há 6 meses. Ao\nexame, mostra-se ansioso, mas em bom estado geral, pulso = 85 bpm, regular, cheio, PA = 140 x\n80 mmHg, pulsos periféricos palpáveis e simétricos, extremidades bem perfundidas. As auscultas\npulmonar e cardíaca estão dentro da normalidade. O seu eletrocardiograma à admissão mostra os\nseguintes achados (VER IMAGEM). Qual a abordagem mais adequada ao paciente?","options":{"A":"Realizar tratamentos anti-isquêmico e antitrombótico administrados de modo imediato e\nsimultâneo.","B":"Observar em Unidade Coronariana e administrar medicamentos sintomáticos até realização de\ncateterismo cardíaco.","C":"Observar na Emergência por 12 horas e encaminhar ao cardiologista para teste ergométrico se\npersistir assintomático.","D":"Realizar tratamento anti-isquêmico imediato, seguido de terapia antitrombótica em caso de\nalterações do segmento ST no ECG nas próximas 12 horas.","E":"Realizar tratamento antitrombótico imediato, seguido de terapia anti-isquêmica em caso de\nelevação de troponina sérica e/ou CK-MB nas próximas 12 horas."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-19208","number":"19208","sourceNumber":"19208","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerando o caso de uma paciente de 28 anos de idade, com megaesôfago\nchagásico e desnutrição calórico-proteica,\njulgue o próximo item. A hipoalbuminemia, se verificada\nna paciente, deve ser corrigida com infusões diárias de albumina intravenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-19209","number":"19209","sourceNumber":"19209","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerando o caso de uma paciente de 28 anos de idade, com megaesôfago\nchagásico e desnutrição calórico-proteica,\njulgue o próximo item.\n\nA reposição nutricional, no caso em tela, deverá apresentar resultados clínicos e laboratoriais após\nduas semanas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-351582","number":"351582","sourceNumber":"351582","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 77 anos de idade, diabético tipo 2, coronariopata, com\nrevascularização miocárdica há 8 anos, chegou ao pronto-socorro com quadro de dor precordial\ncom as mesmas características do infarto agudo do miocárdio, ocorrido há 9 anos, acompanhado\nde palidez e sudorese. O exame físico revelou pressão arterial de 140 x 90mmHg em membros\nsuperiores, frequência cardíaca de 80bpm e peso de 80kg. O paciente apresentava-se com bom\nestado geral, ansioso, pálido, hidratado e afebril. Estava em uso de 100mg/dia de AAS, 850mg de\nmetformina 3x/dia, 50mg de captopril 3x/dia, 25mg/dia de atenolol e 20mg/dia de sinvastatina.\n\nRealizou ECG que não evidenciou alterações no segmento ST. Foram realizadas três dosagens\nnegativas de troponinas. Nesse caso, é\nCORRETO afirmar que a principal hipótese diagnóstica é:","options":{"A":"Síndrome coronariana aguda com angina instável.","B":"Infarto agudo do miocárdio sem supradesnivelamento do segmento ST.","C":"Infarto agudo do miocárdio com supradesnivelamento do segmento ST.","D":"Angina estável."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-352187","number":"352187","sourceNumber":"352187","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quanto aos tipos de infarto agudo do miocárdio (IAM), assinale a alternativa incorreta.","options":{"A":"Tipo 1: é o infarto decorrente de instabilização de uma placa aterosclerótica na coronária.","B":"Tipo 2: é o infarto causado mais comumente por um desbalanço entre oferta e demanda de\noxigênio para o músculo cardíaco.","C":"Tipo 3: quadro sugestivo de IAM em acidente que evoluiu com morte súbita e no qual não houve\ntempo de colher marcadores de necrose miocárdica.","D":"Tipo 4: infarto relacionado à cirurgia de revascularização miocárdica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-320451","number":"320451","sourceNumber":"320451","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As síndromes coronarianas agudas são emergências clínicas de alta morbimortalidade.\nAcerca do tratamento dessas condições, julgue as\nalternativas abaixo e marque a correta:","options":{"A":"O uso de oxigenoterapia deve ser realizado de rotina na sala de emergência.","B":"O uso de beta-bloqueadores (via oral) deve ser feito nos pacientes sem sinais de baixo débito.","C":"A morfina deve ser evitada, pois aumenta o consumo miocárdico de oxigênio.","D":"A dose de ataque de enoxaparina deve ser feita na dose de 1 mg/kg, via subcutânea.","E":"A fibrinólise pode ser realizada para os pacientes com síndrome coronariana aguda sem supra\nde ST de alto risco."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-336312","number":"336312","sourceNumber":"336312","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher, 52 anos, tabagista, portadora de lúpus eritematoso sistêmico e hipertensão\narterial sistêmica, chega no pronto socorro com\nprecordialgia intensa iniciada há 5 horas,\nespontaneamente, em repouso, que piora durante a inspiração forçada, irradiada para ombros, sem\nmelhora desde então. Ao exame: regular estado geral, corada, acianótica, anictérica, desidratada\n\n+/4+, Tax: 38,1°C. Lúcida, orientada em tempo e espaço, pupilas isocóricas e fotorreagentes, sem\ndéficits focais. Ritmo cardíaco regular, 2 tempos, bulhas hipofonéticas, sem sopros, FC: 106 bpm,\nPA: 142/80 mmHg, jugulares túrgidas, TEC < 3 segundos. Murmúrio vesicular fisiológico, sem\nruídos adventícios, eupneica em ar ambiente, SpO2: 97%. Realizado eletrocardiograma e\nultrassonografia cardíaca point-of-care na admissão, cujas imagens estão abaixo. O diagnóstico e\ntratamento, deste paciente são, respectivamente:","options":{"A":"Miocardite aguda / Prednisona + amoxicilina","B":"Pericardite aguda / Ibuprofeno + colchicina","C":"Infarto agudo do miocárdio com supradesnivelamento de ST / Alteplase","D":"Tamponamento cardíaco / Pericardiocentese imediata"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-305021","number":"305021","sourceNumber":"305021","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considere dois pacientes que buscaram atendimento médico no ambulatório de um\nhospital com queixa de tonteira. O paciente\nA é um homem de 73 anos de idade, hipertenso, com\nrelato de sensação de rotação do ambiente que acontece pela manhã, ao se levantar da cama,\nassociada à náusea, que passa muito rapidamente, embora ele permaneça por alguns minutos\nsudorético, nauseado e com as mãos frias. A paciente B é uma mulher de 54 anos de idade,\nhipertensa e diabética, com relato de sensação de desmaio, sudorese, palpitações e escurecimento\nvisual que podem acontecer em repouso ou esforço, e duram alguns minutos, com remissão\nespontânea. Considerando as prováveis origens das tonteiras desses pacientes, os exames\ninicialmente indicados para auxílio diagnóstico são, respectivamente,","options":{"A":"manobra de Dix-Hallpike e eletrocardiograma (ECG).","B":"eletronistagmografia e Holter de 24 horas.","C":"Holter de 24 horas e manobra de Dix-Hallpike.","D":"eletronistagmografia e ECG."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-304873","number":"304873","sourceNumber":"304873","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Adolescente, sexo masculino, 12 anos, comparece a consulta solicitando atestado para\nprática de natação. Assintomático, sem história familiar de risco para doença cardiovascular.\n\nExame físico: dados vitais e exame segmentar normais. Traz eletrocardiograma realizado há um\nano para avaliação pré-operatória de cirurgia\nortopédica com laudo de arritmia sinusal. A conduta\nindicada neste caso é:","options":{"A":"Liberar para prática de natação.","B":"Indicar Tilt teste.","C":"Realizar ecocardiograma.","D":"Solicitar novo eletrocardiograma."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-306731","number":"306731","sourceNumber":"306731","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"D.R.A, 58 anos, dá entrada no PS com queixa de dor torácica há 1 hora. Apresenta-se\nsudoreico e relata náuseas. Durante a\navaliação inicial foi realizado eletrocardiograma, que está\nrepresentado abaixo. PA = 80/50 mmHg, FC = 120 bpm, FR = 28 irpm, SpO2 = 92%. A troponina\nencontra-se 3 vezes acima do valor de referência superior. Qual das drogas abaixo está\ncontraindicada neste caso?","options":{"A":"Ácido acetilsalicílico","B":"Clopidogrel","C":"Dinitrato de isossorbida","D":"Heparina"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-287337","number":"287337","sourceNumber":"287337","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 65 anos, diabético, hipertenso, dislipidêmico e tabagista. Relata\ndor/desconforto no hemitórax esquerdo há 02\nsemanas, durante uma atividade física moderada. Há\n01 dia apresentou desconforto mais intenso (7+/10+), com cerca de 10 minutos de duração. Nessa\nmadrugada, às 05h15, foi acordado com dor retroesternal (10+/10+), acompanhado de náuseas e\nmal-estar intenso. Às 08h30 é atendido com desconforto em hemitórax esquerdo (4+/10+). O\neletrocardiograma está apresentado abaixo. Qual diagnóstico? (Obs. Cópia da Figura a seguir na\npágina 13 ampliada para consulta).","options":{"A":"Síndrome Coronariana Aguda.","B":"Angina Estável.","C":"Dissecção de aorta.","D":"Tomboembolismo Pulmonar."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-246719","number":"246719","sourceNumber":"246719","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A inflamação desempenha papel central na gênese da doença coronariana isquêmica.\nNos últimos anos, vários medicamentos têm sido\nutilizados em pesquisas clínicas buscando reduzir\nnovos eventos coronarianos adversos, a nível de prevenção secundária, agindo exclusivamente por\nvias inflamatórias. Dentre os medicamentos abaixo, qual possui evidência científica mais favorável\nneste contexto?","options":{"A":"Corticoides","B":"Anti-Inflamatórios não hormonais","C":"Idarucizumab","D":"Metotrexato","E":"Colchicina"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-243062","number":"243062","sourceNumber":"243062","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, é admitido na UPA (Unidade de Pronto\nAtendimento) com forte dor precordial há 2 horas.\nEletrocardiograma mostra supradesnível de\nsegmento ST em parede anterior. É submetido à trombólise química com critérios de reperfusão.\nSegundo a estratégia farmacoinvasiva atualmente indicada, este paciente:","options":{"A":"deve ser submetido a cateterismo com vistas à possível intervenção coronária percutânea dentro\nde 3 a 24 horas após a trombólise\nbem-sucedida.","B":"deveria ter sido administrada metade da dose do trombolítico no atendimento pré-hospitalar e,\nem seguida, ter sido encaminhado para hospital de referência.","C":"deve ser submetido a cateterismo o quanto antes após a administração de trombólise, mesmo\nque a reperfusão química seja bem-sucedida.","D":"deve ser submetido a cateterismo com vistas à possível intervenção coronária percutânea após\n48 horas da trombólise bem-sucedida.","E":"caso seja optado por cateterismo cardíaco, a trombólise intra-arterial está indicada."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-243067","number":"243067","sourceNumber":"243067","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A ecocardiografia sob estresse é um método não invasivo, estabelecido para a\navaliação de pacientes com doença arterial\ncoronária. Qual, dentre as alternativas abaixo, NÃO\nconstitui indicação para a realização do ecocardiograma sob estresse na doença arterial coronária\ncrônica?","options":{"A":"Estratificação de risco de pacientes com doença arterial coronária.","B":"Avaliação de isquemia miocárdica em indivíduos assintomáticos com teste ergométrico positivo\nou duvidoso.","C":"Avaliação de rotina em pacientes após revascularização do miocárdio.","D":"Avaliação de isquemia miocárdica na presença de bloqueio do ramo esquerdo ou alterações que\nimpeçam adequada análise eletrocardiográfica de isquemia.","E":"Estresse farmacológico na avaliação de viabilidade miocárdica (miocárdio hibernado) para\nplanejamento de revascularização."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-243074","number":"243074","sourceNumber":"243074","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentre os achados de exame físico, qual, entre os abaixo, NÃO é característico de um\nepisódio anginoso provocado por isquemia miocárdica?","options":{"A":"sopro diastólico aspirativo em foco aórtico acessório.","B":"terceira bulha.","C":"quarta bulha.","D":"sopro de regurgitação mitral.","E":"desdobramento paradoxal da segunda bulha."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215173","number":"215173","sourceNumber":"215173","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 50 anos, tabagista, refere que acordou às 6 horas da manhã com dor\nretroesternal em queimação, com irradiação\npara o pescoço, associado a sudorese, náuseas e\nvômitos. Chega ao pronto-socorro às 10 horas e é submetido a realização de eletrocardiograma\nque evidenciou supra do segmento ST em parede anterior. O paciente encontra-se a 30 minutos do\ncentro de referência com hemodinâmica. Qual é o próximo passo?","options":{"A":"Administrar AAS 200 mg, clopidogrel 300 mg, enoxaparina 30 mg IV e encaminhar ao serviço de\nhemodinâmica para angioplastia primária.","B":"Administrar AAS 200 mg, clopidogrel 300 mg, enoxaparina 30 mg IV e aguardar a troponina\nantes de encaminhar para angioplastia\nprimária.","C":"Administrar AAS 100 mg, clopidogrel 75 mg, enoxaparina 80 mg SC e encaminhar ao serviço de\nhemodinâmica para angioplastia primária.","D":"Administrar AAS 100 mg, clopidogrel 75 mg, enoxaparina 80 mg SC e aguardar a troponina\nantes de encaminhar para angioplastia\nprimária.","E":"Realizar trombólise com tenecteplase."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215179","number":"215179","sourceNumber":"215179","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 52 anos, do sexo masculino, chegou ao pronto-socorro com queixa de dor\nretroesternal em aperto, com duração de 20min, que se repetiu por 2 vezes nas últimas 24 horas.\nEstava assintomático havia 2 anos, em uso de ácido acetilsalicílico (AAS), sinvastatina e enalapril.\nApresenta antecedentes de hipertensão, dislipidemia. Pai falecido de infarto do miocárdio aos 54\nanos. Exame físico: ritmo cardíaco regular; Frequência Cardíaca (FC) = 88 bpm; Pressão Arterial\n(PA) = 140 x 90 mmHg; pulmões sem ruídos adventícios. Primeira medida de troponina positiva. O\neletrocardiograma (ECG) está apresentado na figura que segue:","options":{"A":"Paciente de alto risco (TIMI = 6); deve ser estratificado invasivamente nas próximas 24 horas.","B":"Paciente de alto risco (TIMI = 5); deve ser estratificado invasivamente nas próximas 48 horas.","C":"Paciente de alto risco (TIMI = 7); deve ser estratificado invasivamente nas próximas 24 horas.","D":"Paciente de moderado risco (TIMI = 4); deve ser estratificado invasivamente nas próximas 72\nhoras.","E":"Paciente de alto risco (TIMI = 6); deve ser estratificado invasivamente nas próximas 48 horas."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215181","number":"215181","sourceNumber":"215181","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 68 anos chegou à emergência do Hospital de Marechal Floriano com infarto\nagudo do miocárdio (IAM) com supradesnivelamento de do segmento ST na parede inferior.\n\nClinicamente, apresentava-se estável hemodinamicamente em Killip I. Os sintomas haviam iniciado\nhá 60 minutos, não possui contra-indicação ao\nuso de trombolítico. Qual a estratégia de tratamento\nmais adequada, considerando-se o tempo de transferência para o centro de referência para\nhemodinâmica estima-se ser de cerca de 150 minutos?","options":{"A":"Encaminhar o paciente imediatamente ao centro capacitado para realização de angioplastia\nprimária.","B":"Administrar metade da dose do trombolítico preconizada para IAM com supra de ST e\nencaminhar o paciente para estratégia de angioplastia facilitada.","C":"Utilizar inibidor de IIb/IIa e encaminhar o paciente para estratégia de angioplastia facilitada.","D":"Por ser o IAM de baixo risco para complicações, tratar o paciente sem estratégia de reperfusão,\nevitando-se os riscos do uso de trombolítico em local com poucos recursos ou os riscos de\ntransporte.","E":"Administrar trombolítico imediatamente, com posterior estratificação coronariana invasiva."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215106","number":"215106","sourceNumber":"215106","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O que apresenta um paciente com infarto agudo do miocárdio e insuficiência cardíaca\nKillip III:","options":{"A":"Choque cardiogênico.","B":"Edema agudo de pulmão cardiogênico.","C":"Estertores crepitantes bibasais.","D":"Perda de líquido para terceiro espaço.","E":"Todas as alternativas anteriores."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-196813","number":"196813","sourceNumber":"196813","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 59 anos com dor precordial em aperto iniciada há duas horas, irradiando\npara o andar superior do abdome, com vômitos.\nAusculta pulmonar normal. PA = 115 x 70 mmHg.\nAmilase e lipase normais. Radiografias de tórax e abdome normais e o ECG abaixo. Dentre as\ndrogas abaixo, qual deve ser evitada neste paciente?","options":{"A":"Nitroglicerina.","B":"AAS.","C":"Sinvastatina.","D":"Enoxaparina."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-172803","number":"172803","sourceNumber":"172803","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 78 anos admitido em pronto-socorro com dor precordial típica, há cerca de 1\nhora, associada à dispneia. Histórico de uso de sildenafila há 3 horas. Ao exame físico,\napresentava-se orientado, sudoreico, com frequência cardíaca de 110 bpm e pressão arterial de 85\nx 50 mmHg. O eletrocardiograma evidencia infradesnivelamento de segmento ST de V1 a V3. Este\npaciente deve ser tratado com:","options":{"A":"Heparina de baixo peso molecular associada a antiagregante plaquetário.","B":"Nitroprussiato de sódio por via endovenosa.","C":"Nitrato sublingual.","D":"Trombolítico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-148540","number":"148540","sourceNumber":"148540","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente feminina, 60 anos, multípara, obesa, apresenta dor intensa epigástrica,\nacompanhada de sudorese profusa, dispneia e\ntaquicardia, que durou cerca de 15 minutos. No dia\nseguinte procura assistência médica já assintomática. A pressão arterial foi aferida em 130 x 80\nmmHg, frequência cardíaca de 80 batimentos por minuto, ritmo cardíaco regular em 2 tempos,\nabdome indolor, sem massas palpáveis ou visceromegalias, com peristalse normal e exame do\naparelho respiratório normal. Ao iniciar a investigação, qual a conduta mais adequada neste\ncontexto clínico?","options":{"A":"Solicitar endoscopia digestiva alta.","B":"Solicitar eletrocardiograma de repouso e de teste ergométrico.","C":"Solicitar ultrassonografia abdominal.","D":"Solicitar exame de urina.","E":"Solicitar tomografia computadorizada de tórax."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-149141","number":"149141","sourceNumber":"149141","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente 75 anos, sexo feminino, hipertensa grave de longa data, obesa, dá entrada no\npronto-socorro HECI com história de intensa dor precordial, com irradiação dorsal e para membro\nsuperior esquerdo, iniciada há cerca de 2 horas. Familiares referem quadro de convulsão e breve\nperda de consciência à caminho do hospital. Ao exame clínico encontra-se acordada, lúcida, sem\nalterações no exame neurológico. Ritmo cardíaco regular, FC 102 bpm, 170 x 80 mmHg, sopro\ndiastólico em focos de base. Ausculta pulmonar limpa. Eletrocardiograma realizado imediatamente\nmostrando ritmo sinusal, com supradesnivelamento do segmento ST 3 mm em D2, D3, AVf. Diante\ndo caso exposto, qual a melhor conduta imediata a ser tomada?:","options":{"A":"Medir a pressão em membro superior esquerdo, examinar pulso em membros inferiores e\nrealizar um RX tórax imediatamente.","B":"Solicitar dosagem de troponina e CKMB.","C":"Administrar AAS, clopidogrel, morfina, nitrato, beta bloqueador, heparina e encaminhar à sala de\nhemodinâmica imediatamente para angioplastia primária (desde que o tempo estimado para o\nprocedimento seja inferior a 90 minutos).","D":"Proceder a trombólise imediatamente caso a angioplastia não seja possível num\nintervalo de tempo inferior a 120 minutos.","E":"Administrar AAS, clopidogrel, morfina, nitrato, betabloqueador, heparina e encaminhar à sala de\nhemodinâmica imediatamente para angioplastia primária (desde que a dosagem de enzimas esteja\nalterada)."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-155468","number":"155468","sourceNumber":"155468","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Lactente de 2 anos e 2 meses, é levada ao pronto-socorro por apresentar, há dois dias,\nmanchas roxas pelo corpo, principalmente em membros inferiores. A mãe nega febre e anorexia,\nrefere que, há 3 semanas a criança apresentou quadro gripal. Sua vacinação está em dia. Ao\nexame físico, apresenta petéquias em palato, hematomas em coxas, abdome e pernas, petéquias\nem todo o corpo, restante do exame físico normal. Os exames laboratoriais revelam hemograma:\nHb 10 g/dl, Ht 30%, reticulócitos 1%, leucócitos 8.200/mm³ (basófilos 2%, eosinófilos 3%,\nsegmentados 32%, linfócitos = 50%, monócitos = 8%, linfócitos atípicos = 5%), plaquetas = 5.000/\nmm³, morfologia de hemácias e plaquetas normais. Com base nessas informações, a hipótese\ndiagnóstica mais provável é:","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Leucemia aguda.","C":"Púrpura trombocitopênica imunológica.","D":"Hemofilia.","E":"Dengue."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131616","number":"131616","sourceNumber":"131616","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale a alternativa errada:","options":{"A":"O número máximo de unidades de sangue que pode ser doada de forma autóloga para cirurgia\neletiva, contando que a hemoglobina do paciente fique superior a 11g/dL é cinco, em um intervalo\nde 3 a 4 dias, começando 6 semanas antes da cirurgia","B":"Uma escolha para preparar um paciente com doença de Von Willebrand tipo 1 para cirurgia é\nuso de desmopressina, 1x ao dia, e\nhistoricamente os pacientes se mostram bem responsivos ao\nmedicamento","C":"A deficiência de fator XIII mais comumente se apresenta como sangramento tardio após lesão\nou cirurgia. É uma doença autossômica recessiva, com relação homem / mulher 1:1.","D":"Um paciente com tempo de tromboplastina parcial ativada prolongado e trombose venosa\nprofunda deve ser avaliada pela possibilidade da existência\n\nda Síndrome antifosfolipídeo","E":"Um tempo de tromboplastina parcial ativada anormal está associada a anomalia na via\nextrínseca da cascata da coagulação e TAP (\ntempo de protrombina ) elevado anomalia da via\nintrínseca da cascata da coagulação"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131636","number":"131636","sourceNumber":"131636","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"São características da trombocitopenia induzida por heparina, exceto:","options":{"A":"Varfarina é contraindicada como tratamento inicial devido seu potencial em piorar a\nhipercoagulabilidade.","B":"Ocorre habitualmente com 5 a 10 dias de uso de heparina.","C":"É mais comum com heparina não fracionada do que com a de baixo peso molecular.","D":"Transfusão de plaquetas é frequentemente necessária.","E":"Trombose arterial ou venosa são detectadas em até 50% dos casos."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131642","number":"131642","sourceNumber":"131642","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 38 anos, previamente hígido, está sendo investigado pela presença de\nfebre, trombocitopenia e alterações neurológicas e da função renal. Para o diagnóstico de púrpura\ntrombocitopênica trombótica é essencial o achado de:","options":{"A":"Anemia hemolítica microangiopática.","B":"FAN e ANCA positivos.","C":"Alterações do coagulograma.","D":"Evidência de trombose venosa profunda.","E":"Esplenomegalia."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-106383","number":"106383","sourceNumber":"106383","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Todos os seguintes itens são manifestações comuns de sangramentos causados pela\ndoença de Von Willebrand, exceto:","options":{"A":"angiodisplasia do intestino delgado.","B":"epistaxe.","C":"menorragia.","D":"hemorragia pós-parto.","E":"hemartrose espontânea."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-100991","number":"100991","sourceNumber":"100991","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Constitui indicação para transfusão de concentrado de hemácias lavadas:","options":{"A":"Histórico de pelo menos duas reações febris não hemolíticas.","B":"Portadores de imunodeficiências graves.","C":"Reações alérgicas em hemotransfusões prévias.","D":"Pós-transplantados de medula óssea.","E":"Indivíduos politransfundidos."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-77604","number":"77604","sourceNumber":"77604","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 78 anos, portador de mielodisplasia, hipertenso de longa data e diabético\ncom controle regular dos fatores de risco, em\nuso crônico de aspirina, foi admitido no departamento\nde urgência queixando-se de sonolência, dispneia aos esforços, astenia, hiporexia e palidez\ncutânea. Após coleta de exames de rotina, foi identificado nível sérico de hemoglobina de 5,4\nmg/dl. Solicitado internação e prescrito pelo emergencista hemotransfusão com 02 concentrados de\nhemácias. Seis horas após administração da segunda transfusão, o paciente evoluiu com\ntaquidispneia intensa, hipoxemia com saturação arterial de oxigênio de 86%, crepitações difusas\nem todos os campos pulmonares examinados e pressão arterial de 158 x 90 mmHg. Radiografia de\ntórax revelou discreto aumento global da área cardíaca e infiltrado pulmonar difuso bilateral de\npredomínio peri-hilar sem derrame pleural e distribuição vascular preservada. Eletrocardiograma\nsem alterações em relação ao basal. Dosagem das troponinas negativas e peptídeo natriurético\ncerebral (BNP) inferior a 100 pg/ml. Paciente não apresentou melhora clínica após administração\nde vasodilatador venoso e de diuréticos. Em relação ao caso, o diagnóstico mais provável é:","options":{"A":"Síndrome da angústia respiratória do adulto.","B":"Edema agudo de pulmão hipertensivo.","C":"Sobrecarga circulatória associada à transfusão.","D":"Infarto agudo do miocárdio.","E":"Lesão pulmonar aguda relacionada à transfusão."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-59336","number":"59336","sourceNumber":"59336","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação aos novos anticoagulantes orais marque a alternativa CORRETA:","options":{"A":"Apesar de apresentarem a comodidade posológica de não ser necessário o controle de RNI,\nainda não conseguiram comprovar em estudos\nrandomizados uma eficácia semelhante à warfarina\nna prevenção de fenômenos tromboembólicos em portadores de fibrilação atrial.","B":"Apresentam taxas de sangramento maior (hemorragia intracraniana, por exemplo) superiores à\nwarfarina, por isso nenhum deles foi liberado ainda para uso em idosos acima de 80 anos.","C":"A dabigratana (Pradaxa) é o único já liberado para uso na prevenção de fenômenos\ncardioembólicos relacionados à fibrilação atrial.","D":"Podem ser usados em pacientes com próteses cardíacas metálicas para prevenção de\ntrombose, com eficácia comprovadamente não inferior à warfarina.","E":"A rivaroxabana (Xarelto) além de poder ser usada na prevenção de fenômenos tromboembólicos\nrelacionados à fibrilação atrial, apresenta estudos bem conduzidos no tratamento de pacientes com\nembolia pulmonar."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-59108","number":"59108","sourceNumber":"59108","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Criança, de quatro anos de idade, é atendida com quadro de petéquias e equimoses\ndisseminadas. Na história há relato de sibilância recorrente desde seis meses de vida,\nacompanhados de sintomas virais, o que ocorreu há cerca de duas semanas. Nega outros\nsintomas. Ao exame físico tem lesões petequiais e equimoses em tórax, abdome e membros,\nsendo o restante do exame normal. Os exames revelam plaquetopenia importante de 20.000\nplaquetas, sem alterações de série branca e vermelha, Velocidade de Hemossedimentação (VHS)\nde 12 mm, função hepática e renal normais. Qual a principal hipótese diagnóstica?","options":{"A":"Dengue.","B":"Leucemia aguda.","C":"Lúpus eritematoso sistêmico.","D":"Infecção pelo vírus Epstein-Barr.","E":"Púrpura trombocitopênica idiopática."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-43330","number":"43330","sourceNumber":"43330","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre a prevenção do tromboembolismo venoso (TVP) marque a alternativa\nINCORRETA:","options":{"A":"A incidência de TVP confirmada em pacientes hospitalizados, no pós-operatório de grandes\ncirurgias ortopédicas, sem a adequada tromboprofilaxia, pode chegar até 40-60% dos casos.","B":"O critério de escolha que deve ser usado para selecionar a estratégia de tromboprofilaxia é o\ntipo de cirurgia que será realizada.","C":"A aspirina nunca deve ser isoladamente para profilaxia da TVP em nenhum grupo de pacientes.","D":"Para pacientes submetidos à cirurgia geral de baixo risco, como procedimentos de pequeno\nporte e que não tenham outros fatores de\nrisco para TVP, recomenda-se somente a deambulação\nprecoce e frequente.","E":"Usar primeiramente a tromboprofilaxia mecânica (ex: meias de compressão pneumática) em\npacientes com alto risco de sangramento."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-43322","number":"43322","sourceNumber":"43322","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mãe refere início súbito de petéquias e púrpuras generalizadas em seu filho de 4 anos.\nNega queixas álgicas, febre, tosse, coriza, vômitos ou diarreia. Ao exame: pequeno sangramento\ngengival, bom estado geral, ativo, nuca livre, hidratado, acianótico, anictérico e normocorado; ACV\ne AR sem anormalidades; Abdome depressível, flácido e indolor, ausência de massas ou\nvisceromegalias. Exame laboratorial com hemoglobina, leucometria e o diferencial leucocitário\nnormal, trombocitopenia com plaqueta de tamanho aumentado. Todas as afirmativas estão\nincorretas, exceto:","options":{"A":"Trata-se de um quadro clássico de Púrpura Trombocitopênica Imunológica. A trombocitopenia\ndeve-se ao desenvolvimento de autoanticorpos\ndirecionados contra a superfície plaquetária e o\ntamanho aumentado das plaquetas reflete sua renovação aumentada.","B":"Quando o início é insidioso, principalmente em pré-escolar, a possibilidade de PTI crônica ou\nque a trombocitopenia seja a manifestação\nde uma doença sistêmica, tal como o lúpus eritematoso\nsistêmico, é mais provável.","C":"Setenta a 80% das crianças que apresentam PTI aguda têm a resolução espontânea em um\nmês e 5 a 10% das crianças evoluirão para\nPTI crônica.","D":"A transfusão de plaquetas na PTI aguda geralmente é indicada, pois o objetivo inicial da terapia\né aumentar rapidamente a plaquetometria e\nprevenir a hemorragia intracraniana."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-32417","number":"32417","sourceNumber":"32417","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quanto à coagulação, responda a alternativa CORRETA:","options":{"A":"A deficiência de vitamina K está relacionada a distúrbios de coagulação que acontecem nos\npacientes com fístulas biliares e má absorção intestinal, mas não apresenta relação com a\nadministração parenteral de cefalosporinas.","B":"A warfarin é uma droga anticoagulante que atua bloqueando fatores dependentes da vitamina K,\ntem meia-vida de 6 horas e os distúrbios hemorrágicos causados pela sua administração são\ncorrigidos pela suspensão da mesma. Nos casos graves, realiza-se administração de vitamina K.","C":"A doença renal e a uremia causam um distúrbio hemorrágico reversível, relacionado à disfunção\nplaquetária. A desmopressina ajuda a diminuir os distúrbios hemorrágicos.","D":"A insuficiência hepática apresenta distúrbio de coagulação grave causado pela deficiência da\nabsorção da vitamina K bile dependente, no íleo distal.","E":"A trombocitopenia pode causar sangramento durante uma cirurgia, em níveis abaixo de 100.000\nplaquetas. Algumas drogas são causadoras deste distúrbio, entre elas: bloqueadores H2,\nhipoglicemiantes orais e aspirina."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-23172","number":"23172","sourceNumber":"23172","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente GFH, 23 anos foi admitido com diagnóstico de Trombose Venosa Profunda\nem membro inferior esquerdo. Estão descritas\nabaixo as indicações do uso de filtro em veia cava\ninferior, exceto:","options":{"A":"Contraindicação para uso de anticoagulação.","B":"Embolização pulmonar em vigência de anticoagulação","C":"Baixa reserva cardiopulmonar para tolerar episódio de embolia pulmonar.","D":"Presença de trombo livre não aderente a parede do vaso.","E":"Presença de trombose extensa em membro inferior."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-8104","number":"8104","sourceNumber":"8104","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Entre os itens abaixo, qual não é considerado indicação para o uso de plasma?","options":{"A":"Expansão de volume em pacientes hemodinamicamente instáveis.","B":"Sangramento microvascular difuso por coagulopatia.","C":"Necessidade de reversão dos efeitos cumarínicos.","D":"Pacientes com púrpura trombocitopênica trombótica.","E":"Pacientes com síndrome hemolítico-urêmica."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-355622","number":"355622","sourceNumber":"355622","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino, 60 anos, é atendido com dor precordial constritiva iniciada em\nrepouso desde duas horas antes. Encontra-se\ndiaforético e pálido; PA = 110/75 mmHg; FC = 106\nbpm; ausculta cardíaca com ritmo cardíaco regular, sem sopros. O nível sérico de troponina está\nelevado e o traçado do ECG é compatível com infarto agudo do miocárdio sem elevação do\nsegmento ST. Assinale a alternativa que apresenta a melhor opção terapêutica para este paciente:","options":{"A":"ácido acetilsalicílico","B":"AAS, betabloqueador, clopidogrel e enoxiparina","C":"betabloqueador, maleato de enalapril e enoxiparina","D":"nitroglicerina, sulfato de morfina e betabloqueador","E":"estreptoquinase, AAS, fondaparinux e clopidogrel"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-353832","number":"353832","sourceNumber":"353832","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"De acordo com a Diretriz da Sociedade Brasileira de Cardiologia sobre Angina Instável\ne Infarto Agudo do Miocárdio sem\nSupradesnível do Segmento ST (SCASSST), julgue as seguintes\nafirmações como verdadeiras (V) ou falsas (F). 1. O uso de AAS é recomendado na sala de\nemergência o mais precoce possível em todos os pacientes sem contraindicação, em dose inicial\nde 150 a 300 mg e dose de manutenção de 75 a 100 mg. 2. Os Anti-Inflamatórios Não Esteroides\n(AINE) são preconizados para controle da dor em pacientes com infarto agudo do miocárdio. 3. É\nindicado iniciar o tratamento com nitrato para alívio da angina na sala de emergência, sendo\nadministrado inicialmente por via sublingual, e, caso não haja melhora rápida da dor, a\nadministração intravenosa é recomendada. Sendo (V) para verdadeiro e (F) para falso, é\nCORRETO afirmar:","options":{"A":"1F ? 2V ? 3F.","B":"1V ? 2V ? 3F.","C":"1F ? 2F ? 3V.","D":"1V ? 2F ? 3V."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-334095","number":"334095","sourceNumber":"334095","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O ecocardiograma sob estresse pode ser recomendado para estratificação de risco de\npacientes em unidades de dor torácica:","options":{"A":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado inconclusivo, uma vez aliviada a dor por pelo menos 24h\nem pacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e\nmarcadores de necrose.","B":"Especialmente quando o ECG define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado inconclusivo, uma vez aliviada a dor por pelo menos 24h\nem pacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e\nmarcadores de necrose.","C":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico não é submáximo,\nde realização factível ou com resultado\ninconclusivo, uma vez aliviada a dor por pelo menos 24h em\npacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e marcadores\nde necrose.","D":"Especialmente quando o ECG não define o diagnóstico e o teste ergométrico é submáximo, de\nrealização não factível ou com resultado conclusivo, uma vez aliviada a dor por pelo menos 4h em\npacientes de baixo a moderado risco e sem alterações isquêmicas evidentes no ECG e marcadores\nde necrose."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-334097","number":"334097","sourceNumber":"334097","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em pacientes com dor torácica aguda e ECG não diagnóstico:","options":{"A":"O uso da ecocardiografia com contraste reduz a sensibilidade para o diagnóstico da síndrome\ncoronariana aguda - SCA.","B":"O uso da ecocardiografia sem contraste não aumenta a sensibilidade para o diagnóstico da\nsíndrome coronariana aguda - SCA.","C":"O uso da ecocardiografia com contraste não aumenta a sensibilidade para o diagnóstico da\nsíndrome coronariana aguda - SCA.","D":"O uso da ecocardiografia com contraste aumenta a sensibilidade para o diagnóstico da síndrome\ncoronariana aguda - SCA."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-334773","number":"334773","sourceNumber":"334773","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente do sexo masculino, diabético, com 62 anos de idade, foi submetido à\nangioplastia coronariana com implante de stent há 7 dias, na vigência de quadro de infarto agudo\ndo miocárdio sem supradesnivelamento do segmento ST. No seguimento ambulatorial deste\npaciente é importante garantir que","options":{"A":"a terapia de dupla antiagregação plaquetária seja mantida por no máximo seis meses após o\ninfarto.","B":"os fármacos análogos do GLP-1 não sejam associados ao esquema terapêutico antes de 30\ndias do infarto.","C":"o nível máximo de LDL-C em 50 mg/dL deve ser alcançado o mais brevemente possível.","D":"o ácido acetilsalicílico seja suspenso, em pacientes com ritmo sinusal, após doze meses do\ninfarto."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-330069","number":"330069","sourceNumber":"330069","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dispneia é um termo que indica uma experiência subjetiva de dificuldade ou\ndesconforto respiratório, que consiste em\nsensações qualitativamente distintas, de intensidade\nvariável, e é traduzida por diferentes sinais semiológicos. Podem acontecer manifestações de\ndispneia quando o paciente assume uma posição reclinada, comum em portadores de Insuficiência\nCardíaca Congestiva (ICC). Esta afirmação refere-se a:","options":{"A":"Ortopneia.","B":"Trepopneia.","C":"Platipneia.","D":"Disparapneia."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-339771","number":"339771","sourceNumber":"339771","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após 3\ndias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte: O\nquadro clínico apresentado sugere como diagnóstico:","options":{"A":"infarto agudo do miocárdio com supra desnivelamento do segmento ST.","B":"dissecção de coronária.","C":"miopericardite.","D":"vasoespasmo coronariano."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-339772","number":"339772","sourceNumber":"339772","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nQual dos exames a seguir deverá ser solicitado nesse caso?","options":{"A":"Cateterismo cardíaco.","B":"Angiotomografia de coronárias.","C":"Cintilografia do miocárdio.","D":"Ecocardiograma."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-339773","number":"339773","sourceNumber":"339773","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nNesse caso, o tratamento adequado é o da indicação de","options":{"A":"aspirina e clopidogrel.","B":"anti-inflamatório não hormonal e colchicina.","C":"corticosteroides e nitrato.","D":"heparina, aspirina e clopidogrel."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-339774","number":"339774","sourceNumber":"339774","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 61 anos de idade, sedentário, obeso e tabagista, há duas horas iniciou\nepigastralgia em queimação de forte intensidade após o almoço. O exame físico mostrou uma\nfrequência cardíaca igual a 60 bpm, frequência respiratória = 25 irpm, SatO2 = 92% e PA = 100\nmmHg x 60 mmHg, com ausculta cardíaca e pulmonar normais e sem edema de membros\ninferiores. Na admissão em uma unidade de pronto atendimento, ele realizou o eletrocardiograma\n(ECG) a seguir. Qual é a principal hipótese de diagnóstico?","options":{"A":"Bloqueio de ramo direito.","B":"Infarto agudo do miocárdio","C":"Síndrome de Wolf Parkinson White","D":"Hipertonia vagal","E":"Fibrilação atrial"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-346432","number":"346432","sourceNumber":"346432","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Você está de plantão no pronto socorro do hospital e existem 04 pacientes na sala\nvermelha. Assinale qual dos pacientes possui indicação de trombólise endovenosa de urgência,\nconsiderando ausência de contra indicações?","options":{"A":"Homem de 40 anos, diabético e hipertenso, apresentou episódio de perda de força à direita e\ndificuldade para falar há 05 horas. EF: Hemiplegia à direita e Afasia motora. Exames\nComplementares: TC Crânio Sem alterações;","B":"Mulher de 55 anos, tabagista 40 anos/maço, apresentou episódio de dor torácica, em opressão,\nde forte intensidade, com irradiação para o\nmembro superior esquerdo e mandíbula há 11 horas.\nExames Complementares: ECG Supra de segmento ST em parede anterior;","C":"Homem de 35 anos, submetido a cirurgia de joelho esquerdo há 01 semana, apresentou\nepisódio de dor em membro inferior esquerdo há\n06 horas. EF: Dor à palpação de panturrilha\nesquerda. Exames Complementares: USG Doppler Venoso de Membro Inferior Esquerdo:\nTrombose venosa profunda extensa;","D":"Mulher de 35 anos, em uso de anticoncepcional oral, apresentou episódio de dor torácica\nventilatória dependente à esquerda há 03 horas, sem\ninstabilidade hemodinâmica. Exames\nComplementares: Angio TC Tórax, com presença de TEP Defeitos de enchimento completos dos\nramos inferiores dos lobos médio e inferiores pulmonares."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-321608","number":"321608","sourceNumber":"321608","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após 3\ndias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte: O\nquadro clínico apresentado sugere como diagnóstico:","options":{"A":"infarto agudo do miocárdio com supra desnivelamento do segmento ST.","B":"dissecção de coronária.","C":"miopericardite.","D":"vasoespasmo coronariano."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-337459","number":"337459","sourceNumber":"337459","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A adição do escore de cálcio coronário aos de riscos clínicos:","options":{"A":"Tem figurado como a alternativa mais eficiente e não custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário.","B":"Tem figurado como a alternativa mais eficiente e custo-efetiva na atualidade para estimar o risco\nde doença arterial coronariana (DAC) em pacientes com risco intermediário.","C":"Não Tem figurado como a alternativa mais eficiente e custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário.","D":"Tem figurado como a alternativa menos eficiente e custo-efetiva na atualidade para estimar o\nrisco de doença arterial coronariana (DAC) em pacientes com risco intermediário."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-321609","number":"321609","sourceNumber":"321609","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nQual dos exames a seguir deverá ser solicitado nesse caso?","options":{"A":"Cateterismo cardíaco.","B":"Angiotomografia de coronárias.","C":"Cintilografia do miocárdio.","D":"Ecocardiograma."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-321610","number":"321610","sourceNumber":"321610","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um jovem previamente hígido de 22 anos dá entrada na emergência com dor em\npontada no hemitórax esquerdo e febre após\n3 dias de um quadro de gastroenterocolite aguda. Ao\nexame físico, apresentava com FC = 70bpm, PA 100x60mmHg e Temp. 37,8º. A dosagem\nlaboratorial de troponina foi de 2.000ng/ml (VR < 0,04ng/ml) e o eletrocardiograma foi o seguinte:\nNesse caso, o tratamento adequado é o da indicação de","options":{"A":"aspirina e clopidogrel.","B":"anti-inflamatório não hormonal e colchicina.","C":"corticoesteroides e nitrato.","D":"heparina, aspirina e clopidogrel."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-337466","number":"337466","sourceNumber":"337466","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"De forma concordante, o uso de estatinas em pacientes com doença arterial\ncoronariana (DAC) parece estabilizar placas ateroscleróticas:","options":{"A":"Não podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear\nnão apenas entre a redução do LDL-c e a taxa de eventos doença cardiovascular CV, mas também\nentre o nível de LDL-c e a progressão do volume de ateroma em carótidas.","B":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e não para a\ntaxa de eventos doença cardiovascular CV, mas\ntambém entre o nível de LDL-c e a progressão do volume de ateroma em carótidas.","C":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e a taxa de\neventos doença cardiovascular CV, e não para o\nnível de LDL-c e a progressão do volume de ateroma em carótidas.","D":"Podendo até produzir sua regressão volumétrica, com uma relação aproximadamente linear não\napenas entre a redução do LDL-c e a taxa de\neventos doença cardiovascular CV, mas também\nentre o nível de LDL-c e a progressão do volume de ateroma em carótidas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-315764","number":"315764","sourceNumber":"315764","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Nos pacientes que chegam ao serviço de emergência com menos de 3h do início do\nquadro de dor:","options":{"A":"As Trop-US são significativamente mais sensíveis que a troponina convencional para diagnóstico\nde SCA, melhorando em 61% o poder diagnóstico\nde IAM naquele momento e em 100% se a\ncoleta for 6h após o início do quadro.","B":"As Trop-US são significativamente menos sensíveis que a troponina convencional para\ndiagnóstico de SCA, melhorando em 61% o poder diagnóstico de IAM naquele momento e em\n100% se a coleta for 6h após o início do quadro.","C":"As Trop-US são significativamente mais sensíveis que a troponina convencional para\ndiagnóstico de SCA, piorando em 61% o poder\ndiagnóstico de IAM naquele momento e em 100%\nse a coleta for 6h após o início do quadro.","D":"As Trop-US são significativamente mais sensíveis que a troponina convencional para\ndiagnóstico de SCA, melhorando em 61% o poder\ndiagnóstico de IAM naquele momento e em\n100% se a coleta for 1h após o início do quadro."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-315767","number":"315767","sourceNumber":"315767","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dose de enoxaparina é de 1mg/kg administrado por via subcutânea (SC) duas vezes\nao dia. Na idade superior a 75 anos, a dose\ndeve ser reduzida para 0,75mg/kg duas vezes ao dia.\nSendo correto que:","options":{"A":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida por\n10, sendo então administrado 0,1mg/ kg (SC) uma\nvez ao dia.","B":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida\npela metade, sendo então administrado 1mg/ kg (SC)\nduas vezes ao dia.","C":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose não deve ser reduzida.","D":"Em pacientes com a taxa de filtração glomerular estimada (TFGe) igual ou inferior a\n30mL/min/1,73m2, a dose deve ser reduzida\npela metade, sendo então administrado 1mg/ kg (SC)\numa vez ao dia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-300807","number":"300807","sourceNumber":"300807","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerando as partes que recorrentemente classificam a anamnese, quanto ao\nelemento ?antecedentes pessoais?, é CORRETO afirmar:","options":{"A":"Pergunta-se sobre o início dos sintomas, como evoluíram e como estão no momento.","B":"Pergunta-se sobre a sua atual profissão e se o paciente utiliza algum equipamento de proteção.","C":"É de suma precisão para que se possa obter do paciente se ele possui algum tipo de alergia e\nintolerância a medicações e alimentos.","D":"Pergunta-se se o paciente é fumante ativo ou passivo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-315777","number":"315777","sourceNumber":"315777","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com a introdução das troponinas de alta sensibilidade (Trop-US), está correto o item:","options":{"A":"Passou a ser possível a detecção de níveis mais baixos de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","B":"Passou a ser impossível a detecção de níveis mais baixos de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","C":"Passou a ser possível a detecção de níveis mais elevados de troponina, em menor tempo após\ninício do quadro de lesão miocárdica de causa isquêmica.","D":"Passou a ser possível a detecção de níveis mais baixos de troponina, em maior tempo após\ninício do quadro de lesão miocárdica de causa isquêmica."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-316328","number":"316328","sourceNumber":"316328","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 78 anos, sexo masculino, hipertenso de longa data, com histórico de\ntabagismo importante, inicia quadro súbito de dor torácica em região dorsal com irradiação para\ntórax associado a mal-estar intenso e tontura. Chega ao PS, e na avaliação, apresenta-se com\ndiscordância de pressão em membros superiores. PA MSD 80x50/ PA MSE 150x80 associado a\nsopro diastólico aspirativo aórtico importante. Radiografia de tórax com evidência de alargamento\nmediastinal importante e com exames complementares, realizado o diagnóstico de dissecção de\naorta torácica ascendente, limitando até o tronco da aorta. Qual é a classificação de acordo com a\nclassificação de Stanford e DeBakey?","options":{"A":"Stanford tipo A e DeBakey tipo I.","B":"Stanford tipo A e DeBakey tipo II.","C":"Stanford tipo B e DeBakey tipo I.","D":"Stanford tipo B e DeBakey tipo II."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-316331","number":"316331","sourceNumber":"316331","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 24 anos, sem comorbidades, com histórico de internação recente por\ncovid-19, procura novamente o PS devido ao\nquadro de dor torácica com início há 3 dias com piora\ngradativa. Relata que ao decúbito e também a inspiração profunda apresenta piora significativa.\n\nRealizado o ECG (mostrado a seguir) logo na admissão junto com 2 coletas de marcadores de\nnecrose miocárdica - Troponina (VR <0,2) -> 1º: 0,45/ 2º:2,3. De acordo com o caso, qual o\ndiagnóstico mais provável?","options":{"A":"SCA com supradesnivelamento do segmento ST.","B":"SCA sem supradesnivelamento do segmento ST.","C":"Miopericardite.","D":"Sd. de Takotsubo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308281","number":"308281","sourceNumber":"308281","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica aguda é, por vezes, um desafio diagnóstico. A propedêutica é imperativa\npara direcionar a investigação e otimizar a\nprobabilidade pós teste para tomada de decisão. Muitas\nvezes, situações incomuns podem se tornar um desafio diagnóstico. Neste contexto responda as\nquestões que se seguem. Sobre a dissecção aórtica é correto afirmar:","options":{"A":"A terapia deve ser iniciada imediatamente assim que a hipótese é considerada.","B":"Redução da frequência cardíaca e da pressão arterial são a base do tratamento inicial.","C":"Hipotensão contraindica a conduta da letra b.","D":"Todas alternativas estão corretas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308282","number":"308282","sourceNumber":"308282","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica aguda é, por vezes, um desafio diagnóstico. A propedêutica é imperativa\npara direcionar a investigação e otimizar a\nprobabilidade pós teste para tomada de decisão. Muitas\nvezes, situações incomuns podem se tornar um desafio diagnóstico. Neste contexto responda as\nquestões que se seguem. Em relação as doenças reumatológicas que podem estar associadas a\ndilatação da aorta é correto afirmar como causas, exceto:","options":{"A":"Arterite de takayasu.","B":"Células gigantes.","C":"Aortite reumatoide.","D":"Doença condroblástica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-273122","number":"273122","sourceNumber":"273122","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A anamnese possui elementos estruturais que buscam trazer fatos e dados de grande\nrelevância para a construção do raciocínio diagnóstico que, a partir da história clínica do\npaciente,\nbem como do conhecimento de determinados fatores a ele relacionados, possibilitam a definição da\nestratégia a ser utilizada para exames complementares e procedimentos medicinais adequados\ndiante do diagnóstico do paciente. Faz parte da estrutura da anamnese:","options":{"A":"O reconhecimento.","B":"Histórico de doenças futuras.","C":"Queixa e duração.","D":"Hábitos religiosos."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-274749","number":"274749","sourceNumber":"274749","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, procura atendimento médico em unidade de\npronto socorro com queixa de dispneia e dor\ntorácica há 02 horas. Foi realizada angiotomografia de\ntórax a qual identificou uma dissecção da aorta tipo II de DeBakey. Após admissão clínica e\navaliação por angiotomografia, o referido paciente apresentou sinais de instabilidade\nhemodinâmica. Considerando o quadro clínico do paciente relatado qual tratamento a ser realizado\nimediatamente?","options":{"A":"Internação em leito de Unidade de Terapia Intensiva para acompanhamento rigoroso e\nrealização de angiotomografia seriada por um período de 24 horas.","B":"Internação em leito de Unidade de Terapia Intensiva para terapia medicamentosa\n\"\"anti-hipertensiva\"\" por um período de 24 horas.","C":"Tratamento cirúrgico em caráter emergencial para reparo da aorta ascendente.","D":"Tratamento cirúrgico em caráter eletivo com implante de endoprótese em aorta descendente."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-273207","number":"273207","sourceNumber":"273207","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Considerando os evidentes benefícios da prática de atividade física para a saúde e\nseus possíveis riscos, uma exposição\nequilibrada de riscos e benefícios e uma avaliação das\ncaracterísticas e adaptações necessárias de determinados indivíduos e grupos são elementos\nessenciais de uma boa prática assistencial, a qual busca evitar o risco de agravos que derivam da\nprática de:","options":{"A":"Atividades de maior intensidade e menor duração na presença de condições favorecedoras,\ncomo lesões preexistentes e obesidade.","B":"Atividades de menor intensidade e maior duração na presença de condições desfavorecedoras,\ncomo lesões preexistentes e obesidade.","C":"Atividades de maior intensidade e maior duração na presença de condições favorecedoras,\ncomo lesões preexistentes e obesidade.","D":"Atividades de menor intensidade e menor duração na presença de condições desfavorecedoras,\ncomo lesões preexistentes e obesidade."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-254211","number":"254211","sourceNumber":"254211","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem 54 anos, obeso, hipertenso e diabético, admitido no PA com quadro de dor\ntorácica típica e eletrocardiograma\nevidenciando supradesnívelamento de segmento ST em D2, D3\ne avF. Ao exame físico, apresentava-se acordado, consciente, orientado, com taquidispneia,\nestertor crepitante bibasal, turgência jugular, PA 140x90mmHg, tempo de enchimento capilar 2seg.\nBaseadonos dados apresentados, pode-se classificar o paciente em qual classe de Killip:","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-229499","number":"229499","sourceNumber":"229499","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Nas síndromes coronarianas agudas que podem estar acompanhadas de elevação da\nPA, devido a um reflexo do miocárdio isquêmico, somente podemos CONCORDAR que:","options":{"A":"O aumento da RVP eleva a demanda de oxigênio miocárdico, pelo aumento da tensão parietal\ndo ventrículo esquerdo.","B":"Os nitratos IV reduzem a RVP, e pioram a perfusão coronariana.","C":"Os nitratos IV não possuem importante efeito vasodilatador sistêmico.","D":"Os nitratos IV reduzindo a pré-carga, mas não o consumo de oxigênio miocárdico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-249848","number":"249848","sourceNumber":"249848","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente S.G.A, do sexo masculino, de 66 anos, hipertenso, tabagista, diabético, em\nuso regular de losartana (50 mg/dia),\nmetformina (850 mg/dia) e de ácido acetilsalicílico (100\nmg/dia) há seis meses, deu entrada no pronto atendimento com dor precordial típica, de início há\ntrês horas e que melhorou com uso de nitrato. Após realizar os exames de emergência para\nsíndrome coronariana aguda (troponina positiva, creatinina 0,8 mg/dl, ureia 32 mg/dl e\neletrocardiograma). Nesse caso, o paciente","options":{"A":"deve ser estratificado invasivamente (cateterismo cardíaco), com urgência, por se tratar de uma\nsíndrome coronariana aguda com supra de ST.","B":"deve ser estratificado invasivamente (cateterismo cardíaco), de maneira precoce, por se tratar de\nalto risco cardiológico (TIMI RISK alto), com uma síndrome coronariana aguda sem supra de ST.","C":"deve ser encaminhado para estratificação não invasiva, por se tratar de um paciente de baixo\nrisco cardiológico (TIMI RISK baixo), com uma síndrome coronariana aguda sem supra de ST.","D":"deve ser trombolisado, por se tratar de síndrome coronariana aguda, na falta de estratificação\ninvasiva (cateterismo cardíaco)."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-232225","number":"232225","sourceNumber":"232225","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Leia o caso clínico a seguir. Um paciente de 80 anos dá entrada no pronto-socorro com\nforte dor no peito, há 30 minutos, associada à sudorese. À admissão, observam-se um ritmo\nregular, FC = 80 bpm, PA = 80 x 55 mmHg e SatO? = 95%. O ECG mostrou supradesnivelamento\ndo segmento ST de V1 a V4. Nesse caso, a conduta imediata é:","options":{"A":"Dosar enzimas cardíacas.","B":"Avaliar função renal.","C":"Iniciar noradrenalina.","D":"Realizar revascularização percutânea."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-229866","number":"229866","sourceNumber":"229866","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Gilmar, 52 anos, gari, vem à consulta na Unidade Básica de Saúde com queixa de dor\nno peito há 2 meses. A dor aparece quando\nestá trabalhando e precisa correr ou carregar muito\npeso. Sente como um peso atrás do peito, que dura um 1 minuto e melhora quando fica em\nrepouso. Ele é tabagista, fuma 1 maço/dia há 20 anos, e hipertenso, faz uso de captopril quando a\npressão sobe. O risco cardiovascular calculado na consulta é de 34% e a probabilidade pré-teste\npara doença coronariana é maior que 90%. A alternativa que não corresponde ao caso de Gilmar é","options":{"A":"se o teste ergométrico não evidenciar sinais de isquemia miocárdica, é necessário iniciar\ninvestigação para outras etiologias de dor torácica como causas esofágicas e pulmonares;","B":"caso a dor de Gilmar apresente piora progressiva, com episódios de dor com duração maior e\ncom menor limiar de esforço, é necessário manejar como síndrome coronariana aguda;","C":"em caso de um episódio de dor torácica maior do que 20 minutos, no momento do atendimento\nmédico, é importante obter um\neletrocardiograma e oferecer 300 mg de ácido acetilsalicílico (AAS);","D":"no caso de Gilmar, é recomendado o início de beta-bloqueadores, que podem promover alívio\nsintomático da angina."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-247467","number":"247467","sourceNumber":"247467","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Doença Cardiovascular (CV) aterosclerótica é, em termos proporcionais, a principal\ncausa da mortalidade em países desenvolvidos e em muitos países em desenvolvimento como o\nBrasil. Nos últimos anos, ensaios clínicos randomizados e revisões sistemáticas vêm apontando\navanços no potencial de prevenção dessas doenças. Em relação a prevenção das doenças\ncardiovasculares tem-se o seguinte:","options":{"A":"a alimentação saudável é um dos pilares da prevenção cardiovascular, porém nenhuma\nintervenção nutricional específica mostrou-se efetiva na redução de eventos CV.","B":"evidências consistentes de estudos observacionais demonstram que a realização de atividade\nfísica está associada à redução do risco de\neventos CV tanto em homens quanto em mulheres,\nindependente da idade e intensidade desta atividade.","C":"em prevenção secundária, o uso de alguns fármacos anti-hipertensivos está associado a uma\nredução de eventos CV mesmo em pacientes sem hipertensão.","D":"ensaios clínicos randomizados recentes têm demonstrado que terapia de reposição hormonal\ndiminuiram os eventos CV."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-254291","number":"254291","sourceNumber":"254291","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Manoel é um homem de 55 anos, branco, sedentário, hipertenso, que chega até a\nunidade de saúde com a expectativa de fazer exames. Diz que utiliza losartana 50 mg de 12/12\nhoras há 10 anos e que acredita que a medicação esteja fraca, pois a pressão tem ficado\ndescontrolada. Entendendo o contexto de Manoel, você solicita exames complementares, os quais\nmostram os resultados a seguir: Colesterol total = 195; HDL = 40; LDL = 120; Triglicérides = 230;\nGlicemia de jejum = 108; Hemoglobina glicada = 5,6%; Creatinina = 0,7; EAS = sem alterações;\nEletrocardiograma = normal; Medida ambulatorial de pressão arterial (MAPA) = PA média de 145 x\n78 mmHg; Após analisá-los, você decide calcular o risco cardiovascular de Manoel por meio da\ncalculadora Framingham, cujo desfecho é de 21,40%. Diante do risco cardiovascular aferido, a\nmelhor conduta é:","options":{"A":"Prescrever AAS diário e estimular perda de peso.","B":"Prescrever ciprofibrato e sinvastatina, para repetir lipidograma em 3 meses.","C":"Prescrever sinvastatina e estimular exercícios físicos.","D":"Prescrever metformina e aumentar a dose de losartana."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-254292","number":"254292","sourceNumber":"254292","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Manoel é um homem de 55 anos, branco, sedentário, hipertenso, que chega até a\nunidade de saúde com a expectativa de\nfazer exames. Diz que utiliza losartana 50 mg de 12/12\nhoras há 10 anos e que acredita que a medicação esteja fraca, pois a pressão tem ficado\ndescontrolada. Entendendo o contexto de Manoel, você solicita exames complementares, os quais\nmostram os resultados a seguir: Colesterol total = 195; HDL = 40; LDL = 120; Triglicérides = 230;\nGlicemia de jejum = 108; Hemoglobina glicada = 5,6%; Creatinina = 0,7; EAS = sem alterações;\nEletrocardiograma = normal; Medida ambulatorial de pressão arterial (MAPA) = PA média de 145 x\n78 mmHg; Após analisá-los, você decide calcular o risco cardiovascular de Manoel por meio da\ncalculadora Framingham, cujo desfecho é de 21,40%. Imagine que Manoel retorne à UBS e relate o\nsurgimento, há 4 meses, de dor retroesternal ao realizar esforços mais intensos, com melhora ao\nrepouso, de caráter não progressivo. Para compreender melhor a probabilidade de se tratar de um\nquadro de doença arterial coronariana, você pesquisa pela tabela abaixo: Dentre as opções abaixo,\naquela que representa a melhor conduta diante da suspeita de angina é:","options":{"A":"Solicitar teste de esforço para estratificação de risco, devido à alta probabilidade pré-teste de\nangina estável.","B":"Encaminhar para serviço de urgência devido ao risco de angina instável.","C":"Solicitar cintilografia miocárdica para estabelecer diagnóstico definitivo.","D":"Manter a losartana 100 mg/dia e acrescentar AAS e furosemida."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-201903","number":"201903","sourceNumber":"201903","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 56 anos procura o pronto-socorro por dor torácica, referindo pressão\nretroesternal, irradiada para a mandíbula, desencadeada por esforço, melhorando após 3 minutos\nem repouso, que não se altera com a posição ou com a ventilação. O paciente é atendido 1 hora\napós e no momento está assintomático. O eletrocardiograma é normal. A alternativa que melhor\nrelaciona a hipótese mas provável e a conduta, respectivamente, nesse momento, é:","options":{"A":"angina de peito ? dosagem de troponina","B":"infarto agudo do miocárdio - ecocardiograma","C":"infarto agudo do miocárdio - coronariografia","D":"dissecção de aorta ? radiografia de tórax","E":"angina de peito ? teste de esforço"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-218210","number":"218210","sourceNumber":"218210","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente com suspeita de Infarto Agudo do Miocárdio (IAM) realiza no pronto\natendimento um eletrocardiograma que revela\na presença de Bloqueio do Ramo Esquerdo (BRE).\nSobre o quadro acima exposto, assinale a alternativa CORRETA:","options":{"A":"A presença do BRE torna menos provável um quadro de IAM.","B":"Se o paciente apresentar no pronto atendimento um teste ergométrico realizado há 2 anos com\nBRE no traçado de repouso, fica menos\nprovável um quadro de IAM.","C":"Na vigência do BRE, a presença de uma elevação do segmento ST de 2 mm em V1 e V2 torna o\ntraçado favorável a um quadro de IAM, com provável acometimento de artéria descendente\nanterior.","D":"Na vigência do BRE, a presença de uma elevação do segmento ST de 1 mm em D1 e aVL com\ncomplexos QRS positivos torna o traçado favorável a um quadro de IAM."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-205559","number":"205559","sourceNumber":"205559","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Calcificação Arterial Coronariana (CAC) está associada à mortalidade em pacientes\ncom diabetes, podendo ser considerada marcador\nde carga de placa aterosclerosclerótica, já\ndemonstrado em análise anatômica. Podemos assim, aceitar que:","options":{"A":"Em pacientes sem diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","B":"Em pacientes com diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","C":"Em pacientes com diabetes, CAC > 5 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 10 sejam considerados de alto\nrisco cardiovascular.","D":"Em pacientes com diabetes, CAC > 10 é preditor de mortalidade e eventos cardiovasculares\nfuturos. Recomenda-se que pacientes com diabetes, com\nCAC > 12 sejam considerados de alto\nrisco cardiovascular."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-205573","number":"205573","sourceNumber":"205573","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A alternativa para o rastreio de isquemia é a ecocardiografia de estresse, usando\nexercício ou estresse farmacológico com\ndobutamina. Sensibilidade e especificidade são 81 e 85%,\nrespectivamente, em pacientes diabéticos assintomáticos. Sendo CORRETO que:","options":{"A":"O ecocardiograma de estresse não detecta possíveis anormalidades no movimento segmentar\nda parede ventricular, fornecendo informações\nsobre a intensidade da isquemia e a função\nventricular esquerda.","B":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento segmentar da\nparede ventricular, fornecendo informações sobre\na intensidade da isquemia e a função ventricular\nesquerda.","C":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento global apenas da\nparede ventricular, fornecendo informações sobre a intensidade da isquemia e a função ventricular\nesquerda.","D":"O ecocardiograma de estresse detecta possíveis anormalidades no movimento segmentar da\nparede ventricular, não fornecendo informações sobre a intensidade da isquemia e a função\nventricular esquerda."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-217026","number":"217026","sourceNumber":"217026","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A respeito do manejo clínico da Síndrome Coronariana Aguda, assinale a alternativa\ncorreta.","options":{"A":"O uso de betabloqueador em pacientes com essa síndrome implica redução da mortalidade.","B":"Hipoperfusão, broncoespasmo e tabagismo são contraindicações ao betabloqueador.","C":"A enoxaparina apresenta maior incidência de plaquetopenia que a heparina não fracionada.","D":"Deve-se evitar o uso de nitratos no caso de crepitações ou na presença de B3.","E":"A prescrição de inibidor de ECA e do AAS deve ser precoce à admissão."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-202712","number":"202712","sourceNumber":"202712","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Do ponto de vista do ciclo cardíaco,","options":{"A":"o componente tricuspídeo (T1) da primeira bulha ocorre antes do componente mitral (M1), pois a\npressão diastólica final do átrio direito é menor que a do átrio esquerdo.","B":"o componente aórtico (A2) da segunda bulha ocorre antes do componente pulmonar (P2), pois a\npressão gerada pela contração do ventrículo esquerdo é maior que a gerada pelo ventrículo direito.","C":"o desdobramento fisiológico da segunda bulha ocorre durante a expiração.","D":"o bloqueio de ramo direito é o responsável pelo desdobramento paradoxal da segunda bulha."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-216683","number":"216683","sourceNumber":"216683","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sabe-se que a troponina, CPK e a fração MB, possuem valores diagnósticos no infarto\nagudo do miocárdio. Temos ciência de que a\ntroponina após o início da dor se eleva de 4-6 horas e\napresenta seu pico de 12-48 horas. Considerando-se essas informações, em quanto tempo ela se\nnormaliza?","options":{"A":"De 7 a 14 dias.","B":"De 1 a 3 dias.","C":"De 3 a 5 dias.","D":"Após 16 dias."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175381","number":"175381","sourceNumber":"175381","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O átrio direito é a câmara cardíaca que normalmente recebe o sangue venoso\nsistêmico. Nessa câmara, encontra-se a valva de Eustáquio, que se relaciona com:","options":{"A":"veia cava inferior","B":"crista terminalis","C":"veia cava superior","D":"seio coronário","E":"junção átrio ventricular direita"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174409","number":"174409","sourceNumber":"174409","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Diversos estudos utilizaram fibrinolíticos fora do ambiente hospitalar com condições\noperacionais apropriadas para seu uso, e para a monitorização tanto clínicas como\neletrocardiográfica pré-hospitalar dos pacientes e para o tratamento das taquiarritmias. Esses\nestudos consolidaram alguns conceitos, dos apresentados nas alternativas a seguir, assinale o\nINCORRETO.","options":{"A":"A utilização da terapêutica fibrinolítica pré hospitalar baseia-se no conceito clássico\nexperimental\nde que, ao se abreviar o tempo de isquemia\nmiocárdica aguda, reduz-se o tamanho do infarto do\nmiocárdio.","B":"Quanto mais precoce é administrada a terapêutica fibrinolítica, menores a mortalidade e o grau\nde disfunção ventricular.","C":"O retardo pré-hospitalar, intervalo entre o início dos sintomas isquêmicos e a chegada ao\nhospital, não é um dos determinantes do\ntamanho do infarto e da mortalidade pré e intra-hospitalar.","D":"O retardo pré-hospitalar, esse tempo é de, em média, 3 a 4 horas. A utilização pré-hospitalar da\nterapêutica fibrinolítica visa reduzir esse retardo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-175391","number":"175391","sourceNumber":"175391","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 56 anos procura o pronto-socorro por dor torácica, referindo pressão\nretroesternal, irradiada para a mandíbula, desencadeada por esforço, melhorando após 3 minutos\nem repouso, que não se altera com a posição ou com a ventilação. O paciente é atendido 1 hora\napós e no momento está assintomático. O eletrocardiograma é normal. A alternativa que melhor\nrelaciona a hipótese mais provável e a conduta, respectivamente, nesse momento, é:","options":{"A":"angina de peito ? dosagem de troponina","B":"infarto agudo do miocárdio ? ecocardiograma","C":"infarto agudo do miocárdio ? coronariografia","D":"dissecção de aorta ? radiografia de tórax","E":"angina de peito ? teste de esforço"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174422","number":"174422","sourceNumber":"174422","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentro do uso de medicamentos para tratamento de Síndromes Coronarianas,\npodemos apenas afirmar como CORRETO o seguinte item a\nrespeito do Ácido acetilsalicílico:","options":{"A":"Um dos muitos antiinflamatórios indicados rotineiramente para todos os pacientes com suspeita\nde IAM.","B":"Pacientes com maior risco de doença coronária devem ser instruídos por seus médicos\nassistentes a tomar Ácido Acetilsalicílico (AAS) tamponado em situações emergenciais.","C":"É o antiplaquetário de eleição a ser utilizado no IAM, tendo sido demonstrado sua eficácia.","D":"Tem ação antagônica com o próprio fibrinolítico, levando à associação de ambos os\nmedicamentos a um acréscimo na mortalidade."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174451","number":"174451","sourceNumber":"174451","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quanto ao uso de nitratos nas Síndromes Coronarianas Agudas, podemos considerar\ncomo INCORRETA a alternativa:","options":{"A":"Podem ser utilizados na formulação sublingual (nitroglicerina, mononitrato de isossorbida ou\ndinitrato de isossorbida), para reversão de eventual espasmo e/ou para alívio da dor anginosa.","B":"Não estão recomendados para controle da hipertensão arterial ou alívio da congestão pulmonar,\nse presentes.","C":"Estão contraindicados na presença de hipotensão arterial (Pressão Arterial Sistólica - PAS <\n90mmHg).","D":"Estão contraindicados com o uso prévio de sildenafil ou similares nas últimas 24 horas e quando\nhouver suspeita de comprometimento do\nVentrículo Direito (VD)."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-173504","number":"173504","sourceNumber":"173504","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As complicações relacionadas com a doença coronária e, especificamente, com o\nInfarto Agudo do Miocárdio (IAM) são diversas e\nfrequentes. É uma complicação mecânica do IAM:","options":{"A":"Trombose coronariana.","B":"Dissecção coronariana.","C":"Aneurisma de ventrículo esquerdo.","D":"Bloqueio Atrioventricular Total (BAVT)."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174433","number":"174433","sourceNumber":"174433","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Durante avaliação médica da sala de emergência coronariana, foi solicitado que você\ndesse um parecer fundamentado a respeito da\ncontraindicação de betabloqueadores. Dessa forma,\nem relação aos betabloqueadores, é CORRETO afirmar:","options":{"A":"Na ausência de contraindicações, essa classe de medicamentos deve ser iniciada, de\npreferência, por via endovenosa, após a admissão do paciente.","B":"A utilização de betabloqueador endovenoso deve ser feita com critério, sendo recomendado\natualmente de se utilizar o betabloqueador por via endovenosa nas primeiras 48 horas,\nreservando-se a via endovenosa para casos selecionados, como em pacientes hipertensos e\ntaquicardíacos.","C":"Recomenda-se iniciar o betabloqueador e titular sua dose para um alvo de 60 batimentos por\nminutos.","D":"Pacientes com contraindicação para o uso precoce dos betabloqueadores não devem ser\nreavaliados para candidatos a essa terapia na prevenção secundária."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-173520","number":"173520","sourceNumber":"173520","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente dá entrada no pronto-socorro com síndrome coronariana aguda sem\nsupradesnivelamento do segmento ST. A qual tipo de conduta médica esse paciente não poderá\nser submetido?","options":{"A":"Aspirina.","B":"Heparina.","C":"Trombolítico.","D":"Betabloqueador."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-173526","number":"173526","sourceNumber":"173526","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 55 anos dá entrada no pronto-socorro com queixa de forte dor no peito, há\n30 minutos, associada a mal-estar, sudorese e\nconfusão mental. Ao exame fisico, observam-se\nritmo cardíaco regular, FC 65 bpm, PA 200x140mmHg no membro superior direito e PA\n140x90mmHg no membro superior esquerdo, além de sopro sistólico em carótida direita. O\ndiagnóstico mais provável é:","options":{"A":"acidente vascular cerebral isquêmico.","B":"síndrome coronariana aguda.","C":"urgência hipertensiva.","D":"dissecção de aorta."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-173531","number":"173531","sourceNumber":"173531","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 68 anos, hipertensa, fumante e diabética, dá entrada no pronto-socorro com\nforte dor no peito do tipo aperto e\nassociada a sudorese, náusea e palidez, iniciados há 45 minutos.\nO exame físico, o eletrocardiograma e as enzimas cardíacas, realizados imediatamente, foram\nnormais. Qual seria a conduta médica adequada?","options":{"A":"Administrar aspirina e clopidogrel, internar e seriar enzimas e ECG.","B":"Dar alta hospitalar e encaminhar para o ambulatório de cardiologia.","C":"Solicitar cateterismo cardiaco.","D":"Solicitar um teste isquêmico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182490","number":"182490","sourceNumber":"182490","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 54 anos chega ao pronto atendimento referindo desconforto torácico\ndescrito como sensação de peso e a localiza\ncolocando a mão no esterno, com irradiação para o\nombro esquerdo. O desconforto foi desencadeado após esforço físico habitual. Nega sintomatologia\nsemelhante. A dor aliviou 20 minutos após a chegada ao hospital. Tem diagnóstico, há 3 anos, de\ndislipidemia, e está em uso de sinvastatina 20mg/d. Nesse caso, qual é a hipótese diagnóstica?","options":{"A":"embolia de pulmão","B":"esofagite","C":"síndrome coronariana aguda","D":"pneumotórax"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-182494","number":"182494","sourceNumber":"182494","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual das doenças a seguir cursa mais habitualmente com pulso paradoxal?","options":{"A":"estenose aórtica","B":"pericardite constritiva","C":"insuficiência aórtica","D":"estenose mitral"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-185144","number":"185144","sourceNumber":"185144","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Na avaliação de um paciente com infarto agudo do miocárdio com supra de ST, cujos\nsintomas iniciaram há 18 horas, a coronariografia deve ser realizada","options":{"A":"em caráter de urgência, para a realização de angioplastia primária.","B":"na presença de isquemia refratária às medidas farmacológicas.","C":"apenas quando houver falência da terapia com fibrinolíticos.","D":"apenas nos pacientes de risco moderado a alto pelo escore TIMI."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-187602","number":"187602","sourceNumber":"187602","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino realizou um eletrocardiograma que evidenciou a presença de\ndepressão do segmento ST com inversão da\nonda T. O diagnóstico mais provável para o caso é:","options":{"A":"cardiopatia chagástica.","B":"hipertrofia de ventrículo direito.","C":"infarto agudo do miocárdio.","D":"bloqueio átrio ventricular;"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174427","number":"174427","sourceNumber":"174427","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale a alternativa que corresponde ao choque relacionado à coarctação de aorta:","options":{"A":"Hipovolêmico.","B":"Cardiogênico.","C":"Distributivo.","D":"Obstrutivo."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-178865","number":"178865","sourceNumber":"178865","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um adulto de 28 anos procura o serviço médico por causa de dores internas em região\ntorácica. Relata tratar-se de uma dor contínua em todo o hemitórax direito, que começou há\naproximadamente 2 dias, após um jogo de vôlei com os amigos. Em um Raio-X de tórax,\n\nobserva-se a seguinte condição: Após a realização do exame, o adulto refere que a dor piorou e\nobserva-se que ele está dispnéico, com FR = 28 irpm, e taquicárdico, com FC = 121 bpm. Pode-se\nconcluir que o paciente:","options":{"A":"está com um pneumotórax espontâneo que, devido aos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para um pneumotórax hipertensivo. A conduta é de\ntransferência para um serviço de saúde com maior capacidade; mas, caso o doente piore, é\nnecessário realizar a descompressão torácica.","B":"está com um provável tamponamento cardíaco que, em consequência dos sinais de instabilidade\nsúbitos após a realização do exame, está\naumentando rapidamente. A conduta é de tranferência\npara um serviço de saúde com maior capacidade; contudo, caso o doente piore, é necessário\nrealizar a punção de Marfan.","C":"está com uma pneumonia adquirida na comunidade que, pelos sinais de instabilidade súbitos\napós a realização do exame, está progredindo\npara um quadro séptico. A conduta é transferir para\num serviço de saúde com maior capacidade e iniciar hidratação.","D":"está com um tromboembolismo pulmonar que, pelos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para uma insuficiência respiratória. A conduta é é transferir\npara um serviço de saúde com maior capacidade, iniciar hidratação controlada e instalar cateter de\noxigênio a 2 L/min.","E":"está com um provável tumor pulmonar que, por causa dos sinais de instabilidade súbitos após a\nrealização do exame, está progredindo para uma insuficiência respiratória. A conduta é de\ntransferência para um serviço de saúde com maior capacidade, com sugestão de encaminhamento\npara o oncologista."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-174465","number":"174465","sourceNumber":"174465","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à necessidade do diagnóstico de Doença Aterosclerótica Coronariana\nSubclínica, marque a opção considerada INCORRETA:","options":{"A":"A identificação de indivíduos assintomáticos portadores de aterosclerose e, dessa forma, sob\nrisco de eventos cardiovasculares agudos, como o infarto e morte, é fundamental para se\ninstituírem medidas de tratamento e prevenção secundária.","B":"Diante da complexidade dessas interações, a atribuição intuitiva do risco frequentemente resulta\nem subestimação ou superestimação dos casos de\nmaior ou menor risco, respectivamente.","C":"Para contornar essa dificuldade, diversos algoritmos têm sido criados com base em análises de\nregressão de estudos populacionais, por meio dos quais a identificação do risco global é\nsubstancialmente aprimorada.","D":"A não identificação de indivíduos assintomáticos portadores de aterosclerose e, dessa forma,\nsob risco de eventos cardiovasculares agudos,\ncomo o infarto e morte, é de pouca importância em\ntermos de prevenção secundária."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-178766","number":"178766","sourceNumber":"178766","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 71 anos, chega à unidade de saúde, trazida por seu filho, referindo dor\ntorácica em aperto há aproximadamente 30\nminutos, além de sudorese intensa e mal-estar geral.\nNa avaliação da paciente, entende-se que os sintomas são sugestivos de isquemia ou infarto.\n\nPortanto, qual é a melhor conduta?","options":{"A":"Realizar um eletrocardiograma (ECG); administrar aspirina na dose de 500 mg sublingual;\nconsiderar administrar oxigênio (se saturação de\noxigênio \"menor ou igual\" 94%) e nitroglicerina\nsublingual. Em caso de não haver allteração no ECG, por medida preventiva, encaminhar para um\nserviço especializado.","B":"Realizar um eletrocardiograma (ECG) devido à dor intensa; administrar morfina como primeira\nescolha (em solução decimal); considerar\nadministrar oxigênio (se saturação de oxigênio \"menor ou\nigual\" 92%) e aspirina 500 mg, se a dor persistir após morfina. Em caso de alteração no ECG,\ntransferir para uma unidade de saúde com maior capacidade de atendimento.","C":"Realizar um eletrocardiograma (ECG), se possível, de 12 derivações; administrar nitroglicerina\nem spray ou sublingual, como primeira escolha,\ndevido ao quadro álgico intenso; considerar\nadministrar oxigênio (se saturação de oxigênio \"menor ou igual\" 85%) e morfina, se o desconforto\ntorácico não for aliviado pela nitroglicerina. Em caso de não haver alteração no ECG, por medida\npreventiva, encaminhar para um serviço especializado.","D":"Realizar um eletrocardiograma (ECG), se possível, de 6 derivações; administrar aspirina na dose\nde 160 a 325 mg mastigável; considerar\nadministrar oxigênio (se saturação de oxigênio \" menor ou\nigual\" 85%) e morfina, se o desconforto torácico não for aliviado pela nitroglicerina. Em caso de\nnão\nhaver alteração no ECG, por medida preventiva, encaminhar para um serviço especializado.","E":"Realizar um eletrocardiograma (ECG), se possível, de 12 derivações; administrar aspirina na\ndose de 160 a 325 mg mastigável; considerar\nadministrar oxigênio (se saturação de oxigênio \"\nmenor ou igual\" 90%), nitroglicerina sublingual ou spray e, se o desconforto torácico não for\naliviado\npela nitroglicerina, morfina. Em caso de alteração no ECG, transferir para uma unidade de saúde\ncom maior capacidade de atendimento."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183345","number":"183345","sourceNumber":"183345","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O núcleo da equipe é formado por Médicos, Enfermeiras e especialistas em exercícios,\ncom a opção de agregar especialistas em\noutras disciplinas para fornecer ao paciente atendimento\ne educação completa (Nutricionista, Psicólogo, entre outros), dessa forma, podemos considerar\ncomo completamente adequado o item:","options":{"A":"Um programa de reabilitação cardiovascular RCV não necessita de ser integrado por uma\nequipe multidisciplinar.","B":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências: conhecimento\nbásico na área cardiovascular apenas.","C":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências:\nconhecimento básico nas áreas cardiovascular, pulmonar e\nmusculoesquelética, interpretação do eletrocardiograma, manejo de emergências médicas e\nconhecimentos em teoria e prática do exercício físico.","D":"Um programa de reabilitação cardiovascular RCV é integrado por uma equipe multidisciplinar,\nque requer as seguintes competências:\nconhecimento básico nas áreas cardiovascular, pulmonar e\nmusculoesquelética, interpretação do eletrocardiograma é desnecessária, manejo de emergências\nmédicas e conhecimentos em teoria e prática do exercício físico."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183343","number":"183343","sourceNumber":"183343","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O cálculo do Índice de Massa Corporal (IMC) tem sido proposto pelo Instituto Nacional\nda Saúde dos Estados Unidos (NHLBI) e pela\nOrganização Mundial da Saúde (OMS) como o\nmétodo convencional para diagnosticar sobrepeso e obesidade. Sendo INCORRETO afirmar que:","options":{"A":"Embora o IMC seja um método simples para detectar sujeitos com aumento considerável de\ngordura corporal, particularmente em âmbito populacional, estudos recentes têm confirmado\ntotalmente a sua validade para diagnosticar obesidade individual.","B":"O obeso tem maior frequência e incidência de outros fatores de risco.","C":"O risco manifesta-se também de forma direta, uma vez que a gordura, particularmente a visceral\nintra-abdominal, é um órgão endócrino, metabolicamente ativo, que sintetiza e libera na circulação\nsanguínea diferentes peptídeos e outros compostos não peptídicos que participam da homeostase\ncardiovascular.","D":"O obeso perde em maior ou menor grau esse equilíbrio e assim o risco também aumenta."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183337","number":"183337","sourceNumber":"183337","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A presença de estenose significativa no Tronco de Coronária Esquerda - TCE tem\ngrande importância prognóstica e impacto na tomada\nde decisão. Em relação a isso, somente NÃO\npodemos concordar com a alternativa:","options":{"A":"Deve-se ter em mente ainda que doença no Tronco de Coronária Esquerda - TCE está\nraramente associada à doença em ramos\nsubsequentes, e a presença de estenoses significativas\nna artéria descendente anterior e/ou na artéria circunflexa pode sub ou superestimar o valor da RFF\nmedida na lesão no TCE.","B":"Presença de estenose significativa no Tronco de Coronária Esquerda - TCE tem grande\nimportância prognóstica, e a determinação do\nsignificado funcional de tais estenoses é fundamental\npara a decisão da estratégia terapêutica.","C":"Revascularização de lesões no Tronco de Coronária Esquerda - TCE não significativas, do ponto\nde vista funcional, pode levar à oclusão\nprecoce dos enxertos cirúrgicos, mesmo que condutos de\nartéria mamária interna esquerda sejam utilizados.","D":"Ademais, deve-se ter em mente que o TCE representa o local da árvore coronária em que a\navaliação angiográfica da gravidade da estenose é mais ambígua e variável."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157415","number":"157415","sourceNumber":"157415","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"São sinais de ruptura aórtica, com EXCEÇÃO de:","options":{"A":"Obliteração do cajado aórtico.","B":"Desvio de traqueia para a direita.","C":"Elevação do brônquio fonte esquerdo.","D":"Derrame extrapleural apical."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157348","number":"157348","sourceNumber":"157348","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente homem, 65 anos, tabagista, hipertenso em tratamento adequeado, procura\natendimento de urgência queixando-se de dor em região epigástrica iniciado há 30 minutos. Com\nbase nessas informações e no eletrocardiograma a seguir, assinale a alternativa com o diagnóstico\nprovável. (Conforme imagem do caderno de questões).","options":{"A":"Infarto Agudo em Parede Inferior.","B":"Infarto Agudo em Parede Lateral Alta.","C":"Infarto Agudo em Parede Anterior.","D":"Infarto Agudo Anterior Extenso.","E":"Infarto Agudo em Parede Anterosseptal."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-150265","number":"150265","sourceNumber":"150265","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Na semiologia do tórax, qual é o ponto anatômico que serve de referência para a\nidentificação e a contagem dos espaços intercostais, que é importante na ausculta cardíaca (focos\nde ausculta) e na realização de procedimentos invasivos, como toracocentese e drenagem\ntorácica?","options":{"A":"Ângulo esternal.","B":"Linha hemiclavicular.","C":"Linha paraesternal.","D":"Linha axilar."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-150722","number":"150722","sourceNumber":"150722","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente apresenta-se na emergência com diagnóstico de síndrome coronariana\naguda, com ECG normal, porém com elevação de\nmarcadores enzimáticos de necrose miocárdica.\nNessas condições, a conduta inicial, além das medidas gerais, deve ser:","options":{"A":"Terapia antiplaquetária dupla + terapia anticoagulante (enoxaparina).","B":"Terapia fibrinolítica.","C":"Angioplastia primária dentro das primeiras três horas do quadro.","D":"Terapia anticoagulante (enoxaparina), sem terapia antiplaquetária."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157410","number":"157410","sourceNumber":"157410","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino de 60 anos de idade foi internado no hospital com quadro de dor\ntorácica, estável pela manhã, mas com progressiva piora da dor torácica, que apesar de não\nocorrer positivação dos marcadores de lesão miocárdica, teve indicado cateterismo diagnóstico e\npossivelmente terapêutico por parte da cardiologia. Diversas condutas serão realizadas a fim de\nmelhorar os desfechos desse paciente, dentre eles o uso de medicações que interagem com\nplaquetas. A respeito dessa intervenção, assinale a alternativa considerada INADEQUADA:","options":{"A":"Na utilização de clopidogrel, é preciso ressaltar ainda que, dentre os pacientes submetidos à\ntrombólise, a dose de ataque de 300 mg não deve ser administrada em pacientes acima de 75\nanos.","B":"A dose dobrada de 150 mg/dia de clopidogrel deve ser restrita aos pacientes com baixo risco de\nsangramento.","C":"Em caso de intervenção cirúrgica, o clopidogrel deve ser suspenso 10 dias antes do\nprocedimento.","D":"Para uso de clopidogrel com dose de ataque de 600 mg em pacientes submetidos à ICPP, tem\nse baseado na inibição do receptor do ADP mais rápido que se obtém com essa dose."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-149245","number":"149245","sourceNumber":"149245","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino de 64 anos de idade, com intensa dor torácica, deu entrada no\nhospital com diagnóstico de infarto agudo do miocárdio. Dentre as condutas iniciais a serem\ntomadas para melhor prognóstico, podemos referenciar como ADEQUADO, quanto ao uso de\noxigênio, o seguinte:","options":{"A":"Indicado sempre que ocorrer desconforto respiratório, queda da saturação abaixo de 94% ou\ncongestão pulmonar.","B":"Seu uso, sem indicação precisa, sempre é considerado benéfico.","C":"Seu uso, quando desnecessário, pode provocar vasodilatação sistêmica.","D":"Seu uso, quando desnecessário, pode provocar queda do débito cardíaco."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-149247","number":"149247","sourceNumber":"149247","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente hipertenso mal controlado de 60 anos de idade procura o hospital com intensa\ndor torácica com característica descrita de\nser \"rasgada\", sendo bastante intensa. Existe diferença\nde pressão entre os membros superiores, sendo a maior de 210 x 120 mmHg. Como ECG estava\ninespecífico, foi realizada tomografia torácica que demonstrou Dissecção de Aorta. Para esse\ntratamento clínico, assinale a alternativa considerada como INADEQUADA.","options":{"A":"Idealmente, a pressão sistólica alvo de 120 mmHg deve ser alcançada em 20 minutos.","B":"Potencialmente, o uso isolado do nitroprussiato de sódio pode piorar a dissecção da aorta.","C":"O uso isolado de Nitroprussiato pode promover aumento da Frequência Cardíaca.","D":"Nitroprussiato não deve ser associado ao beta bloqueador."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-156520","number":"156520","sourceNumber":"156520","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Dentre os fatores de risco para doença cardiovascular podemos citar a deficiência de\ncomponentes do complemento.","B":"Segundo a organização mundial de saúde (OMS) as doenças cardiovasculares são as principais\ncausas de óbito no mundo. Somente no Brasil, mais de 300 mil pessoas morrem anualmente","C":"Dentre os Fatores modificáveis para doenças cardiovasculares podemos citar a predisposição\ngenética","D":"Dentre os fatores não modificáveis, para doenças cardiovasculares podemos citar corrigir os\nmaus hábitos de vida e alimentação"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157423","number":"157423","sourceNumber":"157423","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Podemos considerar a aterosclerose como uma doença inflamatória crônica de origem\nmultifatorial que ocorre em resposta à agressão endotelial, que acomete principalmente a camada\níntima de artérias de médio e grande calibres. A formação da placa aterosclerótica se relaciona com\no contido em uma das opções. Aponte-a.","options":{"A":"Agressão ao endotélio vascular devido a diversos fatores de risco, como dislipidemia,\nhipertensão arterial ou tabagismo.","B":"Pela disfunção endotelial diminui a permeabilidade da íntima às lipoproteínas plasmáticas,\nfavorecendo a retenção das mesmas no espaço subendotelial.","C":"As HDL sofrem oxidação, causando a exposição de diversos neo-epitopos e tornando-as\nimunogênicas.","D":"O depósito de lipoproteínas na parede arterial, processo-chave na parada da aterogênese."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157428","number":"157428","sourceNumber":"157428","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"De acordo com a importância epidemiológica das placas de aterosclerose e suas\nrelações com os eventos clínicos trombogênicos, assinale a alternativa CORRETA:","options":{"A":"Placas estáveis caracterizam-se por predomínio de colágeno, desorganizado em capa fibrosa\nespessa, muitas células inflamatórias e núcleo lipídico e necrótico de proporções menores.","B":"As placas instáveis apresentam atividade inflamatória reduzida, especialmente nas suas bordas\nlaterais, com grande atividade proteolítica, núcleo lipídico e necrótico proeminente e capa\nfibrótica\ntênue.","C":"A ruptura desta placa instável expõe material endotelial colágeno altamente trombogênico,\nlevando à formação de um trombo sobrejacente.","D":"O processo de aterotrombose é um dos principais determinantes das manifestações clínicas da\naterosclerose."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157435","number":"157435","sourceNumber":"157435","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Para se entender a epidemiologia da estratificação de risco cardiovascular para\nadequada prevenção de eventos relacionados com a arteriosclerose, aponte a alternativa\nINCORRETA:","options":{"A":"Um evento coronário agudo é a primeira manifestação da doença aterosclerótica em menos de\num décimo dos indivíduos que apresentam essa\ncomplicação.","B":"Ocorre necessidade de identificação dos indivíduos assintomáticos que estão mais predispostos\npara a prevenção efetiva com a\n\ncorreta definição das metas terapêuticas individuais.","C":"Diversos algoritmos têm sido criados com base em análises de regressão de estudos\npopulacionais, por meio dos quais a identificação\ndo risco global é aprimorada substancialmente.","D":"A estimativa do risco de doença aterosclerótica resulta da somatória do risco associado a cada\num dos fatores de risco mais a potenciação\ncausada por sinergismos entre alguns desses fatores.\n\nDiante da complexidade destas interações, a atribuição\n\nintuitiva do risco frequentemente resulta em subestimação ou superestimação dos casos de maior\nou menor risco."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-138183","number":"138183","sourceNumber":"138183","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual dos seguintes fatores da coagulação é ativado pelo contato com as superfícies e é\ncapaz de desencadear a via intrínseca da coagulação?","options":{"A":"Fator IX.","B":"Fator XII.","C":"Fator XIII.","D":"Fator tecidual."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-127669","number":"127669","sourceNumber":"127669","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 75 anos, tabagista, hipertenso, diabético e dislipidêmico, relata início, há\nseis horas, de dor precordial tipo queimação,\nde forte intensidade, associada a náuseas e vômitos,\npiora com exercício leve, sem fatores de melhora e com irradiação para membro superior esquerdo.\nAo exame, apresenta ritmo cardíaco regular, pressão arterial de 170 x 100 mmHg; SatO? de 92%\nem ar ambiente e com o seguinte ECG: (VER IMAGEM) Nesse caso, a primeira conduta\nterapêutica a ser feita é:","options":{"A":"Encaminhar para cateterismo cardíaco (cineangiocoronariografia).","B":"Prescrever estreptoquinase 1.500.000 UI EV em uma hora.","C":"Prescrever morfina 2 mg EV.","D":"Prescrever aspirina 300 mg VO."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-138219","number":"138219","sourceNumber":"138219","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A confirmação do Rh negativo faz-se pela:","options":{"A":"pesquisa de anticorpos irregulares (PAI).","B":"prova de compatibilidade.","C":"pesquisa do \"D\" fraco.","D":"técnica do Coombs direto."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109331","number":"109331","sourceNumber":"109331","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um dos mecanismos de ação da heparina de baixo peso molecular, que contribui para\nseu efeito anticoagulante, é a inibição do\nfator:","options":{"A":"IVa.","B":"Vlla.","C":"IXa.","D":"Xa."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109361","number":"109361","sourceNumber":"109361","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"J.S.S., de 22 anos, do sexo masculino, foi admitido no pronto-socorro após ferimento\npor arma branca em região abdominal.\nFamiliares negaram o uso de álcool ou drogas ilícitas. Ao\nexame físico, o paciente apresentava-se com sangramento ativo de grande monta e desorientado\nno tempo e espaço. Os sinais vitais eram: FC: 132 bpm; PA: 80 x 40 mmHg; FR: 35 irpm; peso: 82\nKg. J.S.S, foi adequadamente conduzido pelo médico emergencista e evoluiu com melhora clínica\ngradativa. No terceiro dia de internação hospitalar, apresentou recorrência do quadro de\nhipotensão, taquicardia e taquidispneia, dessa vez acompanhado de febre, leucocitose, sem\nsangramento ativo. Recebeu o diagnóstico de choque séptico e foram iniciadas adequadamente as\nmedidas terapêuticas. No segundo dia de antimicrobiano, o paciente apresentava-se sem melhora\nsignificativa e com sangramento importante ao redor do orifício de inserção do acesso venoso\ncentral, além de melena. Os exames laboratoriais eram: hemograma: Hb: 10,4 g/dl; Ht: 31%;\nleucócitos totais: 14.500/µl; plaquetas: 75.000/µl. Presença de moderada quantidade de\nesquizócitos em lâmina de sangue periférico; d-dímeros: 1000 ng/ml (VR: inferior a 500 ng/dl). TAP:\nRNI de 6,5; TTPA: relação P/N 3,5 (VR: 0,8-1,2). Fibrinogênio: 130 mg/dl (VR: 150: 150-370 mg/dl).\nNesse caso, qual é a conduta hematológica adequada?","options":{"A":"Plasmaférese terapêutica.","B":"Transfusão de 800 ml de plasma fresco congelado.","C":"Transfusão de 800 ml de plasma fresco congelado + 1 Ul de plaquetas por aférese.","D":"Transfusão de 800 ml de plasma fresco congelado + 1 UI de plaquetas por aférese + 8 UI de\ncrioprecipitado."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-110209","number":"110209","sourceNumber":"110209","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Foi admitido no pronto-socorro um paciente portador de fibrilação atrial em uso de\ndabigatrana 150 mg uma vez por dia com quadro de HDA. Nesse caso, qual a melhor opção para\ninterrupção do sangramento o mais breve possível?","options":{"A":"Vitamina K endovenosa.","B":"Plasma fresco congelado.","C":"Crioprecipitado.","D":"Complexo protombínico de 4 fatores e diálise."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-79536","number":"79536","sourceNumber":"79536","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma criança de 3 anos é levada ao posto de saúde por apresentar ?manchas? na pele\nhá 1 semana e epistaxe. Nega outros sintomas. Ao exame físico: criança em bom estado geral,\ncom petéquias na face, no tronco e nos membros e algumas equimoses; sem\nhepatoesplenomegalia. Contagem de plaquetas: 10.000/mm³. A principal hipótese diagnóstica é:","options":{"A":"Púrpura de Henoch-Schönlein","B":"Leucemia linfocítica aguda","C":"Púrpura trombocitopênica idiopática","D":"Meningococcemia","E":"dengue"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-79547","number":"79547","sourceNumber":"79547","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma criança de 3 anos, previamente hígida, é levada para uma consulta por ter\nocorrido, há 24 horas, o surgimento de\npetéquias e equimoses no tronco, abdome e membros\ninferiores; com passado de infecção das vias aéreas superiores há 14 dias. Exame físico normal,\nexceto pela presença de petéquias e equimoses. Hemograma realizado revelou Hb = 12 g/dl; Ht =\n36%; leucócitos = 8.300; segmentados = 48%; linfócitos = 50%; monócitos = 2% e plaquetas =\n\n5.000. A hipótese diagnóstica mais provável seria:","options":{"A":"Leucemia","B":"Púrpura de Henoch-Schönlein","C":"Púrpura trombocitopênica autoimune","D":"Riquetsiose"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-79561","number":"79561","sourceNumber":"79561","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um menino de 4 anos, descendente de italianos, é atendido no ambulatório por\nartralgias de repetição, epistaxe, petéquias\ne hematomas em membros inferiores e superiores.\nNega traumas recentes. Dor abdominal, náuseas e vômitos. Tem apresentado quadro gripal há 5\ndias. O seu hemograma revela hemoglobina = 9 g/dl, leucócitos = 6.700/mm³, contagem diferencial\nnormal e plaquetas = 39.000/mm³. O diagnóstico mais provável é:","options":{"A":"Hemofilia","B":"Púrpura de Henoch-Schönlein","C":"Doença de von Willebrand","D":"Talassemia","E":"Púrpura trombocitopênica imunológica"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-84401","number":"84401","sourceNumber":"84401","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Cite o item abaixo que não é causa de doença hereditária da função plaquetária.","options":{"A":"Síndrome antifosfolípide.","B":"Doença de von Willebrand.","C":"Síndrome de Goulier.","D":"Trombastenia de Glanzmann.","E":"Os itens A e C estão corretos."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-62766","number":"62766","sourceNumber":"62766","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Durante a anestesia, um risco de complicação por transfusão sanguínea é o paciente\nreceber sangue diferente do seu tipo, por erro humano. Qual é o paciente com maior risco de\nincompatibilidade com reação transfusional, caso receba sangue de um tipo diferente do seu?","options":{"A":"A.","B":"B.","C":"O.","D":"AB."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-63420","number":"63420","sourceNumber":"63420","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A vitamina K, em sua forma reduzida vitamina KH2, é um cofator essencial para a\nativação de proteínas da coagulação, os\nchamados fatores da coagulação vitamina K-dependentes.\nSão fatores vitamina K-dependentes, exceto:","options":{"A":"Fator IX.","B":"Protrombina.","C":"Fator X.","D":"Fator XII.","E":"Fator VII."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-63412","number":"63412","sourceNumber":"63412","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quais destas condições clínicas que interferem sobre os efeitos da warfarina está\nincorreta?","options":{"A":"Dietas ricas em vitamina K reduzem a resposta à warfarina (ex.: dietas para redução de peso\nricas em vegetais, suplementos alimentares ricos em vitamina K, dietas parenterais com vitamina\nK);","B":"Dietas pobres em vitamina K potencializam a resposta à warfarina (ex.: dietas enterais ou\nparenterais sem vitamina K).","C":"Estados hipermetabólicos como febre e hipertiroidismo, diminuem o catabolismo dos fatores da\ncoagulação vitamina K-dependentes.","D":"A Insuficiência hepática diminui a síntese dos fatores da coagulação.","E":"Síndromes de má-absorção de gorduras reduz a absorção da vitamina K."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-61847","number":"61847","sourceNumber":"61847","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma paciente de 22 anos, sexo feminino, procura atendimento médico devido ao\nquadro de púrpura em membros inferiores,\nsem outro dado clínico relevante. Realizado somente\nhemograma prévio, que evidenciou plaquetopenia isolada de 12.000 mm³. Considerando a hipótese\nde Púrpura Trombocitopênica Imunológica (plaquetopenia autoimune), pode-se afirmar que:","options":{"A":"A principal forma observada no adulto é a aguda, com predominância em mulheres, sendo\ncomum um quadro de infecção viral precedendo o\nquadro clínico.","B":"Os pacientes apresentam o tempo de sangramento geralmente maior do que o esperado para o\ngrau de plaquetopenia, as plaquetas circulantes são maiores e mais jovens que o normal.","C":"O diagnóstico é de exclusão, sendo importantes os exames: análise do esfregaço de sangue\nperiférico, FAN, mielograma, anticorpos antiplaqueta, sorologias para HIV e hepatites (B e C).","D":"A principal indicação de transfusão de plaquetas é a presença de sangramento com risco de\nmorte e a transfusão profilática tem benefício ainda questionável.","E":"O tratamento em situações emergenciais deve ser realizado com imunoglobulina endovenosa ou\npulsoterapia com metilprednisolona, observando-se uma resposta mais rápida com o corticoide."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-51070","number":"51070","sourceNumber":"51070","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual das condições abaixo resulta em prolongamento do tempo de tromboplastina\nparcial, mas não do tempo de protrombina?","options":{"A":"Hemorragia varicosa decorrente de cirrose.","B":"Menorragia resultante de doença de von Willebrand.","C":"Terapia com antibióticos de amplo espectro.","D":"Terapia com cumarina para flebite.","E":"Doença celíaca."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-51016","number":"51016","sourceNumber":"51016","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A trombocitopenia causada por aumento da destruição de plaquetas está mais\nrelacionada com qual das seguintes condições?","options":{"A":"Anemia aplásica.","B":"Poliquimioterapia.","C":"Leucemia aguda.","D":"Lúpus eritematoso sistêmico.","E":"Consumo excessivo de álcool etílico."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-47686","number":"47686","sourceNumber":"47686","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A determinação dos autoanticorpos nas doenças reumáticas é útil na classificação\nclínica, na caracterização de alvos antigênicos e\nno monitoramento terapêutico. A pesquisa no\nplasma do anticoagulante lúpico mostra uma associação importante com a:","options":{"A":"Síndrome do anticorpo antifosfolípide.","B":"Artrite reumatoide.","C":"Doença de Behçet.","D":"Síndrome de Sjögren."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-35839","number":"35839","sourceNumber":"35839","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual das doenças relacionadas é caracterizada como causadora de trombofilia\nsecundária?","options":{"A":"Síndrome antifosfolípide.","B":"Deficiência de proteína C e S.","C":"Deficiência de antitrombina III.","D":"Resistência à proteína C ativada causada pela presença de molécula anormal do fator V Leiden.","E":"Nenhuma das anteriores."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-35857","number":"35857","sourceNumber":"35857","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Indicação de plasma fresco:","options":{"A":"Reversão urgente do efeito cumarínico.","B":"Reversão urgente do efeito da heparina.","C":"Reposição de perda volêmica superior a 20%.","D":"Suporte nutricional em pacientes hipoalbuminêmicos.","E":"Expansão volêmica."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-22967","number":"22967","sourceNumber":"22967","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Leia o caso clínico a seguir. Uma paciente do sexo feminino, com 35 anos, fumante,\ndiabética insulinodependente, G2P1A0, procura\natendimento médico devido a quadro clínico de dor\ne edema de +++/+4 no membro inferior direito, iniciados há +/- 6 horas. Refere que a dor piora com\ndeambulação para curtas distâncias. A panturrilha encontra-se empastada, os pulsos distais\ndiminuídos (++/+4) e o edema é elástico, pouco doloroso à palpação e acomete todo o membro,\ndesde a raiz da coxa. Considerando os dados apresentados, qual a principal hipótese diagnóstica?","options":{"A":"Oclusão arterial aguda.","B":"Tromboflebite superficial.","C":"Trombose venosa profunda.","D":"Rotura muscular aguda."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-26972","number":"26972","sourceNumber":"26972","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual a droga de escolha para tratamento das tromboses venosas profundas?","options":{"A":"Penicilina","B":"Heparina","C":"Aspirina","D":"Anti-inflamatórios não hormonais","E":"Anti-inflamatórios hormonais"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-10679","number":"10679","sourceNumber":"10679","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual a droga de escolha para tratamento das tromboses venosas profundas?","options":{"A":"Penicilina.","B":"Heparina.","C":"Aspirina.","D":"Anti-inflamatórios não-hormonais.","E":"Anti-inflamatórios hormonais."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-216365","number":"216365","sourceNumber":"216365","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Ao avaliar um paciente com dor torácica aguda, escores de risco como o TIMI ou o\nGRACE se prestam a definir:","options":{"A":"Necessidade de realizar eletrocardiograma na sala de emergência.","B":"Candidatos à estratificação invasiva precoce num contexto de provável síndrome coronariana\nsem supra ST.","C":"Revascularização cirúrgica versus percutânea em pacientes com IAM com supra de ST.","D":"O tipo de dor torácica em: definitivamente anginosa, definitivamente não-anginosa,\nprovavelmente anginosa ou provavelmente não-anginosa."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131911","number":"131911","sourceNumber":"131911","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Adulto jovem procura ambulatório de clínica médica, encaminhado por médica do\ntrabalho. Informa que teve \"alteração\" em\nexames periódicos. Refere estar assintomático e mostra\num hemograma com 18.000 plaquetas, sem outros achados. A hematoscopia do sangue periférico\né normal, assim como as bilirrubinas, albumina, coagulograma, vitamina B12, ácido fólico,\ntransaminases e hormônios tireoidianos. Anti-HIV, FAN, eletroforese de proteínas normais. À\nanamnese dirigida, nega febre ou qualquer evidência de sangramentos. Não tem histórico\npatológico pregresso relevante, nem faz uso regular de qualquer medicação. Exame físico não\nmostra petéquias. A melhor conduta neste momento é:","options":{"A":"Internar, transfundir 1 concentrado de plaquetas para cada 10 kg de peso e monitorar eventuais\nsinais de sangramento.","B":"Encaminhar para hematologista, visando à realização de aspirado de medula óssea.","C":"Solicitar novo hemograma, com retorno em 30 dias, por enquanto não iniciar tratamento.","D":"Iniciar prednisona 1 mg/kg/24h e manter seguimento ambulatorial.","E":"Internar paciente para esplenectomia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131930","number":"131930","sourceNumber":"131930","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre a coagulação intravascular disseminada (CIVD), é correto afirmar, EXCETO:","options":{"A":"São causas comuns: sepse, neoplasia, trauma, queimadura, acidente ofídico.","B":"A síndrome HELLP é uma forma de CIVD.","C":"Ocorre prologamento do TAP e do TTPA.","D":"Ocorre plaquetopenia, queda de fibrinogênio e aumento de D-dímero.","E":"CIVD relacionada a neoplasias manifesta-se tipicamente por sangramento difuso (síndrome de\nTrousseau)."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-131923","number":"131923","sourceNumber":"131923","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Correlacione o agente tóxico e seu respectivo antídoto.","options":{"A":"Acetaminofeno - Piridoxina.","B":"Opióides - Octreotide.","C":"Varfarina - vitamina K.","D":"Organofosforado - Azul de Metileno.","E":"Metemoglobinizantes - Dexferroxamin."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-105725","number":"105725","sourceNumber":"105725","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Vítima de trauma abdominal, com rotura esplênica há 45 dias, comparece a ambulatório\nde clínica médica para seguimento de quadro de\nsíndrome metabólica. A presença de corpúsculos\nde Howell-Jolly, no hemograma trazido pela paciente, permite afirmar que:","options":{"A":"O paciente tem baço acessório ou não foi esplenectomizado.","B":"Trata-se de deficiência de G6PD em paciente esplenectomizado.","C":"O paciente tem deficiência de G6PD.","D":"Houve esplenectomia, e não há baço acessório.","E":"Certamente não houve esplenectomia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-80806","number":"80806","sourceNumber":"80806","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma menina de 4 anos apresenta história de, há 2 semanas, ter tido quadro de diarreia\ncom muco e sangue que durou 5 dias. Há 1 semana vem apresentando fadiga e edema\nperiorbitário bilateral. Qual das alternativas abaixo apresenta os resultados de exames que mais\nprovavelmente estarão associados ao quadro dessa paciente?","options":{"A":"Elevados tempos de protrombina e tromboplastina parcial ativada.","B":"Hipoalbuminemia.","C":"Anemia e plaquetopenia.","D":"Complemento abaixo.","E":"Anticorpo antinúcleo positivo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-84929","number":"84929","sourceNumber":"84929","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Hemofilia A é a deficiência de qual fator de coagulação?","options":{"A":"Fator VIII.","B":"Fator V.","C":"Fator II.","D":"Fator IX.","E":"Fator X."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-47468","number":"47468","sourceNumber":"47468","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O tratamento para PTI (Púrpura Trombocitopênica Idiopática) crônica na criança é:","options":{"A":"Gamaglobulina intravenosa (IVIG)","B":"Corticosteroides","C":"Concentrado de plaquetas","D":"Esplenectomia","E":"Transplante de medula"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-311491","number":"311491","sourceNumber":"311491","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 54 anos, diabético, admitido com dor retroesternal intensa irradiada para\nmandíbula e MSE há 50 minutos. ECG de entrada com ST supra de 5mm de V1 a V6, D1 e AVL.\nQual diagnóstico provável e melhor conduta?","options":{"A":"IAM de parede lateral. Administrar AAS 300mg, clopidogrel 300mg, heparinização plena e\ncateterismo cardíaco.","B":"Espasmo coronário difuso grave. Iniciar nitroglicerina IV e seriar enzimas cardíacas.","C":"IAM de parede anterior extenso. Administrar AAS 300mg, ticagrelor 180mg e encaminhar para\nangioplastia primária em caráter emergencial.","D":"Dissecção aguda de aorta. Solicitar angiotomografia de aorta torácica de urgência.","E":"TEP com repercussão eletrocardiográfica. Heparinização plena e providenciar angiotomografia\nde artérias pulmonares."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-302039","number":"302039","sourceNumber":"302039","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quando o profissional de saúde orienta mudanças no estilo de vida é fundamental\nidentificar qual o estágio motivacional que o\nusuário se encontra para poder elaborar a melhor\nestratégia. Prochaska, DiClemente e Norcross (1992) desenvolveram um Modelo de Avaliação do\nGrau de Motivação para a Mudança, descrevendo etapas que podem ser identificadas no discurso\nda pessoa quando indagada acerca de sua vontade de mudança de hábito e de seus planos para\nmudança. Assinale a alternativa que relaciona a fala do paciente e o estágio motivacional quando\nse aborda a cessação do tabagismo.","options":{"A":"Preparação: \"\"Eu tenho tentado parar de fumar de um tempo para cá\"\"","B":"Ação: \"\"Eu não quero parar de fumar\"\".","C":"Pré-contemplação: \"\"Eu voltei a fumar regularmente\"\".","D":"Contemplação: \"\"Eu parei de fumar\"\".","E":"Recaída: \"\"Eu tenho feito uso descontínuo do cigarro de um mês para cá\"\"."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-250391","number":"250391","sourceNumber":"250391","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 68 anos, internado com quadro de angina instável. Qual, dentre as alternativas\nabaixo, NÃO constitui estratificador de alto\nrisco nesta condição clínica?","options":{"A":"Angina noturna.","B":"Dor em repouso prolongada (> 20 minutos) e contínua.","C":"Angina com hipotensão.","D":"Angina associada a sopro sistólico de regurgitação em foco mitral.","E":"Angina em repouso com alterações dinâmicas de ST (igual ou maior do que 1mm)."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-250392","number":"250392","sourceNumber":"250392","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual é o exame com maior acurácia diagnóstica para avaliar o paciente com dissecção\naórtica aguda?","options":{"A":"Angiotomografia computadorizada","B":"Cintilografia com tecnécio","C":"Radiografia de tórax","D":"Ecocardiograma transtorácico.","E":"Ecocardiograma transesófágico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-218043","number":"218043","sourceNumber":"218043","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente admitido na unidade coronariana com quadro compatível com IAM anterior\ncom menos de 8 horas de duração. Como não\nexistia hemodinâmica disponível, foi submetido a\ntrombólise com estreptoquinase. Após 30 minutos da infusão inicia arritmia no monitor. Feito um\nECG com o traçado mostrado abaixo. Pergunta-se sobre este paciente: Qual o ritmo registrado no\nECG?","options":{"A":"Fibrilação atrial.","B":"Fibrilação ventricular.","C":"Taquicardia supraventricular com aberrância.","D":"Ritmo idioventricular acelerado.","E":"Ritmo sinusal."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-203195","number":"203195","sourceNumber":"203195","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher, 69 anos, é submetida a cateterismo cardíaco para avaliação de uma angina\nestável que não obteve resposta ao tratamento\nclínico. A complicação mais comum do cateterismo\ncardíaco e da angiografia coronariana é:","options":{"A":"Insuficiência renal aguda.","B":"Taquiarritmias.","C":"Bradiarritmia.","D":"Infarto do miocárdio.","E":"Sangramento do local de acesso vascular."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177516","number":"177516","sourceNumber":"177516","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Ao realizar a ausculta cardíaca de um paciente, você ausculta o componente pulmonar\nda segunda bulha (P2) mais intenso que o\ncomponente aórtico (A2). Assinale em qual patologia\nabaixo é esperado esse achado semiótico.","options":{"A":"Estenose aórtica","B":"Hipertensão maligna","C":"Tromboembolismo pulmonar","D":"Miocardite aguda","E":"Hipotireoidismo"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-154409","number":"154409","sourceNumber":"154409","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 35 anos, tabagista, hipertenso, refere dor na região anterior do tórax, que piora\ncom decúbito, de início há 8 horas. À admissão, apresentava PA = 160 x 100 mmHg, FC = 120\nbpm, FR = 32 mrpm, Temperatura = 38,0°C. Eletrocardiograma evidenciava elevação difusa de\nsegmento ST com concavidade para cima. Qual das hipótese diagnóstica mais provável?","options":{"A":"Cardiomiopatia hipertrófica.","B":"Dissecção aórtica.","C":"Síndrome coronariana aguda.","D":"Taquiarritmia supraventricular por reentrada.","E":"Pericardite aguda."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-103951","number":"103951","sourceNumber":"103951","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, com 65 anos, foi internado nesta unidade hospitalar com\nquadro de apendicite aguda e será submetido\na procedimento cirúrgico laparoscópico, dentro das 6\nhoras após o diagnóstico clínico e de imagem do quadro. O paciente citado é usuário de AAS de\nlonga data por doença coronária. Marque afirmativa correta:","options":{"A":"Sangue e plaquetas vão dar segurança ao procedimento.","B":"O procedimento deverá ser adiado.","C":"Entrar com antibiótico para esfriar o processo e esperar.","D":"Pós-operatório imediato na unidade de terapia intensiva não será necessário.","E":"A raquianestesia e a cirurgia aberta deverão ser indicadas."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-89562","number":"89562","sourceNumber":"89562","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente em uso de dicumarínicos, quais exames devem ser usados para controle de\ncoagulação?","options":{"A":"TPTA + INR.","B":"PTT + INR.","C":"TAP + INR.","D":"TPTA + INR.","E":"TC + TPTA."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-52527","number":"52527","sourceNumber":"52527","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"São indicações habituais de mielograma, exceto:","options":{"A":"Citopenia não explicada: anemia, leucopenia, trombocitopenia, ou combinação destas.","B":"Suspeita de infiltração medular: carcinoma, linfoma e leucemias.","C":"Suspeita de infecções: leishmaniose.","D":"Investigação de síndrome mielodisplásica.","E":"Pacientes com menos de 60 anos, com clínica e laboratório de púrpura trombocitopência\nidiopática."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308317","number":"308317","sourceNumber":"308317","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre a Pericardite Aguda, assinale a afirmativa correta.","options":{"A":"A radiografia de tórax é geralmente alterada, pois pequenos volumes de líquido no pericárdio 30\na 50 mL alteram a silhueta cardíaca.","B":"A grande maioria dos pacientes com pericardite aguda não apresenta dor torácica.","C":"A pericardite aguda pode se manifestar com uma variedade de sinais e sintomas inespecíficos,\ndependendo da etiologia subjacente. No ECG, pode-se observar novo supradesnivelamento do\nsegmento ST generalizado e depressão do PR.","D":"O derrame pericárdico hemorrágico normalmente tem como causa a infecção viral."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308319","number":"308319","sourceNumber":"308319","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente masculino, 52 anos, com história médica pregressa de hipertensão arterial\nsistêmica e síndrome de Marfan, chega à\nemergência com queixa de dor torácica retroesternal em\naperto, com irradiação para o dorso. Nega tabagismo, dislipidemia ou diabetes. Ao exame, paciente\nse apresenta inquieto pela dor constante, sem alívio após uso de nitrato 5 mg sublingual. PA = 200\nx 110 mmHg na chegada e 220 x 110 mmHg 3 minutos após uso de nitrato. Saturação de O? = 96\n\n% em ar ambiente, ausculta cardíaca: ritmo regular, sopro sistólico +++/6 em foco mitral e sopro\ndiastólico ++++/6 foco aórtico. Ausculta\npulmonar sem alterações. Realizou ECG: ritmo sinusal,\nsinais de sobrecarga ventricular, associado a infradesnível do segmento ST em derivações V1 e V2\ne supradesnível em derivações DII, DIII e avF. Após 20 minutos na emergência, paciente evolui\ncom hipotensão e sinais clínicos de choque. A melhor explicação fisiopatológica para o caso é\ninfarto agudo do miocárdio em parede.","options":{"A":"Inferodorsal, causado por dissecção da aorta e insuficiência aórtica aguda e comprometimento\ndo óstio do seio coronário direito, hipotensão\ne choque justificados por provável envolvimento do\nventrículo direito.","B":"Anterosseptal, causando ruptura de cordoalhas do folheto mitral, com consequente choque\nassociado à piora com o uso de nitrato sublingual.","C":"Inferior, causado pela crise hipertensiva e pela síndrome de Marfan. Posterior hipotensão,\njustificada pelo uso de nitrato sublingual.","D":"Inferodorsal, causado por dissecção da aorta e insuficiência aórtica aguda e seu\ncomprometimento da válvula mitral, causando\ninsuficiência mitral aguda e posterior choque devido\na edema agudo de pulmão cardiogênico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-316004","number":"316004","sourceNumber":"316004","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 54 anos chega ao pronto atendimento referindo desconforto torácico\ndescrito como sensação de peso e a localiza\ncolocando a mão no esterno, com irradiação para o\nombro esquerdo. O desconforto foi desencadeado após esforço físico habitual. Nega sintomatologia\nsemelhante. A dor aliviou 20 minutos após chegada ao hospital. Tem diagnóstico, há 3 anos, de\ndislipidemia, e está em uso de sinvastatina 20mg/d. Nesse caso, qual é hipótese diagnóstica?","options":{"A":"Embolia de pulmão","B":"Esofagite","C":"Síndrome coronariana aguda","D":"Pneumotórax","E":"Dissecção de aorta"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308320","number":"308320","sourceNumber":"308320","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Durante fase inicial de uma cirurgia de revascularização miocárdica, antes da abertura\nesternal, o anestesiologista observa, no\nmonitor cardíaco, que no traçado da curva do pulso venoso\njugular, apenas a onda a (presente anteriormente) não é mais observada. Ao olhar o traçado\neletrocardiográfico no monitor cardíaco, mais provavelmente aparecerá:","options":{"A":"Bloqueio atrioventricular de 3º grau.","B":"Bloqueio atrioventricular de 2º grau tipo II (2:1).","C":"Bradicardia sinusal.","D":"Fibrilação atrial."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308321","number":"308321","sourceNumber":"308321","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente em recuperação, na UTI, na 1ª hora após revascularização miocárdica, em\nventilação mecânica, com marcapasso temporário. Seu médico cardiologista resolve testar o grau\nde dependência do marca-passo epimiocárdico, que está em 70 bpm e com captura ventricular\nadequada. Ao ser desligado o gerador do marca-passo, o médico verifica, no monitor que o gráfico\ndo pulso venoso jugular passa a demonstrar uma onda a \"em canhão\". Ao olhar para o monitor\ncardíaco, ele observa que o traçado eletrocardiográfico passou a demonstrar a presença de","options":{"A":"Bradicardia sinusal","B":"Flutter atrial","C":"Bloqueio atrioventricular total.","D":"Bloqueio 1 grau."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-308386","number":"308386","sourceNumber":"308386","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente M. C. S. de 35 anos vem para consulta médica com queixa de ganho de 15 kg\nnos últimos 24 meses, após sua última\ngestação. Refere que tem preferência por doces, não faz\nlanches, passa o dia trabalhando e come mais à noite, quando chega em casa. É sedentária, nega\ntabagismo, nega diagnósticos prévios e não faz uso de qualquer medicação. Teve 3 gestações e 3\npartos vaginais, sem intercorrências. Sua mãe é diabética e seu pai morreu aos 57 anos de infarto\nagudo do miocárdio. Ao exame: peso 89 kg, estatura 155 cm, PA 140 x 85 mmHg, cintura 97 cm.\n\nTraz os seguintes exames: glicemia 104 mg/dL; colesterol total 225 mg/dL; triglicerídeos 188 mg/dL;\nHDL 33mg/dL. Marque a afirmativa correta.","options":{"A":"A paciente apresenta obesidade grau III, pois seu IMC é de 37.","B":"A paciente apresenta diagnóstico de Diabetes Mellitus tipo 2, por apresentar obesidade central\nassociada a alterações na glicemia de jejum.","C":"A paciente deve ser incentivada a iniciar programa de Modificação de Estilo de Vida\nimediatamente, instituindo atividade física regular,\nalimentação saudável e manutenção do peso\nideal.","D":"O diagnóstico de Síndrome Metabólica ainda não pode ser firmado devido à falta de alguns\nexames diagnósticos na história clínica."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-313414","number":"313414","sourceNumber":"313414","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher, 67 anos, hipertensa e diabética de longa data, chega à unidade com quadro de\ndor torácica típica após realização de esforço físico. Realizado eletrocardiograma abaixo: Qual o\ndiagnóstico mais provável?","options":{"A":"Infarto agudo do miocárdio de parede lateral;","B":"Infarto agudo do miocárdio de parede inferior;","C":"Síndrome coronariana aguda sem supra de ST;","D":"Infarto agudo do miocárdio com bloqueio de ramo esquerdo."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-274111","number":"274111","sourceNumber":"274111","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 41 anos de idade internou no HUJM por dor precordial e dispneia aos\nmoderados esforços. História prévia de\nhipertensão arterial, dislipidemia mista, tabagismo e lúpus\neritematoso sistêmico, desde os 21 anos. Nos últimos meses, queixou-se de quadro de dor\nprecordial do tipo pleurítica, que piorava no decúbito e melhorava com posição sentada.\n\nAntecedente de anemia e convulsões, atribuídas ao lúpus há 2 anos. Ao exame físico, paciente em\nrazoável estado geral, hidratada, eupneica, FC 115 bpm, PA 110 x 70 mmHg. Ausculta pulmonar\nnormal e ausculta cardíaca revelou bulhas rítmicas, hipofonese do componente aórtico da segunda\nbulha e sopro sistólico ++++/6+. O exame do abdome foi normal, não havendo edema e os pulsos,\nsimétricos. O ECG revelou ritmo sinusal, frequência cardíaca de 109 bpm, com ondas T apiculadas\ne elevação do segmento ST. Assinale a alternativa que apresenta os dados semiológicos\nidentificados compatíveis com a fisiopatologia/histologia.","options":{"A":"Miocardite necrotizante eosinofílica ? alterações degenerativas da fibra com hipertrofia e\nfibrose\ninstersticial; sopro sistólico grave ++++/6+.","B":"Pericardite constritiva ? espessamento fibroso acentuado e aderências dos folhetos visceral e\nparietal e calcificação extensa ou em placas; ondas T apiculadas e elevação do segmento ST.","C":"Doença arterial coronariana ? ? de IL-6 associado ao ? de cálcio coronário e TNF-? e IL-17\naumentam a resistência à insulina; PA normal associado à taquicardia com ritmo sinusal.","D":"Insuficiência mitral ? espessamento dos folhetos valvares, áreas de calcificação, fusão\ncomissural e encurtamento de cordoalhas;\nhipofonese do componente aórtico da segunda bulha."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-288136","number":"288136","sourceNumber":"288136","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Todo paciente com dor torácica, atendido num pronto atendimento, deve ser\ninvestigado quanto à presença de doença\nisquêmica coronariana. No ECG, quando surge o\nsupradesnivelamento do segmento ST de pelo menos 2 mm em duas derivações precordiais\nadjacentes, o paciente deve ser considerado candidato ao tratamento de reperfusão. Em relação ao\ninfarto agudo do miocárdio (IAM), assinale a afirmativa CORRETA.","options":{"A":"A creatinofosfoquinase (CK) eleva-se durante o período de 4 a 8 h e geralmente retorna ao\nnormal em 48 a 72 horas.","B":"A troponina T não é um bom biomarcador cardíaco num IAM.","C":"A morfina não é um analgésico eficaz no tratamento da dor em um paciente com IAM e ainda\npode aumentar a constrição arteriolar.","D":"A fibrinólise deve ser iniciada mesmo se houver contraindicações, como sangramento ativo."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-283991","number":"283991","sourceNumber":"283991","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher, 67 anos, hipertensa e diabética de longa data, chega à unidade com quadro de\ndor torácica típica após realização de esforço físico. Realizado eletrocardiograma abaixo: Qual o\ndiagnóstico mais provável?","options":{"A":"Infarto agudo do miocárdio de parede lateral.","B":"Infarto agudo do miocárdio de parede inferior.","C":"Síndrome coronariana aguda sem supra de ST.","D":"Infarto agudo do miocárdio com bloqueio de ramo esquerdo."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-244785","number":"244785","sourceNumber":"244785","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma mulher jovem apresenta quadro de febre recorrente por acometimento das vias\naéreas superiores, acompanhada de dor torácica, que varia com a respiração e a posição do tórax,\nvariando, também, de intensidade e duração. Seu exame físico revela a presença de um atrito\npericárdico. Das situações a seguir, qual não indica a necessidade de internação hospitalar?","options":{"A":"Elevação de enzimas de necrose miocárdica","B":"Febre acima de 38°C e leucocitose","C":"Derrames pericárdicos volumosos, com ou sem tamponamento cardíaco","D":"Acometimento em imunocomprometidos","E":"Presença de bloqueio do ramo esquerdo no eletrocardiograma"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-221391","number":"221391","sourceNumber":"221391","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A eficácia do AAS durante as primeiras 24 horas do IAMCSST foi demonstrada\ninicialmente. A dose apresenta a seguinte alternativa como CORRETA:","options":{"A":"No entanto, a utilização de doses altas de AAS não associada a aumento significante das taxas\nde sangramento menor.","B":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), foi evidenciada diferença significante entre os dois grupos no desfecho primário de morte\ncardiovascular, IAM ou AVC até 30 dias de acompanhamento.","C":"No entanto, a utilização de doses altas de AAS esteve associada a aumento insignificante das\ntaxas de sangramento menor.","D":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), não foi evidenciada diferença significante entre os dois grupos no desfecho primário de morte\ncardiovascular, IAM ou AVC até 30 dias de acompanhamento."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-221398","number":"221398","sourceNumber":"221398","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A eficácia e segurança da terapia antiplaquetária dupla TAD pós-intervenção coronária\npercutânea ICP em pacientes com alto risco de sangramento tem sido avaliada em estudos\nrecentes. Podemos apenas concordar com o item:","options":{"A":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes não representa um\ndesafio na prática clínica devido ao elevado risco de\ncomplicações hemorrágicas associada à terapia tripla.","B":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nsem uso de anticoagulantes ainda representa\num desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas associada à terapia tripla.","C":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda representa um desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas associada à terapia tripla.","D":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda representa um desafio na prática clínica devido ao elevado risco\nde complicações hemorrágicas não associadas à terapia tripla."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-221389","number":"221389","sourceNumber":"221389","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Ticagrelor é um novo fármaco antagonista reversível do receptor não tienopiridínico\nP2Y12, sendo adequado o seguinte ao seu respeito:","options":{"A":"Necessita de processo de conversão metabólica para um componente ativo.","B":"Não necessita de processo de conversão metabólica para um componente inativo.","C":"Não necessita de processo de conversão metabólica para um componente ativo.","D":"Não necessita de processo de desconversão metabólica para um componente ativo."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-214586","number":"214586","sourceNumber":"214586","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 55 anos, hipertenso e tabagista, deu entrada no PA com queixa de\ndesconforto epigástrico há uma hora. Ao exame\nfísico, apresenta-se com PA = 80 x 50 mmHg; FC\n\n= 60 bpm; pálido e sudoreico, com pulsos filiformes, pulmões sem estertores, ausência de B3 ou\nsopros cardíacos. ECG mostra\nsupradesnivelamento do segmento ST de 3 mm nas derivações D2,\nD3 e aVF. Qual é o diagnóstico e a conduta mais adequada?","options":{"A":"Infarto inferior com repercussão hemodinâmica; iniciar infusão de dobutamina + noradrenalina e\navaliar V3R e V4R.","B":"Infarto de ventrículo direito; iniciar infusão de volume com cristaloide e dobutamina.","C":"Infarto de ventrículo direito; iniciar infusão de volume com cristaloide e noradrenalina.","D":"Infarto inferior com hipotensão arterial importante; iniciar infusão de volume com cristaloides e\navaliar V3R e V4R."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-208559","number":"208559","sourceNumber":"208559","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 50 anos foi admitido em unidade de pronto atendimento com relato de\ndor torácica súbita, de leve intensidade, em\naperto, iniciado a 15 minutos de sua admissão. Após\nrápida coleta de enzimas de injuria miocárdica, seu eletrocardiograma revelou corrente de lesão\nsubepicárdica nas derivações D2, D3 e aVF. Ao exame físico, apresentava PA=160x80 mmHg e\nFC=100bpm. Em se tratando de infarto agudo do miocárdio, qual dos critérios a seguir determina a\nreperfusão coronariana imediata?","options":{"A":"característica da dor torácica","B":"achado eletrocardiográfico","C":"nível de pressão arterial","D":"frequência cardíaca","E":"valores das enzimas cardíacas"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-208589","number":"208589","sourceNumber":"208589","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual é o maior compartimento líquido do corpo?","options":{"A":"plasma","B":"fluido espinal central","C":"fluido intersticial","D":"fluido intracelular","E":"nenhuma das anteriores"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181597","number":"181597","sourceNumber":"181597","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à semiologia cardíaca nas valvopatias, assinale a afirmativa CORRETA.","options":{"A":"Na insuficiência tricúspide, pode-se observar exacerbação do sopro com a manobra de Rivero\nCarvalho, presença de onda V gigante no pulso jugular e pulso hepático.","B":"O sopro de Austin Flint se caracteriza por ser diastólico, é classicamente encontrado na\ninsuficiência aórtica grave quando associada à estenose mitral moderada/importante.","C":"O sopro de Carey Coombs, diastólico por hiperfluxo, melhor audível em foco mitral, é o sopro\nclássico da estenose mitral grave causada por febre reumática.","D":"O sopro de Gallavardin da estenose aórtica ocorre por irradiação do sopro diastólico para o\nápice do\n\ncoração em uma valva aórtica calcificada, confundindo com o sopro da estenose mitral."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177321","number":"177321","sourceNumber":"177321","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 69 anos apresenta quadro de angina instável e deve ser submetido a\ncateterismo cardíaco. Ele está internado em unidade coronariana, com pressão arterial controlada e\nFC = 66 bpm. A creatinina é de 1,2 mg%. A complicação mais esperada para essa angiografia é:","options":{"A":"lesão renal aguda intrínseca","B":"infarto agudo do miocárdio","C":"taquiarritmia pós-procedimento","D":"sangramento do local de punção","E":"obstrução arterial aguda em femoral"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-167800","number":"167800","sourceNumber":"167800","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"NÃO faz parte das manifestações clínicas da hipertrofia concêntrica do ventrículo\nesquerdo:","options":{"A":"Insuficiência cardíaca restritiva.","B":"Insuficiência cardíaca de alto débito.","C":"Presença de quarta bulha na ausculta.","D":"RX de tórax nos limites da normalidade."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-158189","number":"158189","sourceNumber":"158189","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente diabético foi submetido à angioplastia primária e implante de stent na artéria\ndescendente anterior por IAM. Apresentou evolução satisfatória e a coronariografia não mostrou\nlesões significativas nas demais coronárias. Após 5 dias, recebeu alta hospitalar. NÃO é droga\nutilizada na prevenção secundária desse paciente:","options":{"A":"Nitrato.","B":"Estatina.","C":"Clopidogrel.","D":"IECA."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109216","number":"109216","sourceNumber":"109216","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A proteína responsável pela ligação &#34;plaqueta-plaqueta&#34;, através de pontes\ncom fibrinogênio ou fator de von Willebrand, é:","options":{"A":"Proteína C.","B":"Glicoproteína IIB/IIIA.","C":"Proteína S.","D":"Fator V de Leiden."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-71074","number":"71074","sourceNumber":"71074","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"As proteínas C e S, assim como, protombina, fatores VII, IX e X, estão relacionados\nrespectivamente a:","options":{"A":"anticoagulação e coagulação; dependentes de vitamina K.","B":"inflamação e anticoagulação; dependentes de cálcio.","C":"anticoagulação e coagulação; dependentes de vitamina D.","D":"inflamação e coagulação; dependentes de vitamina K.","E":"inflamação e coagulação; dependentes de vitamina D."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-309775","number":"309775","sourceNumber":"309775","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O anti-hipertensivo de primeira escolha na dissecção de aorta é a/o:","options":{"A":"Furosemida","B":"Captopril","C":"Nimodipina","D":"Metoprolol","E":"Nitroglicerina"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-309796","number":"309796","sourceNumber":"309796","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente 65 anos, masculino, admitido na sala de emergência com história de dor\ntorácica de início súbito e lancinante com\nirradiação Inter escapular. Encontra-se agitado, eupneico,\nPA 220/120mmHg, FC 100pm, pulsos distais de extremidades presentes. cardioscopio na sala de\nemergência com D2 longo contínuo com ondas normais. Não há antecedente de traumas, viagens\nou cirurgias recentes. Antecedente de tabagismo, dislipidemia e hipertensão mal controlada.\n\nAssinale a alternativa correta em relação ao manejo diagnostico e ou terapêutico neste caso:","options":{"A":"Se fizer um raio-x de tórax na beira do leito e não houver alargamento de mediastino posso\nafastar a possibilidade de uma emergência aórtica aguda.","B":"A dosagem de enzimas cardíacas está dispensada neste caso com o traçado de ECG normal no\ncardioscopio. Ocorrendo modificação das ondas que se iniciaria o protocolo de infarto.","C":"Caso o paciente evolua com assimetria de pulsos nos membros superiores, sendo menor\namplitude no membro superior direito devemos\npensar no diagnóstico de dissecção de aorta tipo B\ne acionar o cirurgião vascular.","D":"A redução da pressão arterial e da frequência cardíaca deve ser imediata com uso de\nnitroprussiato e betabloqueador respectivamente.","E":"A tomografia de tórax com contraste neste caso deve priorizar a janela para parênquima\npulmonar."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-301651","number":"301651","sourceNumber":"301651","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com relação ao Brasil, não existem dados suficientes para análise detalhada quanto à\nevolução do consumo percentual de gorduras:","options":{"A":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, não mostraram diminuição significativa nas despesas domiciliares com\nóleos e gorduras.","B":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram\ndiminuição significativa nas despesas domiciliares com óleos e\ngorduras.","C":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram aumento significativo nas despesas domiciliares com óleos e\ngorduras.","D":"No entanto, resultados importantes da última POF/IBGE, 201922 que comparou o período de\n2017-2018 a 2002-2003, mostraram diminuição não significativa nas despesas domiciliares com\nóleos e gorduras."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-284213","number":"284213","sourceNumber":"284213","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em coronariopatas estáveis, a Reabilitação Cardiovascular (RCV) é uma estratégia\nque, em termos de custo-efetividade, está de\nacordo com o item:","options":{"A":"Não é capaz de superar procedimentos amplamente utilizados no país, tais como a intervenção\ncoronariana percutânea (ICP).","B":"Supera, com larga margem, procedimentos amplamente utilizados no país, tais como a\nintervenção coronariana percutânea (ICP).","C":"Supera, com larga margem, procedimentos amplamente utilizados no país, exceto a intervenção\ncoronariana percutânea (ICP).","D":"Nunca supera, somente a coronariana não percutânea."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239610","number":"239610","sourceNumber":"239610","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Nos últimos 30 anos, o tratamento dos fatores de risco cardiovascular resultou na\nredução de 50% das mortes por DAC, em\ngrande parte devido ao advento das estatinas. Podemos\naceitar que:","options":{"A":"A doença arterial coronariana (DAC) não é a principal causa de mortalidade no mundo ocidental.","B":"As estatinas são hoje a droga mais prescrita no mundo, atrás apenas dos anti-hipertensivos.","C":"A eficácia comprovada e o bom perfil de segurança, aliados ao baixo custo, têm sido os\nprincipais determinantes do aumento do uso.","D":"O grande debate atual sobre a prevenção de doenças cardiovasculares refere-se cada vez mais\nà questão de como e não quando usar estatinas no controle efetivo do risco cardiovascular mesmo\ncom banalização e supertratamento com potencial aumento de efeitos adversos."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239611","number":"239611","sourceNumber":"239611","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A fisiopatologia do IAM perioperatório difere um pouco da do IAM espontâneo. O item\nerrado é:","options":{"A":"No IAM perioperatório, a ruptura de placa ocorre em aproximadamente metade dos casos; o\nrestante se dá por um desequilíbrio prolongado entre a redução da oferta de oxigênio para o\nmiocárdio (anemia, baixo fluxo etc.) e o aumento da demanda arterial coronariana (taquicardia e\nhipertensão).","B":"TE - teste de esforço é uma ferramenta segura, útil e eficaz para a detecção de isquemia\nmiocárdica, tendo justamente como mecanismo\nproduzir este desbalanço entre oferta e demanda.","C":"Detecção de anormalidades durante execução TE - teste de esforço possa ser reprodutível\ndurante o perioperatório e seus variados\nníveis de estresse.","D":"Deve se considerar que, quanto menor a prevalência da doença coronária em determinada\npopulação, maior será também o valor preditivo positivo do TE."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-243736","number":"243736","sourceNumber":"243736","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"João, 49 anos, IMC de 39, tabagista, hipertenso e diabético em uso regular de\nhidroclorotiazida, anlodipina e metformina.\nEstá com dor do tipo aperto em região torácica anterior\nesquerda iniciada há alguns minutos, após subir 3 lances de escada para chegar ao ambulatório.\nDurante a anamnese, conta sobre crises frequentes de \"dor no coração\" com piora ao estresse\nemocional e às atividades físicas. Exame físico normal, sem reprodução de dor à palpação de\nregião torácica e ECG de repouso normal. Ao final do exame ele não sente mais dor. Sobre o caso,\né possível afirmar que:","options":{"A":"muitos pacientes com dor torácica referem que a dor pode ser de origem cardíaca, mas isso não\ntem nenhum valor semiológico","B":"o eletrocardiograma de repouso sem alterações e a melhora espontânea da dor permitem\nafastar a possibilidade de cardiopatia\nisquêmica","C":"apresentar dor torácica não reprodutível à palpação e com piora ao realizar atividade física\ntorna\nmuito provável que a causa seja doença arterial coronariana","D":"em pacientes diabéticos, o padrão de apresentação de angina é diferente de pacientes não\ndiabéticos, fazendo com que a queixa de dor torácica não seja tão importante"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239620","number":"239620","sourceNumber":"239620","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O aumento da sensibilidade dos kits disponíveis das troponinas propiciou uma maior\nacurácia e rapidez no diagnóstico ou não do IAM em pacientes com dor torácica na sala de\nemergência. Não podemos apenas concordar com o item:","options":{"A":"No perioperatório de operações não cardíacas, as evidências científicas disponíveis incluem\ntodas as troponinas (I e T) e todos métodos\nutilizados para sua dosagem, que apresentam limites\nde detecção e valores de referência diferentes.","B":"O limite de detecção significa o mínimo valor que é detectado pelo método.","C":"O valor de referência da normalidade é determinado utilizando o percentil 99, que é obtido\nrealizando-se o exame em uma população normal e significa que 99% dos indivíduos normais\napresentam valores abaixo deste cut-off.","D":"Os kits de troponina podem ser classificados em baixa (convencionais), média (contemporâneos\nou sensíveis) ou alta sensibilidade."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239621","number":"239621","sourceNumber":"239621","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Definir a melhor maneira de tratar esses pacientes submetidos à ICP Intervenção\nCoronária Percutânea torna-se fundamental,\nprincipalmente quanto à associação de medicamentos\nantiplaquetários e anticoagulantes. Não podemos aceitar que:","options":{"A":"Aproximadamente 6 a 8% dos pacientes submetidos à ICP têm indicação concomitante de\nutilização de anticoagulantes orais em longo prazo.","B":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como FA ou valvas biológicas.","C":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como valvas mecânicas.","D":"Indicação concomitante de utilização de anticoagulantes orais em longo prazo, devido a vários\nmotivos como o tromboembolismo."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-221224","number":"221224","sourceNumber":"221224","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A eficácia do AAS durante as primeiras 24 horas do IAMCSST foi demonstrada\ninicialmente. A dose apresenta a seguinte alternativa\n\ncomo CORRETA:","options":{"A":"No entanto, a utilização de doses altas de AAS não associada a aumento significante das taxas\nde sangramento menor","B":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), foi evidenciada diferença\n\nsignificante entre os dois grupos no desfecho primário de morte cardiovascular, IAM ou AVC até 30\ndias de acompanhamento","C":"No entanto, a utilização de doses altas de AAS esteve associada a aumento insignificante das\ntaxas de sangramento menor.","D":"Quando comparadas doses altas de AAS (300-325 mg por dia) a doses menores (75-100 mg ao\ndia), não foi evidenciada\n\ndiferença significante entre os dois grupos no desfecho primário de morte cardiovascular, IAM ou\nAVC até 30 dias de\n\nacompanhamento."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-221253","number":"221253","sourceNumber":"221253","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A eficácia e segurança da terapia antiplaquetária dupla TAD pós-intervenção coronária\npercutânea ICP em pacientes com alto risco de\n\nsangramento tem sido avaliada em estudos recentes. Podemos apenas concordar com o item:","options":{"A":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes não\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","B":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nsem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","C":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nassociada à terapia tripla.","D":"O manejo da terapia antiplaquetária dupla TAD em pacientes submetidos a implante de Stent e\nem uso de anticoagulantes ainda\n\nrepresenta um desafio na prática clínica devido ao elevado risco de complicações hemorrágicas\nnão associadas à terapia tripla."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-216819","number":"216819","sourceNumber":"216819","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 75 anos, tabagista, hipertenso, chega ao pronto-socorro com dor\nretroesternal em aperto, a dor é intensa, e\npersiste durante o deslocamento do paciente até o\nhospital mais próximo (45 minutos). Ao exame físico, paciente apresenta-se sudoreico, pálido, com\nB4 à ausculta cardíaca. O ECG feito na admissão revelou inversão de onda T e a troponina\nencontrava-se elevada. Qual é o seu provável diagnóstico?","options":{"A":"Miocardite.","B":"Infarto agudo do miocárdio com supra de segmento ST.","C":"Infarto agudo do miocárdio sem supra de segmento ST.","D":"Angina instável."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-214099","number":"214099","sourceNumber":"214099","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher com 50 anos, obesa, hipertensa não controlada, recém-separada do marido,\napresenta-se à consulta médica com dor torácica típica, teste ergométrico positivo e\ncineangiocoronariografia normal. No que diz respeito ao tema esquematizado nesse exemplo,\nassinale a alternativa correta.","options":{"A":"Durante testes de estresse como Teste Ergométrico, muitos desses pacientes desenvolvem dor\ntorácica e alterações eletrocardiográficas de isquemia, porém alterações cintilográficas de isquemia\nnão são presentes.","B":"Durante os perídos de maior demanda de oxigênio pelo miocárdio como exercícios físicos, esses\npacientes não produziram evidência bioquímica consistente de isquemia como elevados níveis de\nlactato pelo miocárdio.","C":"Não foram produzidas evidências de disfunção microvascular com reserva vasodilatadora\ninadequada nesses indivíduos.","D":"Aumento da sensibilidade à dor e distúbios psiquiátricos não foram correlacionados a indivíduos\ncom essa síndrome.","E":"A incidência de calcificação coronária nas imagens de tomografia computodorizada com\nmúltiplos cortes é igual a dos indivíduos-controle."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-214101","number":"214101","sourceNumber":"214101","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dá entrada na maternidade uma mulher de 40 anos, G3P2A0 com 36 semanas da\ngestação, precordialgia intensa típica iniciada há 60 minutos. O ECG demostra\nsupradesnivelamento de 3 mm do segmento ST em parede anterior. Sobre isso, é correto afirma\nque","options":{"A":"o infarto agudo do miocárdio é raro em mulheres em idade fértil, e a gestação não é fator de\nrisco para IAM.","B":"a dissecção da artéria coronária é a causa mais provável de IAM no período periparto.","C":"o IAM pode ocorrer durante qualquer estágio da gestação e é mais freguente em primíparas,\nsendo que a maioria dos eventos ocorre em\nmulheres menor que 30 anos e na maior parte do\ntempo a localização é a parede inferior.","D":"os fatores de risco tradicionais não estão presentes com frequência entre aquelas que\nexperimentam IAM durante a gestação, incluindo\ntabagismo, hiperlipidemia, hipertensão e diabetes.","E":"a angiocoronariografia de urgência deve ser evitada nessas situações."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177891","number":"177891","sourceNumber":"177891","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 70 anos procura o ambulatório de cardiologia com sintomas típicos de\nangina pectoris. Tem história prévia de IAM a cerca de 7 anos e há 4 meses iniciou dor\nretroesternal típica. Faz uso regular de antiadesivo plaquetário, além de isossorbida e\nbetabloqueador em doses tradicionais. O exame físico encontra-se praticamente normal, apenas\ncom bloqueio de ramo esquerdo no ECG de repouso. Em relação à propedêutica, qual seria o\nmelhor exame para avaliar o quadro clínico desse paciente?","options":{"A":"Ecocardiograma com stress farmacológico.","B":"Cateterismo cardíaco.","C":"Ressonância nuclear magnética do miocárdio.","D":"Cintilografia perfusional miocárdica.","E":"Teste ergométrico."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177878","number":"177878","sourceNumber":"177878","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual das seguintes patologias citadas abaixo evolui mais frequentemente com o\nachado semiológico durante o exame físico de pulso\nparadoxal?","options":{"A":"Miocardite.","B":"Angina instável.","C":"Estenose aórtica.","D":"Insuficiência aórtica.","E":"Pericardite constrictiva."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-183517","number":"183517","sourceNumber":"183517","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, com antecedente de hipertensão arterial com\ntratamento irregular, dá entrada em sala de\npronto atendimento com história de dor torácica há 2\nhoras. O ECG de entrada é: Assinale a alternativa que fornece CORRETAMENTE o diagnóstico e a\nconduta.","options":{"A":"Síndrome coronariana aguda com supra do segmento ST inferolaterodorsal. Trombólise química\nou angioplastia primária.","B":"Síndrome coronariana aguda com supra do segmento ST inferolaterodorsal: solicitar enzimas\ncardíacas e CT de tórax para descartar dissecção de aorta.","C":"Pericardite aguda. Supradifuso do segmento ST: solicitar ecocardiograma e introduzir\nibuprofeno.","D":"Tromboembolismo pulmonar. S1Q3T3: solicitar CT de tórax e ecocardiograma para avaliar\nfunção do VD. Trombólise caso VD com disfunção sistólica.","E":"Dissecção de aorta: solicitar CT de tórax com urgência."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-177941","number":"177941","sourceNumber":"177941","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Trata-se do melhor tratamento para um paciente com dissecção de aorta torácica\ndescendente não complicada. Assinale a alternativa correta.","options":{"A":"Procedimento de tronco com reparação em estágios.","B":"Substituição da aorta envolvida por enxerto.","C":"Cateterização com colocação de stent aórtico.","D":"Monitoramento do paciente sem procedimento cirúrgico, a princípio.","E":"Internação em UTI com anti-hipertensivos e hidratação vigorosa."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152285","number":"152285","sourceNumber":"152285","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 40 anos de idade, hipertensa, fumante e com histórico de uso de\nanticoncepcional oral, procura atendimento\nmédico com dor no ombro esquerdo, dispneia e\ndiaforese. Realizado avaliação física encontra sudorese fria e pegajosa, dispneia, taquipneia e\nestertores crepitantes bi basais. ECG demonstra supra de ST em V1, V2, V3 e V4. Dessa forma,\nassinale a alternativa CORRETA.","options":{"A":"Indicar angioplastia facilitada.","B":"Contraindicar beta bloqueador.","C":"Contraindicar oxigênio suplementar.","D":"Contraindicar analgésico com opioide."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152291","number":"152291","sourceNumber":"152291","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 54 anos de idade, hipertensa, fumante e com histórico de uso de\nanticoncepcional oral, procura atendimento médico com dor no ombro esquerdo, dispneia e\ndiaforese. Realizado avaliação física encontra sudorese fria, dispneia, taquipneia e estertores\ncrepitantes bi-basais. ECG demonstra supra de ST em V1, V2 e V3. Dessa forma, o tratamento\nADEQUADO deve ser feito com:","options":{"A":"Atenolol oral.","B":"Metoprolol venoso.","C":"Aspirina.","D":"Trombolítico seguido de angioplastia (facilitada)."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-152264","number":"152264","sourceNumber":"152264","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente com cirurgia de revascularização do miocárdio prévia refere dor precordial,\ncom 2 horas de evolução e apresenta\nsupradesnivelamento de segmento S-T em parede\ndiafragmática e marcadores cardíacos alterados. Nesse caso, qual é a conduta IMEDIATA?","options":{"A":"Encaminhamento para estudo hemodinâmico.","B":"Administração de fibrinolítico em Unidade Coronariana.","C":"Avaliação de fatores de risco e acompanhamento com marcadores cardíacos.","D":"Encaminhamento para cirurgia cardíaca."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-140373","number":"140373","sourceNumber":"140373","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Estratégia para o diagnóstico e tratamento da trombose venosa profunda , qual é a\nALTERNATIVA CORRETA.","options":{"A":"Hoje existe um consenso mundial de que somente o diagnostico clínico é suficiente para o\ndiagnostico de T.V.P.","B":"Exames auxiliares que demonstre direta e indiretamente a presenças do trombo não são\nnecessários para a confirmação da T.V.P.","C":"Em caso de suspeita clinica, pode-se iniciar o tratamento com anticoagulante, somente apos a\nconfirmação através de exames complementares.","D":"Em caso de suspeita clinica de T.V.P os exames complementares não precisam ser realizados\nde imediato se o paciente procurar o hospital em\nhorário em que os exames não estejam\ndisponiveis.","E":"Nenhuma das anteriores"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-138051","number":"138051","sourceNumber":"138051","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 36 anos, no terceiro dia de puerpério até então sem intercorrências, inicia\nquadro de cefaleia intensa, confusão\nmental e crise convulsiva. Ao exame físico apresenta: palidez\ncutâneo-mucosa +++, ausência de icterícia, taquicardia, ausência de sinais neurológicos\nespecíficos, ausência de hepatoesplenomegalia. Observam-se petéquias nas pernas e equimoses\nesparsas. Os exames laboratoriais iniciais mostram: Hb 6,0 g% (normo/normo), reticulócitos 5%,\nleucócitos 10300/mm³ (78% segmentados, 15% linfócitos, 7% monócitos), plaquetas 15.000,\npresença de esquizócitos. Com relação ao quadro apresentado, assinale a alternativa correta.","options":{"A":"Trata-se de sepse e o tratamento é antibioticoterapia de amplo espectro.","B":"Trata-se de Síndrome de HELLP e deve ser indicada histerectomia de urgência.","C":"A abordagem com plasmaferese deve ser instituída o mais rápido possível, pois o diagnóstico é\npúrpura trombocitopênica trombótica.","D":"Deve ser indicada transfusão de concentrado de hemácias e concentrado de plaquetas de\nurgência e avaliada reabordagem cirúrgica.","E":"Provável quadro de PTI induzida pela gestação e deve ser abordado com prednisona 1\nmg/kg/dia."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-62311","number":"62311","sourceNumber":"62311","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A síndrome de Heyde consiste na associação de sangramento gastrointestinal por\nangiodisplasia, e qual valvulopatia?","options":{"A":"Estenose mitral.","B":"Insuficiência aórtica.","C":"Estenose pulmonar.","D":"Estenose aórtica.","E":"Insuficiência mitral."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-60231","number":"60231","sourceNumber":"60231","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual combinação de exames abaixo melhor avalia a hemostasia primária:","options":{"A":"Tempo de protrombina, tempo de sangramento, dosagem de fator VIII.","B":"Contagem de plaquetas, tempo de tromboplastina parcial ativada, dosagem dos produtos de\ndegradação da fibrina (PDF).","C":"Tempo de protrombina, tempo de sangramento, tempo de coagulação.","D":"Contagem de plaquetas, tempo de sangramento, avaliação da função plaquetária.","E":"Tempo de coagulação, tempo de tromboplastina parcial ativada, tempo de protrombina."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-22631","number":"22631","sourceNumber":"22631","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Constituem recomendações clássicas para a profilaxia de fenômenos tromboembólicos,\nEXCETO:","options":{"A":"Idade acima de 40 anos.","B":"Cirurgias ortopédicas, urológicas e ginecológicas.","C":"Portadores de neoplasias.","D":"Obesidade.","E":"Em paciente diabéticos, mesmo na ausência de co-morbidades."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-25760","number":"25760","sourceNumber":"25760","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à Coagulação Intravascular Disseminada (CIVD) em pediatria, assinale a\nalternativa incorreta.","options":{"A":"A causa mais comum de CIVD em UTI pediátrica é a sepse","B":"A liberação de endotoxinas lesa diretamente a parede vascular, expondo o subendotélio","C":"Pode levar a formação de microtromboses disseminadas provocando isquemia de órgãos","D":"Os germes mais frequentemente envolvidos são os gram-positivos","E":"A superfície subendotelial exposta ativa o fator XII e toda via intrínseca da coagulação"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-25765","number":"25765","sourceNumber":"25765","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dos fatores de coagulação abaixo, qual não é considerado vitamina K dependente:","options":{"A":"Fator II","B":"Fator V","C":"Fator VII","D":"Fator IX","E":"Fator X"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-359377","number":"359377","sourceNumber":"359377","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 64 anos foi atendido no pronto-socorro de um hospital que não possui\nserviço de hemodinâmica. Foi diagnosticado\ncom infarto agudo do miocárdio (IAM) com\nsupraelevação do segmento ST. Recebeu tratamento trombolítico com alteplase, apresentou\nresposta clínica e eletrocardiográfica (ECG pós-reperfusão sem anormalidades) e permaneceu sob\nmonitorização. Encontrava-se assintomático e apresentava os seguintes dados vitais: FC 68bpm,\nFR 18ipm, SpO2 95% (ar ambiente), PA 136/84mmHg, quando foi observado o seguinte traçado\neletrocardiográfico: Assinale a alternativa que apresenta a conduta MAIS ADEQUADA neste\nmomento em relação à abordagem da alteração eletrocardiográfica observada:","options":{"A":"Administração de amiodarona pela via IV.","B":"Cardioversão elétrica sincronizada.","C":"Conduta expectante e suporte clínico.","D":"Transferência para cateterismo de urgência (em até 1 hora)."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-359376","number":"359376","sourceNumber":"359376","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale a alternativa que apresenta um achado semiológico que NÃO poderia ter sido\ncausado pela anormalidade identificada ao ECG:","options":{"A":"Desdobramento amplo da primeira bulha cardíaca (B1).","B":"Desdobramento amplo e variável, mais acentuado durante a inspiração, da segunda bulha\ncardíaca (B2).","C":"Ondas A em canhão irregulares ao exame do pulso venoso central.","D":"Variação da intensidade de B1 a cada batimento cardíaco."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-149917","number":"149917","sourceNumber":"149917","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 66 anos, admitido com infarto agudo do miocárdio acometendo parede\ninferior do ventrículo esquerdo com seis\nhoras de evolução, apresenta-se com níveis pressóricos\nreduzidos, sinais de pressão venosa aumentada e pulmões limpos à ausculta. Qual afecção abaixo\nexplica MELHOR este quadro clínico?","options":{"A":"Edema agudo de pulmão.","B":"Falência ventricular esquerda.","C":"Infarto agudo do ventrículo direito.","D":"Síndrome pós-infarto do miocárdio."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-78429","number":"78429","sourceNumber":"78429","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 35 anos é atendido no Pronto-Socorro queixando-se de dispneia súbita. O\nnível sérico do D-dímero encontra-se acima dos valores de referência e a tomografia de tórax\nhelicoidal evidencia falha de enchimento na artéria do segmento basal posterior do lobo pulmonar\ninferior direito. Em relação aos fatores etiopatogênicos que podem estar relacionados a esse\nevento, é CORRETO afirmar que:","options":{"A":"A presença do anticorpo anti-fosfolípide alarga o tempo parcial de tromboplastina e previne a\nformação de trombos.","B":"O aumento dos níveis séricos da antitrombina III, da proteína C e da proteína S aceleram a\nformação de coágulos.","C":"O fator V de Leiden, mutação autossômica dominante, interfere na ação da proteína C ativada.","D":"O gene mutante da protrombina diminui a concentração plasmática da protrombina."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-60337","number":"60337","sourceNumber":"60337","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em face do traçado eletrocardiográfico abaixo reproduzido, seria lícito esperar que o\npaciente referisse a seguinte queixa: (VER IMAGEM)","options":{"A":"Dor precordial irradiada para a borda do músculo trapézio esquerdo, aliviada pela posição\nsentada, com o tórax inclinado para frente, e\nagravada pela inspiração profunda e pelo decúbito\ndorsal.","B":"Dor precordial irradiada para a borda do músculo trapézio esquerdo, aliviada pela inspiração\nprofunda e agravada pela posição sentada, com o tórax inclinado para frente.","C":"Dor precordial irradiada para o braço esquerdo, aliviada pelo decúbito dorsal e agravada pela\ninspiração profunda e pela posição sentada, com o tórax inclinado para frente.","D":"Dor precordial irradiada para o dorso, aliviada pelo decúbito dorsal e agravada pela posição\nsentada, com o tórax inclinado para frente."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-45065","number":"45065","sourceNumber":"45065","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 65 anos com história de três dias de evolução de diarreia. Relata ter\nchegado da praia e seu filho também\napresenta diarreia. Diz ter acabado tratamento adjuvante para\ncâncer gástrico há 45 dias e tinha viajado para descansar. Após um dia de fezes líquidas, evoluiu\ncom dor abdominal em cólica, hematoquezia e vômito. Apresentava ao exame físico hipotensão\nortostática. Seus exames iniciais mostravam hemoglobina de 12,5 g/dl, creatinina de 1,5 mg/dl e\nureia de 30 mg/dl. Foi iniciada hidratação venosa e colhida cultura fecal para patógenos habituais.\nDois dias após internação, sua ureia era de 200 mg/dl, creatinina de 7,5 mg/dl, hemoglobina de 8,5\ng/dl e plaquetas de 60.000/mm². A alternativa CORRETA é:","options":{"A":"Este paciente apresenta quadro muito sugestivo de metástase para cólon de seu câncer gástrico\ne um enema opaco deve ser feito\nimediatamente.","B":"O paciente deve ser tratado com medicamento antiparasitário, pois, provavelmente, desenvolveu\numa infecção por E. histolytica.","C":"O provável diagnóstico deste paciente é síndrome hemolítico-urêmica causada por Escherichia\ncoli. Terapia apropriada de suporte, incluindo\ndiálise, deve ser oferecida.","D":"O tratamento imediato deve ser a introdução de medicamento antidiarreico (ioperamida) para\ncontrolar a perda de líquido e tratar a insuficiência renal aguda (pré-renal) desenvolvida."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-52362","number":"52362","sourceNumber":"52362","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente com neoplasia de cólon de indicação cirúrgica, apresenta como\ncomorbidades: obesidade mórbida, fibrilação\natrial e varizes de membros inferiores. Foi submetida\nà colectomia segmentar e no 2° DPO evoluiu com dispneia importante e sinais clínicos de baixo\ndébito. Em relação a esse caso, podemos afirmar, EXCETO:","options":{"A":"A angiotomografia helicoidal do tórax pode identificar trombos em grandes vasos pulmonares.","B":"A dosagem sérica do d-dímero pode nos auxiliar na exclusão do diagnóstico de\ntromboembolismo pulmonar.","C":"O diagnóstico mais provável é tromboembolismo pulmonar.","D":"Para essa paciente estaria indicado o uso profilático de heparina não fracionada na dose de\n5000 unidades subcutâneas de 12 em 12 horas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-359305","number":"359305","sourceNumber":"359305","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"É CORRETO afirmar que o uso de corticosteroides no tratamento da pericardite aguda\nestá indicado para","options":{"A":"pacientes que não responderam aos anti-inflamatórios não hormonais e à colchicina.","B":"todos os pacientes, independente de comorbidades anteriores.","C":"casos de etiologia viral.","D":"pacientes com alergia ao ácido acetilsalicílico."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-340700","number":"340700","sourceNumber":"340700","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A recomendação da dupla antiagregação plaquetária DAPT, com associação de ácido\nacetilsalicílico e um inibidor de P2Y12 (clopidogrel, ticagrelor ou prasugrel) após intervenção\ncoronária percutânea ICP, varia conforme o contexto clínico (doença arterial aguda ou crônica) e\ntipo de stent utilizado. Sobre isso, podemos afirmar que:","options":{"A":"Em pacientes submetidos à ICP fora da vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses, podendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","B":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 2 meses, podendo\na terapia ser reduzida para 6 dias ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","C":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses,\npodendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, bem como o risco\nisquêmico.","D":"Em pacientes submetidos à ICP na vigência de síndrome coronariana aguda (SCA),\nrecomenda-se a manutenção por 12 meses,\npodendo a terapia ser reduzida para 6 meses ou\nestendida, levando-se em consideração o risco individual de sangramento, mas não o risco\nisquêmico."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-340706","number":"340706","sourceNumber":"340706","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"No contexto de Doença Arterial Coronariana (DAC) crônica, a recomendação atual é a\nrealização de dupla antiagregação plaquetária (DAPT):","options":{"A":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 3 a\n12 meses para os stents farmacológicos, com\nabreviação excepcionalmente em 30 dias, a\ndepender do risco de sangramento e geração do stent implantado.","B":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 2\nmeses para os stents farmacológicos, com\nabreviação excepcionalmente em 3 dias, a depender do\nrisco de sangramento e geração do stent implantado.","C":"Durante tempo mínimo de 4 a 6 semanas para stents não farmacológicos, e geralmente de 3 a\n12 meses para os stents farmacológicos, com\nabreviação excepcionalmente em 30 dias,\nindependente do risco de sangramento e geração do stent implantado.","D":"Durante tempo mínimo de 4 a 6 semanas para stents farmacológicos, e geralmente de 3 a 12\nmeses para os stents não farmacológicos, com\nabreviação excepcionalmente em 30 dias, a\ndepender do risco de sangramento e geração do stent implantado."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-346207","number":"346207","sourceNumber":"346207","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 47 anos, previamente hipertenso em uso irregular das medicações, foi\nadmitido no pronto atendimento com quadro\nde dor torácica intensa com irradiação para dorso.\nAlega parestesia de membro superior esquerdo associada. A dor teve início no momento em que\ntrabalhava como mecânico. Apresentava PA em MSE de 185 x 120 mmHg e em MSD de 225 x 135\nmmHg. Realizado Ultrassom à beira leito, sendo notada linha de dissecção intimal em aorta\nascendente e arco aórtico. Sobre o caso clínico acima, diagnóstico e tratamento, assinale a\nalternativa correta.","options":{"A":"A dissecção de aorta é uma emergência hipertensiva e o seu tratamento inicial é idealmente\nrealizado com medicação endovenosa como\nnitroglicerina. A queda da PA deve ser gradual, de até\n25% na primeira hora.","B":"A dissecção de aorta é uma urgência hipertensiva, o seu tratamento inicial é idealmente\nrealizado com Nitroglicerina. A queda da PA\ndeve ser gradual, de até 20 mmHg na primeira hora.","C":"A dissecção de aorta é uma emergência hipertensiva e o seu tratamento inicial é idealmente\nrealizado com nitroprussiato de sódio e betabloqueador endovenosos. A queda da PA deve ser\nmais rápida, tendo como objetivo PAS<120 mmHg em 20 minutos.","D":"A dissecção de aorta é considerada uma pseudocrise hipertensiva, com o aumento da PA\ndecorrente da dor torácica. A PA deve ser\ncontrolada a partir do controle da dor, podendo utilizar\nmorfina como tratamento.","E":"A dissecção de aorta é uma urgência hipertensiva, podendo a PA ser controlada com\nmedicamentos orais, como anlodipino. A queda\nda PA deve ser gradual, de até 25% na primeira\nhora."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-346210","number":"346210","sourceNumber":"346210","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A pericardite é caracterizada por inflamação do pericárdio, podendo levar a um\nimportante derrame pericárdico e sintomas como\ndor torácica e dispneia. O exame físico pode ser\ncaracterizado pela presença de atrito pericárdico à ausculta cardíaca e o seu prognóstico depende\ndo acometimento e da causa. Sabendo disso, marque a alternativa que apresenta a causa mais\ncomum de pericardite.","options":{"A":"Doença bacteriana.","B":"Doença fúngica.","C":"Neoplasias.","D":"Doença viral.","E":"Lúpus eritematoso sistêmico."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-340764","number":"340764","sourceNumber":"340764","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O desempenho de exercícios resistidos em 2 a 3 dias por semana também pode ser\nrecomendado.","options":{"A":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 900 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado.","B":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 50 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado.","C":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade não vigorosa, ou uma combinação equivalente dos\nmesmos, idealmente com exercício diário supervisionado.","D":"Para benefício adicional em adultos saudáveis, recomenda-se um aumento gradual da atividade\nfísica aeróbica para 300 minutos por semana de\nintensidade moderada ou 150 minutos por semana\nde atividade física aeróbica de intensidade vigorosa, ou uma combinação equivalente dos mesmos,\nidealmente com exercício diário supervisionado."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278836","number":"278836","sourceNumber":"278836","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica é o principal sintoma sugestivo de Síndrome Coronária Aguda (SCA) com\ncaracterísticas da dor torácica sugestivas de isquemia miocárdica. Sendo correto que:","options":{"A":"Pacientes com dor anginosa em repouso com mais de 60 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA.","B":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor não são sugestivas de SCA.","C":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de ambulatório\nde cardiologia, já que essas características da dor são sugestivas de SCA.","D":"Pacientes com dor anginosa em repouso com mais de 20 minutos de duração, angina limitante\nde início recente e angina em crescendo (maior\nfrequência, maior intensidade e menor limiar para\naparecimento dos sintomas que o habitual) devem ser encaminhados aos serviços de emergência,\njá que essas características da dor são sugestivas de SCA."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-260533","number":"260533","sourceNumber":"260533","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A elevação do segmento ST, localizada em V1 e V2 não pode ser detectada no traçado\neletrocardiogràfico de :","options":{"A":"Padrão de Brugada.","B":"Hipercalcemia.","C":"Hipertrofia ventricular direita.","D":"Hiperpotassemia."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-260534","number":"260534","sourceNumber":"260534","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentre as doenças a seguir a que cursa mais habitualmente com pulso paradoxal é:","options":{"A":"Tamponamento Cardíaco.","B":"Insuficiência cardíaca diastólica.","C":"Insuficiência aórtica.","D":"Dissecção aórtica."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-260257","number":"260257","sourceNumber":"260257","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com relação às Síndromes Coronarianas Agudas Sem Supradesnivelamento do\nSegmento ST (SCASST), assinale a alternativa INCORRETA.","options":{"A":"Os betabloqueadores devem ser iniciados precocemente, na ausência de contraindicações.","B":"O emprego da nitroglicerina deve ser considerado quando houver precordialgia persistente,\ncongestão pulmonar e/ou hipertensão arterial\nrefratária.","C":"A mortalidade dos pacientes com SCASST, em longo prazo, é inferior à dos pacientes com\nsíndrome coronariana aguda com supradesnivelamento do segmento ST.","D":"O escore GRACE (Global Registry of Acute Coronary Events) permite avaliar a gravidade dos\npacientes, fornecendo uma estratificação de risco precisa tanto na admissão quanto na alta."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-266594","number":"266594","sourceNumber":"266594","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 23 anos realiza avaliação períodica de saúde. Não apresenta queixas\nexpecíficas. O exame cardiovascular revela\nestalido mesossistólico agudo e sopro suave que se\ninicia após o estalido e encobre a segunda bulha parcialmente, mais audível na ponta do coração\ncom irriadiação para a axila esquerda. Ao realizar a manobra de Valsalva, o estalido tornou-se mais\npróximo da primeira bulha, mais audível, e o sopro aumentou a intensidade. Assinale a alternativa\nque apresenta outra manobra MAIS provavelmente capaz de tornar o estalido e o sopro mais\npróximos da primeira bulha e mais intensos.","options":{"A":"Agachamento.","B":"Aperto de mão (hand grip).","C":"Elevação passiva dos membros inferiores.","D":"Ficar de pé rapidamente."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-262943","number":"262943","sourceNumber":"262943","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Numere a COLUNA II de acordo com a COLUNA I, estabelecendo a melhor correlação\nentre o sinal semiológico e a doença que pode\ncausá-lo. COLUNA I 1. Asterixis 2. Atrito pericárdico\n\n3. Crepitações teleinspiratórias 4. Osteoartropatia hipertrófica 5. Sopro diastólico no terceiro\nespaço\nintercostal direito COLUNA II ( ) Cirrose hepática ( ) Insuficiência cardíaca ( ) Retocolite\nulcerativa (\n\n) Sífilis ( ) Uremia Assinale a sequência correta.","options":{"A":"3 4 1 2 5","B":"1 2 3 5 4","C":"1 3 4 5 2","D":"5 3 4 1 2"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-278882","number":"278882","sourceNumber":"278882","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Estudos clínicos randomizados, que demonstram significativas reduções da\nmorbimortalidade cardiovascular e global, em como da taxa de hospitalização, com expressivo\nganho de qualidade de vida, justificando a sua consensual e enfática recomendação pelas\nprincipais sociedades médicas mundiais dos efeitos favoráveis da Reabilitação Cardiovascular\n(RCV).","options":{"A":"O principal objetivo da RCV com ênfase nos exercícios físicos é propiciar uma melhora dos\ncomponentes da aptidão física, aeróbico e nunca dos não aeróbicos (força/ potência muscular,\nflexibilidade, equilíbrio).","B":"O principal objetivo da RCV com ênfase nos exercícios físicos é propiciar uma melhora dos\ncomponentes da aptidão física, tanto aeróbico quanto não aeróbicos (força/ potência muscular,\nflexibilidade, equilíbrio).","C":"O principal objetivo da RCV com ênfase nos exercícios físicos é não propiciar uma melhora dos\ncomponentes da aptidão física, tanto aeróbico quanto não aeróbicos (força/ potência muscular,\nflexibilidade, equilíbrio).","D":"O principal objetivo da RCV com ênfase nos exercícios físicos é propiciar uma melhora dos\ncomponentes da aptidão física, somente aeróbico (força/ potência muscular, flexibilidade,\nequilíbrio)."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-253900","number":"253900","sourceNumber":"253900","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Analise as alternativas abaixo e marque o betabloqueador que não está aprovado para\ntratamento clínico da cardiopatia isquêmica:","options":{"A":"Propranolol","B":"Metoprolol","C":"Carvedilol","D":"Bisoprolol"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-253902","number":"253902","sourceNumber":"253902","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma opção terapêutica nos pacientes com doença coronariana crônica estável é a\ninibição do metabolismo de ácidos graxos pelos miócitos, que passam a utilizar vias metabólicas\nmais eficientes, diminuindo a isquemia. O medicamento que possui este mecanismo de ação é:","options":{"A":"Neprisilina","B":"Levosimendan","C":"Ivabradina","D":"Trimetazidina"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-244513","number":"244513","sourceNumber":"244513","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Estudos sugerem que a terapia com AAS pode estar associada a uma diminuição do\nAVC entre mulheres diabéticas. Dos itens\nabaixo, qual apresenta erro?","options":{"A":"Ocorre uma diminuição do infarto agudo do miocárdio (IAM) entre homens diabéticos.","B":"Ocorrem que as reduções de risco obtidas com baixas doses (75 mg/dia) foram tão significativas\nquanto às obtidas com doses mais elevadas (650\nmg/dia).","C":"Baixa dose de AAS era benéfica para a prevenção primária de DCV nos pacientes de alto risco e\nque a decisão sobre o tratamento com AAS\ndeveria ser feita coletivamente.","D":"Indicação da terapia antiplaquetária nos pacientes de muito alto risco, incluindo aqueles com\nDACL e eventos cardiovasculares prévios\n(prevenção secundária), o benefício é estabelecido."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-239818","number":"239818","sourceNumber":"239818","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual situação apresenta desdobramento amplo da segunda bulha?","options":{"A":"Bloqueio de ramo esquerdo.","B":"Bloqueio divisional antero-superior.","C":"Bloqueio de ramo direito.","D":"Bloqueio divisional póstero-inferior."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-238754","number":"238754","sourceNumber":"238754","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 65 anos é admitido no pronto-atendimento do Hospital da Polícia Militar\nde Minas Gerais com a queixa de dor\nretroesternal de início súbito, lancinante, há\naproximadamente 60 minutos, associada a sudorese fria e dispneia aos pequenos esforços. É\ntabagista e portador de hipertensão arterial sistêmica, em uso irregular de enalapril e anlodipino.\nAo\nexame físico, está inquieto, ansioso e sudorético. Os dados vitais são PA170/100mmHg, FC\n90bpm, FR 25ipm, SpO2 em ar ambiente 94%. A ausculta respiratória revela crepitações\nteleinspiratórias discretas nas bases pulmonares. O exame cardiovascular revela assimetria de\npulsos radiais, ritmo cardíaco regular, sopro diastólico aspirativo na borda paraesternal esquerda,\nsuave, de intensidade II/VI. Não há serviço de hemodinâmica no Hospital. Eletrocardiograma da\nadmissão: infradesnivelamento de 3mm do segmento ST em V1 a V4 e supradesnivelamento de\n2,5mm em V7 e V8. Assinale a alternativa CORRETA sobre o caso deste paciente.","options":{"A":"Está indicada a trombólise imediata com alteplase com o tempo porta-agulha de até 30 minutos.","B":"As alterações vistas ao eletrocardiograma sugerem território isquêmico no território da artéria\ncoronária descendente anterior.","C":"Está indicada a realização de ecocardiograma transesofágico de urgência.","D":"A troponina I atinge seu pico nas primeiras 4 horas dos sintomas, sendo método diagnóstico\nauxiliar para o diagnóstico da síndrome\ncoronariana aguda."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-238640","number":"238640","sourceNumber":"238640","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Após a administração de fibrinolítico no infarto agudo do miocárdio com\nsupradesnivelamento do segmento ST, indica-se a\nintervenção coronariana percutânea de resgate\nna seguinte situação:","options":{"A":"Quando há aumento de troponina após seis horas de administração do fibrinolítico.","B":"Sempre e imediatamente após o término da fibrinólise.","C":"Manutenção da dor torácica e/ou se não houver redução de pelo menos 50% do\nsupradesnivelamento do ST no eletrocardiograma.","D":"Se o paciente apresentar ritmo idioventricular acelerado ao eletrocardiograma."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-219404","number":"219404","sourceNumber":"219404","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente sexo feminino de 32 anos apresentando piora dor torácica retroesternal nos\núltimos 7 dias. Ela se queixa de dispneia e edema de membros inferiores. Faz uso de\nhidroxicloroquina para lesão facial fotossensível, rash e úlceras orais. Rx tórax com aumento da\nsilhueta cardíaca. Qual a descrição mais característica do seu pulso?","options":{"A":"Anacrótico","B":"Bífido","C":"Colapsante","D":"Baixa amplitude"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-201647","number":"201647","sourceNumber":"201647","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 45 anos, portador de dislipidemia e diabetes, é admitido no Hospital da\nPolícia Militar queixando-se de dor torácica retroesternal, ventilatório-dependente, que melhora na\nposição sentada e inclinado para a frente, associada à dispneia leve, de início há 6 horas. Nega\nuso de entorpecentes. Realizado o ECG apresentado abaixo. Troponina = 0,2 ng/ml (VR = 0,01\nng/ml). Sobre esse caso, marque a alternativa CORRETA:","options":{"A":"Trata-se de infarto agudo do miocárdio de parede anterior extenso, sendo indicado cateterismo\nde urgência ou trombólise.","B":"Deve-se realizar angiotomografia de tórax ou cintilografia pulmonar de ventilação e perfusão na\nurgência e iniciar anticoagulação plena.","C":"A realização de ecocardiograma não contribui para o diagnóstico e a avaliação da gravidade.","D":"Anti-inflamatório, colchicina e repouso são medidas que devem ser prontamente instituídas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-203929","number":"203929","sourceNumber":"203929","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 52 anos com quadro de dor torácica de moderada intensidade, em aperto,\ncom irradiação para MSE, duração de 8 minutos e\nassociada a dispneia e sudorese. Paciente é\nhipertenso e diabético. Apresenta ECG a seguir: De acordo com a principal hipótese diagnóstica\npara o quadro descrito, são medicamentos que podem fazer parte do tratamento do paciente,\nEXCETO:","options":{"A":"Alteplase.","B":"Isordil.","C":"Clopidogrel.","D":"Ticagrelor."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-210452","number":"210452","sourceNumber":"210452","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Analise o caso abaixo: um paciente de 52 anos foi admitido na UPA/Oeste com quadro\nde dor torácica típica para insuficiência\ncoronariana aguda. O ECG mostrava supradesnivelamento\nde ST em DII, DIII e AVF, além de V3R e V4R (derivações feitas como imagem em espelho de V3 e\nV4 tradicionais, mais à direita). Não apresentava crepitações à ausculta pulmonar, mas exibia\nhipotensão e confusão mental. Ao exame, também apresentava elevação paradoxal da veia jugular\nexterna durante a inspiração. Assinale a alternativa que representa as informações consideradas\nCORRETAS sobre o caso descrito:","options":{"A":"O paciente apresenta um quadro de infarto agudo do miocárdio de parede inferior de VE com\ninfarto de ventrículo direito e sinal de Kussmaul.","B":"O edema agudo dos pulmões pode se apresentar com ausculta pulmonar normal se o paciente\ntiver infarto da artéria circunflexa.","C":"O paciente apresenta-se também com sinais de tromboembolismo pulmonar maciço ou\ndissecção aguda da aorta, sendo necessário\nsaber pelo menos as enzimas cardíacas para indicar a\ntrombólise.","D":"O quadro desse paciente se confunde com pericardite constritiva crônica com sinais de baixo\ndébito cardíaco e, nesse caso, o ecocardiograma é necessário para o diagnóstico diferencial."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181241","number":"181241","sourceNumber":"181241","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"O uso da Ecocardiografia sob estresse na doença aterosclerótica coronariana crônica,\nsomente não apresenta a seguinte característica descrita a seguir:","options":{"A":"O ecocardiografia sob estresse é um método não invasivo, estabelecido para a avaliação de\npacientes com DAC obstrutiva suspeita ou conhecida, para a determinação do diagnóstico e\nprognóstico, na avaliação do impacto de terapias de revascularização, mas não na detecção de\nviabilidade miocárdica.","B":"O estresse cardiovascular causa isquemia miocárdica em regiões supridas por uma artéria com\ngrau significativo de estenose, e esse fenômeno é manifestado por alteração transitória da\ncontração segmentar.","C":"A ecocardiografia bidimensional permite a avaliação de todos os segmentos miocárdicos do\nventrículo esquerdo com grande resolução\nespacial e temporal, tornando-se a ferramenta ideal para\na avaliação não invasiva da isquemia miocárdica.","D":"Os métodos disponíveis para a indução do estresse são o esforço físico (esteira ou bicicleta\nergométrica), a estimulação atrial transesofágica, e o uso de drogas vasodilatadoras (dipiridamol e\nadenosina) ou de estimulantes adrenérgicos (dobutamina)."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181253","number":"181253","sourceNumber":"181253","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Durante última visita em grupo da cardiologia, você foi indicado para explicar aos\ncolegas sobre o uso de Marcadores de Lesão\nMiocárdica, sua apresentação foi bastante elogiada,\nmas o chefe do setor não concordou com uma de suas afirmações. De acordo com as últimas\ndiretrizes aceitas, aponte essa possível afirmação:","options":{"A":"Embora as troponinas sejam importantes fatores prognósticos de risco, elas não devem ser\nutilizadas isoladamente para definir o risco de pacientes com SCA.","B":"A maior parte dos pacientes que desenvolvem complicações apresenta troponinas normais;\nnenhum marcador bioquímico é perfeitamente acurado para determinar dano miocárdio.","C":"As Troponinas nos paciente que se apresentam em menos de 3 horas do início dos sintomas,\nestão dentro do valor de normalidade, não\nsendo sempre necessária a mensuração seriada do\nmarcador.","D":"As troponinas na admissão estão dentro do valor de normalidade em até um quinto dos\npacientes que depois confirmam diagnóstico de IAM."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181027","number":"181027","sourceNumber":"181027","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 64 anos com história prévia de radioterapia com irradiação do tórax\napresenta-se com sintomas gradualmente\nprogressivos de fadiga, ascite, edema de membros\ninferiores e elevação da pressão venosa jugular ao longo dos últimos 4 meses. A radiografia do\npaciente é mostrada abaixo. A respeito do provável diagnóstico é CORRETO afirmar:","options":{"A":"O paciente irá apresentar a onda Y do pulso venoso jugular atenuada.","B":"A tomografia de tórax é menos precisa que o ecocardiograma para demonstrar o diagnóstico.","C":"A tuberculose não é causa importante do diagnóstico nos países em desenvolvimento.","D":"Pode haver Knock pericárdico na diástole."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-184588","number":"184588","sourceNumber":"184588","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 44 anos apresenta dor precordial súbita, irradiando para mandíbula,\nassociado a náuseas e sudorese. ECG mostrou\nsupradesnivelamento de V1-V4. Qual a artéria\nacometida?","options":{"A":"Descendente anterior.","B":"Coronária circunflexa.","C":"Coronária esquerda.","D":"Descendente posterior."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-178002","number":"178002","sourceNumber":"178002","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente chega à unidade de pronto atendimento, com diagnóstico de infarto agudo do\nmiocárdio com supradesnível do ST. Em qual das condições seria possível indicar trombólise?","options":{"A":"Acidente vascular cerebral isquêmico há 6 meses.","B":"Acidente vascular cerebral hemorrágico há 1 ano.","C":"Traumatismo crânio encefálico há 3 meses.","D":"Qualquer lesão vascular cerebral conhecida (malformação arteriovenosa)."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181231","number":"181231","sourceNumber":"181231","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Dentro da necessidade de monitorização, um de seus pacientes deu entrada essa\nmanhã transferido de outro hospital já com\ndiagnóstico de IAM, sendo que a monitorização\neletrocardiográfica é recomendada a todos os pacientes com suspeita de SCA, a partir do primeiro\ncontato médico. Sendo INCORRETO o seguinte item:","options":{"A":"Deve ser contínua, durante a permanência na unidade coronariana.","B":"Pode ser utilizada sob a forma de telemetria, em unidade intermediária ou no quarto na fase\npré-alta hospitalar.","C":"As arritmias cardíacas e os distúrbios de condução são raros nas primeiras horas do IAM, mas\nsua identificação deve ser imediata para adequada\nintervenção.","D":"O traçado eletrocardiográfico deve ser estável, com derivações padronizadas, com sistema de\nalarmes ajustados, permitindo adequada identificação de arritmias, assim como de alterações do\nsegmento ST."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-179153","number":"179153","sourceNumber":"179153","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 60 anos, sexo masculino, hipertenso há 20 anos, tabagista 30 anos/maço e\ndiabético insulino-dependente. Foi admitido no pronto-socorro com queixa de dor precordial de\nintensidade 7/10, iniciada em repouso há 1 hora, com irradiação para ambos os membros\nsuperiores e dorso, associado a náuseas e vômitos. Ao admitir o paciente na sala de emergência, a\npropedêutica mais adequada a ser seguida é:","options":{"A":"Solicitar mioglobina, creatinofosfoquinase, creatinoquinase MB massa e troponina por\napresentarem alta especificidade e valor\npreditivo positivo em casos de infarto agudo do miocárdio,\nnas primeiras 2 horas dos sintomas.","B":"Realizar eletrocardiograma nos primeiros 10 minutos após a admissão do paciente e repetir\nsempre que necessário ou se houver mudança dos sintomas (melhora ou piora).","C":"A presença de supradesnivelamento do segmento ST ? 2 mm em derivação AVR sugere infarto\nde ventrículo direito, sendo o próximo passo a\nrealização de radiografia de tórax para avaliar\ncongestão pulmonar.","D":"A presença de supradesnivelamento do segmento ST ? 2 mm em derivações D2, D3 e AVF\nsugere infarto de parede inferior. A\ncomplementação eletrocardiográfica com derivações V3R, V4R,\nV5 e V6 deverá ser realizada objetivando diagnosticar infarto de ventrículo direito e de parede\nposterior."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-158313","number":"158313","sourceNumber":"158313","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente apresenta dor precordial em repouso de início há 40 minutos. Apresenta o\nECG a seguir: (Conforme imagem do caderno de questões). Qual a conduta mais importante?","options":{"A":"Heparinização plena.","B":"Cineangiocoronariografia e angioplastia primária.","C":"Analgesia com morfina.","D":"Controle pressórico."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-155247","number":"155247","sourceNumber":"155247","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A respeito das dores torácicas agudas, marque a alternativa CORRETA.","options":{"A":"A dor secundária a pericardite aguda é frequentemente retroesternal, podendo\n\nirradiar para o ombro esquerdo e piora na posição sentada e com a inclinação para frente.","B":"Apesar de rara, dor secundária a processos osteomusculares deve ser considerada no\ndiagnóstico diferencial da dor torácica aguda.","C":"Uma forma de diferenciar a dor de origem isquêmica da dor originada de espasmo esofageano é\natravés da realização de prova terapêutica com nitrato.","D":"Em pacientes com dor torácica aguda, baixa probabilidade para tromboembolismo pulmonar e\nD-dímero normal, angiotomografia de tórax torna-se desnecessária para afastar este diagnóstico."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-158007","number":"158007","sourceNumber":"158007","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"O substrato anatomopatológico comum ao infarto agudo do miocárdio à angina instável é a placa\nde ateroma calcificada não complicada.","B":"O uso de betabloqueadores nas síndromes coronarianas agudas tem a finalidade de estabilizar\na placa de ateroma rota, com obstrução\ntrombótica secundária.","C":"Na angina estável não é necessário o uso de antiagregantes plaquetários.","D":"O uso de nitratos deve ser evitado no infarto agudo do miocárdio com comprometimento do\nventrículo direito."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-163448","number":"163448","sourceNumber":"163448","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação ao tromboembolismo e à trombose venosa profunda assinale a afirmativa\nERRADA:","options":{"A":"A dosagem sérica de D-dímero tem alta sensibilidade e é específica para o diagnóstico de\ntromboembolismo pulmomar.","B":"Cintilografia de perfusão inalterada, praticamente, afasta o diagnóstico de tromboembolismo\npulmonar.","C":"Na presença de trombose venosa profunda sem causa aparente deve-se pesquisar câncer\noculto.","D":"O período pós-operatório imediato de cirurgia oftalmológica é contraindicação de\nanticoagulação."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-158228","number":"158228","sourceNumber":"158228","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher de 21 anos, assintomática, com sopro mesossistólico audível no 2° espaço\nintercostal esquerdo, irradiando para a região\ninfraescapular ipsilateral, em crescendo-decrescendo,\ngrau II, além de movimento paraesternal inferior esquerdo de grande amplitude, pulsação no\n2°espaço intercostal esquerdo e desdobramento fixo da segunda bulha. Considerando o caso\ndescrito, assinale a alternativa CORRETA.","options":{"A":"Esses achados são fisiológicos nessa faixa etária.","B":"O sopro auscultado se deve ao hiperfluxo na valva pulmonar.","C":"A primeira bulha cardíaca, geralmente, é hipofonética.","D":"A estenose pulmonar congênita é a principal hipótese."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157815","number":"157815","sourceNumber":"157815","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Correlacione achado da semiologia cardiovascular com laudos de ECG. a - Ritmo\ncardíaco irregular, com variações de fonese de\nprimeira bulha.; b - Desdobramento de B2 na\nexpiração em foco pulmonar.; c - Desdobramento de B2 na inspiração em foco pulmonar.; d ?\nHipofonese de B1.; 1 ? Bloqueio de ramo direito.; 2 ? Bloqueio de ramo esquerdo.; 3 ? Normal.; 4 ?\nFibrilação atrial.; 5 ? Taquicardia atrial multifocal.; 6 ? Bloqueio Atrio-ventricular de 1º grau.\n\nAssinale a alternativa correta.","options":{"A":"4A, 2C, 6D","B":"4D, 2B, 3C","C":"5A, 1B, 6D","D":"5D, 3B, 6A","E":"2B, 3B, 4D"},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-157816","number":"157816","sourceNumber":"157816","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Tabagista de 59 anos, queixa-se de dor torácica retroesternal em aperto há 30 minutos.\nSua esposa, por recomendação médica, se\nlembrou e administrou nitroglicerina sublingual e\noxigênio por cateter nasal. A pressão arterial é de 115 x 70 mmHg, e sua frequência cardíaca é de\n90 bpm. Foi conduzido imediatamente ao Pronto Socorro. Na chegada, realizaram um ECG que\nestava normal. Qual dos seguintes é o passo mais adequado? Assinale a alternativa correta:","options":{"A":"Ecocardiograma de repouso.","B":"Teste de esforço com tálio.","C":"Bloqueador beta-adrenérgico.","D":"Teste ergométrico.","E":"Ácido acetilsalicílico."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-163898","number":"163898","sourceNumber":"163898","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A hemofilia A e B são coagulopatias em que há deficiência dos fatores e\n\n, sendo a manifestação mais frequente . Marque a alternativa que\ncontém os dados que preenchem corretamente as lacunas na afirmação acima:","options":{"A":"VII e VIII, epistaxe.","B":"VII e IX, hemartroses.","C":"VIII e IX, hemartroses.","D":"VII e VIII, hematoma muscular."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-129533","number":"129533","sourceNumber":"129533","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Criança de 6 anos, previamente hígida, é levada ao pronto socorro com história de\naparecimento súbito e espontâneo de algumas equimoses no corpo, sem relato de sangramento\nem mucosas. Duas semanas antes havia apresentado quadro gripal. Ao exame clínico não foi\nobservada linfadenomegalia ou hepatoesplenomegalia. Realizado hemograma, com o resultado a\nseguir: Hemácias 4,1 milhões/mm3; Hemoglobina 12,4 g/dL; Hematócrito 37 %; Leucócitos 6.900\n\n/mm3; Segmentados 54,4 %; Linfócitos 32,1 %; Monócitos 10,5 %; Eosinófilos 2,7 %; Basófilos 0,3\n\n%; Plaquetas 20.000 /mm3. Assinale a conduta mais apropriada para esse paciente:","options":{"A":"Iniciar tratamento com metilprednisolona intravenosa.","B":"Transfusão imediata de concentrado de plaquetas.","C":"Administração de imunoglobulina intravenosa.","D":"Acompanhamento ambulatorial; orientar limitação das atividades físicas."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-135612","number":"135612","sourceNumber":"135612","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação a Síndrome Hemolítica Urêmica , marque a alternativa incorreta.","options":{"A":"É caracterizada por anemia hemolóitica microangiopática, trombocitopenia e insuficiência\nrenal aguda.","B":"Incide principalmente em crianças maiores de 5 anos.","C":"Hipertensão arterial a as manifestações do sistema nervoso central são freqüentes.","D":"O tratamento tem como objetivos: Corrigir distúrbios hidroeletrolíticos e ácido-básicos,\nhipertensão, uremia, anemia e manifestações extrarrenais que possam ocorrer."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-103776","number":"103776","sourceNumber":"103776","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Marque a alternativa CORRETA:","options":{"A":"Nos processos de urticária/angioedema há grande envolvimento de linfócitos e monócitos.","B":"A maioria das tromboembolias pulmonares é produzida por êmbolos provenientes de trombose\nvenosa profunda de membros inferiores, veias\npélvicas, renais, e de átrio e ventrículo direitos.\nRaramente pode haver embolia a partir de trombose de veias superficiais e dos membros\nsuperiores.","C":"Maior gravidade e incidência de infecções, maior risco de certos tipos de câncer e menor\nresposta a vacinas não se correlacionam,\ncomo se imaginava, com a imunossenescência, conforme\nachados de estudos atuais.","D":"A manobra de Rivero-Carvallo (relacionado à inspiração profunda) reforça o sopro das\ninsuficiências Tricúspide e Mitral."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-105976","number":"105976","sourceNumber":"105976","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Qual das doenças trombofílicas abaixo é a causa mais comum de TVP nos pacientes a\nserem submetidos a cirurgia:","options":{"A":"Fator V de Leiden","B":"Deficiência de proteína C e S","C":"Deficiência de antitrombina","D":"Síndrome do Anticorpo antifosfolípide"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-108012","number":"108012","sourceNumber":"108012","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Anticoagulante oral como warfarina, normalmente é:","options":{"A":"rapidamente absorvida, com picos sérico de 1 hora.","B":"quase totalmente conjugada a albumina.","C":"fator de risco para sangramento digestivo em idosos.","D":"bem absorvida independente da dieta.","E":"principal antagonista da vitamina K."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-103070","number":"103070","sourceNumber":"103070","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 54 anos em anticoagulação com cumarínico há 3 meses, devido à\ntrombose venosa profunda, cursou com\nsangramento genital intenso, procurando atendimento\nmédico. Avaliada pelo plantonista, que encontrou a paciente pálida, com frequência cardíaca de\n120bpm e hipotensão de 80 x 40mmHg. Exames laboratoriais mostravam hemoglobina: 8,2mg/dL;\nRNI: > 10. Portadora de hipertensão arterial e miomatose uterina. Após prescrição de hidratação\nvenosa com 2000ml de cristaloide, a paciente evoluiu com melhora da pressão arterial para 110 x\n70mmHg, frequência cardíaca caiu para 100bpm e apareceram crepitações em bases pulmonares\nbilateralmente. A paciente ainda mantinha quadro de sangramento ativo. Considerando o caso\nclínico descrito, assinale a alternativa MAIS adequada para o controle do sangramento.","options":{"A":"Administrar vitamina K intravenosa de 12/12 horas.","B":"Transfundir plasma fresco congelado na dose de 15ml/kg de peso.","C":"Administrar complexo protrombínico na dose de 25UI/kg.","D":"Realizar histerectomia de urgência para tratamento da miomatose uterina."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-105981","number":"105981","sourceNumber":"105981","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Mulher jovem procura ambulatório de clínica médica com quadro de cefaléia parietal\nunilateral pulsátil com fotofobia e náuseas\nassociadas. Nega comorbidades. História familiar\nrevelando pai portador de HAS e dislipidemia. Relata ser ansiosa e sedentária. Nega\ntabagismo e etilismo. Menarca aos 12 anos com ritmo menstrual regular no momento. Está\ntentando engravidar novamente e está angustiada por já ter abortado espontaneamente três vezes,\nsempre no primeiro trimestre de gestação. Ao exame físico: RCR 2T sem sopros. PA: 110 x 80\nmmHg, MVUA sem ruídos adventícios, pupilas iscocóricas e fotorreagentes. Exames\ncomplementares revelando positividade de anticardiolipina IgM e IgG. Qual medicamento\ndeveria ser iniciado para tal paciente já que ela deseja engravidar?","options":{"A":"Warfarim","B":"Ácido acetilsalicílico","C":"Heparina não fracionada","D":"Prednisona"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-103042","number":"103042","sourceNumber":"103042","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Menina de 3 anos, 14 kg, é levada à consulta por apresentar, subitamente, sufusões\nhemorrágicas pelo corpo. Ao exame físico, apresentava bom estado geral e encontrava-se ativa,\nafebril e normocorada. Além de petéquias e equimoses disseminadas, foi palpado o baço a 3 cm da\nreborda costal esquerda, linha hemiclavicular. Foram solicitados exames, que mostraram: HB =\n11,5 g%, com VCM e HCM normais; leucócitos de 9.110/mm³, com 30% de segmentados, 5% de\neosinófilos, 4% de monócitos e 615 de linfócitos. Plaquetas de 10.000/mm³. A partir desses dados,\né CORRETO afirmar que:","options":{"A":"Deve-se realizar uma transfusão de duas unidades de plaquetas, ou seja: 1 unidade para cada 7\nkg.","B":"Deve-se solicitar um mielograma, pois a possibilidade de uma leucemia\né muito grande.","C":"Se esse quadro de sufusões hemorrágicas e trombocitopenia se mantiver por mais de três\nmeses, apesar da terapêutica instituída, está indicada uma esplenectomia.","D":"Em caso de sangramento de mucosas, pode-se fazer uso de corticoides e imunoglobulina."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109966","number":"109966","sourceNumber":"109966","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Portaria Nº 2.712, de 12 de Novembro de 2013, redefine o regulamento técnico de\nprocedimentos hemoterápicos. De acordo com o Art. 130: É obrigatória a realização de exames\nlaboratoriais de alta sensibilidade a cada doação, para detecção de marcadores para as seguintes\ninfecções transmissíveis pelo sangue:","options":{"A":"Hepatite A; hepatite B; hepatite C; AIDS; doença de Chagas; e citomegalovírus.","B":"Sífilis; doença de Chagas; hepatite B; hepatite C; AIDS; e HTLV I/II.","C":"Toxoplasmose; blastomicose; hepatite B; hepatite C; AIDS; e doença de Chagas.","D":"Hepatite B; hepatite C; AIDS; sífilis; doença de Chagas; e malária."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-120705","number":"120705","sourceNumber":"120705","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 62 anos, gênero masculino, sem queixas, realizou exames pré-operatórios,\ndentre eles Tempo de Tromboplastina Parcial\nativado (TTPa) e Tempo de Protrombina (TP). O\nresultado foi TTPa (relação paciente/teste) = 1,5 e TP (atividade) = 90%. Responda a alternativa\nCORRETA em relação à conduta deste paciente:","options":{"A":"Os exames estão normais, portanto o paciente pode ser liberado para o procedimento cirúrgico.","B":"O TTPa está alterado, sendo necessário\ninvestigar hepatopatia neste paciente.","C":"O TP está alterado, sendo necessário investigar\nhepatopatia neste paciente.","D":"O TTPa está alterado, sendo necessário investigar hemofilia neste paciente.","E":"O TTPa e o TP estão alterados, sendo\nnecessário investigar deficiência de fator V."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-80753","number":"80753","sourceNumber":"80753","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Laura, quatro anos, apresentou há um mês otite média aguda, tratada com Amoxicilina,\ntendo remissão do quadro. Permaneceu\nassimtomática até três dias atrás, quando foi trazida com\nhistória de hematomas espontâneos nas extremidades e no tronco, sem outros sangramentos. Ao\nexame - bom estado geral, afebril, corada, ausência de linfadenomegalia e/ou\nhepatoesplenomegalia. Hematomas múltiplos, pequenas áreas equimóticas e muitas lesões\npetequiais sobre as extremidades e tronco. Qual o diagnóstico CORRETO?","options":{"A":"Trombocitopenia amegacariocítica","B":"Púrpura trombótica trombocitopênica","C":"Trombocitopenia de Glanzmann","D":"Púrpura trombocitopenica idiopática","E":"Púrpura anafilactóide"},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-80757","number":"80757","sourceNumber":"80757","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Laura, quatro anos, apresentou há um mês otite média aguda, tratada com amoxicilina,\ntendo remissão do quadro. Permaneceu assintomática\naté três dias atrás, quando foi trazida com\nhistória de hematomas espontâneos nas extremidades e no tronco, sem outros sangramentos. Ao\nexame: bom estado geral, afebril, corada, com ausência de linfadenomegalia e/ou\nhepatoesplenomegalia. Hematomas múltiplos, pequenas áreas equimóticas e muitas lesões\npetequiais sobre as extremidades e tronco. Para diagnóstico, neste caso, é necessário a\ndemonstração de:","options":{"A":"Tempo de protrombina normal, tempo parcial de tromboplastina normal e número de plaquetas\nnormal.","B":"Tempo de protrombina alterado, tempo parcial de tromboplastina normal e número de plaquetas\nnormal.","C":"Tempo de protrombina alterado, tempo parcial de tromboplastina alterado e número de\nplaquetas normal.","D":"Tempo de protrombina normal, tempo parcial de tromboplastina normal e número de plaquetas\ndiminuído.","E":"Tempo de protrombina alterado, tempo parcial de tromboplastina alterado e número de\nplaquetas diminuído."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-80759","number":"80759","sourceNumber":"80759","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Laura, quatro anos, apresentou há um mês otite média aguda, tratada com Amoxicilina,\ntendo remissão do quadro. Permaneceu\nassintomática até três dias atrás, quando foi trazida com\nhistória de hematomas espontâneos nas extremidades e no tronco, sem outros sangramentos. Ao\nexame - bom estado geral, afebril, corada, ausência de linfadenomegalia e/ou\nhepatoesplenomegalia. Hematomas múltiplos, pequenas áreas equimóticas e muitas lesões\npetequiais sobre as extremidades e tronco. Qual a complicação mais grave que pode ocorrer no\ninício da evolução da doença?","options":{"A":"Hemorragia intracraniana","B":"Hemorragia gastrointestinal","C":"Hemorragia pulmonar","D":"Trombose de veia renal","E":"Trombose de membros inferiores"},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-58940","number":"58940","sourceNumber":"58940","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A síntese de protrombina pode ser impedida por falta de:","options":{"A":"Vitamina B12.","B":"Fator intrínseco.","C":"Vitamina D.","D":"Vitamina K."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-60806","number":"60806","sourceNumber":"60806","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Marque a alternativa CORRETA:","options":{"A":"S. pneumoniae e H. influenzae estão entre os patógenos mais comumente causadores de\npneumonia adquirida na comunidade e em\npacientes internados (ambiente hospitalar), mas não em\npacientes em UTIs (Tratamento Intensivo).","B":"As heparinas de baixo peso molecular têm meia-vida curta e ação completamente reversível\ncom protamina.","C":"Em um estudo espirométrico, o achado de VEF1/CVF% reduzido e VEF1% reduzido sugerem\ndistúrbio ventilatório restritivo.","D":"A cólica renal tipicamente é de forte intensidade e associada à náusea, vômito e hematúria.\n\nQuando o cálculo atinge a junção ureterovesical pode mimetizar quadro de infecção urinária, com\ndisúria e polaciúria."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-58976","number":"58976","sourceNumber":"58976","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 24 anos, sexo feminino, procurou a unidade de pronto atendimento por\nepistaxe leve iniciada após desentendimento\ncom o marido (não houve agressão física). Na UPA foi\nidentificada plaquetopenia (24.000) e a paciente encaminhada para internação. No hospital, a\nanamnese revelou uma jovem sem comorbidades ou uso de medicamentos; sem história de\nsangramento prévio e sem queixas recentes antecedendo o episódio de epistaxe. Foram solicitadas\nsorologias para hepatites B e C, anti-HIV, FAN: todos negativos; além de TSH: normal. O esfregaço\ndo sangue periférico era normal. Confirmou-se a plaquetopenia (24.500) após a contagem manual\ndas plaquetas. Sobre o caso acima, marque a alternativa CORRETA:","options":{"A":"Trata-se provavelmente de púrpura trombocitopênica imunológica, porém esse diagnóstico é de\nexclusão, o que torna o mielograma necessário.","B":"A púrpura trombocitopênica trombótica é um diagnóstico alternativo a ser considerado pela idade\nda paciente e pela manifestação hemorrágica.","C":"O tratamento inicial é a transfusão de plaquetas associada à pulsoterapia com metilprednisolona\npor três dias consecutivos.","D":"Na ausência de resposta à corticoterapia, pode-se considerar a esplenectomia como opção\nterapêutica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-58999","number":"58999","sourceNumber":"58999","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Criança de três anos de idade, previamente hígida, é levada a uma consulta por ter\niniciado há 24 horas surgimento de petéquias e equimoses no tronco, abdome e membros\ninferiores. Passado de infecção vias aéreas superiores há 14 dias. Exame físico normal,\nexcetuando pela presença de petéquias e equimoses. Hemograma realizado revelou: Hb 12 g/dl\nHtc 36% G. Leucócitos 8300 neutrof seg 48% linf 50% mon 2% plaquetas 5000. A hipótese\ndiagnóstica mais provável seria:","options":{"A":"Leucemia.","B":"Púrpura de Henoch-Schönlein.","C":"Púrpura trombocitopênica autoimune.","D":"Riquetisiose."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-44550","number":"44550","sourceNumber":"44550","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 53 anos, previamente hígido, procura um médico devido a aparecimento\nsúbito de equimoses espontâneas em tronco e\nmembros superiores. Em seu exame físico, não\nhavia nenhuma outra alteração. Seus exames complementares evidenciaram apenas\nplaquetopenia (7.000). Qual a hipótese diagnóstica mais provável para o caso em questão?","options":{"A":"Anemia Falciforme.","B":"Leucemia Mieloide Aguda.","C":"Púrpura Trombocitopênica Idiopática.","D":"Linfoma de Hodgkin."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-44554","number":"44554","sourceNumber":"44554","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 53 anos, previamente hígido, procura um médico devido a aparecimento\nsúbito de equimoses espontâneas em tronco e\nmembros superiores. Em seu exame físico, não\nhavia nenhuma outra alteração. Seus exames complementares evidenciaram apenas\nplaquetopenia (7.000). Qual dos exames abaixo poderia contribuir para o diagnóstico do caso\nacima?","options":{"A":"Coombs Direto.","B":"Pesquisa de cromossomo philadelfia.","C":"Ultrassom de abdome.","D":"Biópsia de Medula Óssea."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-44310","number":"44310","sourceNumber":"44310","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A Púrpura Trombocitopênica Idiopática ? PTI é o distúrbio hemorrágico adquirido mais\nfrequente na faixa etária pediátrica. É CORRETO afirmar que:","options":{"A":"Hemorragia grave de sistema nervoso central é frequente, daí a necessidade de sempre se\ninternar a criança.","B":"Geralmente o baço é palpável em 100% dos casos.","C":"É comum o relato de doença viral recente e pode estar relacionado à vacinação prévia em\nlactentes abaixo de 2 anos.","D":"Além da plaquetopenia, o exame laboratorial apresenta leucocitose e anemia, independente de\nter ocorrido sangramento."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-19123","number":"19123","sourceNumber":"19123","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"São causas de hipopotassemia por desvio do potássio intracelular, EXCETO:","options":{"A":"alcalose metabólica.","B":"hiperplasia congênita de suprarrenal.","C":"uso de beta-2 adrenérgicos.","D":"uso de insulina."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-19124","number":"19124","sourceNumber":"19124","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à alcalose metabólica, assinale a afirmativa INCORRETA.","options":{"A":"A clínica se manifesta por desidratação e hipotensão, bem como por sinais de sintomas\nassociados a hipopotassemia e a hipocalcemia","B":"Entre as causas, podem-se citar o aporte excessivo de bicarbonato, Síndrome de Batter,\nexsanguíneotransfusão e diuréticos.","C":"O objetivo do tratamento é corrigir a causa.","D":"O tratamento é feito quase que em sua totalidade com diuréticos inibidores da anidrase\ncarbônica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-318548","number":"318548","sourceNumber":"318548","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem com 48 anos de idade, tabagista, em tratamento irregular de hipertensão\narterial sistêmica, diabetes mellitus e\ndislipidemia, é admitido na unidade de emergência de hospital\nde pequeno município do interior, com quadro de dor torácica de forte intensidade, tipicamente\nanginosa, associada a diaforese, náuseas e vômitos. Segundo informa, o quadro álgico tem cerca\nde 4 horas de evolução, não tendo procurado antes a unidade de saúde por receio de\ncontaminação devido à pandemia em curso. O exame físico dirigido revela um paciente em\nmoderado desconforto agudo, ansioso, com Pressão Arterial (PA) de 102 x 70 mmHg, frequência\ncardíaca de 102 batimentos por minuto, levemente taquipneico, frequência respiratória de 22\nincursões respiratórias por minuto. Na ausculta cardíaca, revelam-se uma 4ª bulha e um sopro\nsistólico suave na ponta, estando os pulmões limpos. É realizado, então, um Eletrocardiograma\n(ECG) nos primeiros 10 minutos de atendimento, que mostra a presença de um supradesnível do\nsegmento ST superior a 2 mm nas derivações D2, D3, aVF e V1, além de infradesnível de ST de 3\nmm nas derivações V2 a V4, nas quais são observadas ondas R aumentadas e ondas T positivas\nproeminentes. São administrados nitrato sublingual e Ácido Acetilsalicílico (AAS), além de ser\nsolicitada a infusão de tenecteplase intravenosa em bolus, uma vez que não há serviço de\nhemodinâmica na região. Enquanto é providenciada a elaboração do trombolítico, o paciente refere\npiora dos sintomas, sendo verificado que ele se encontra ainda mais pálido e hipotenso (PA: 80 x\n46 mmHg), a despeito de sua ausculta pulmonar manter-se sem ruídos adventícios. Considerando\nos dados relatados, a melhor explicação para a piora clínica do paciente logo após a instituição da\nabordagem inicial é:","options":{"A":"Agravamento da hipercalemia pelo AAS.","B":"Desenvolvimento de rotura de septo interventricular.","C":"Medicação inadequada na coexistência de infarto de ventrículo direito.","D":"Instalação de choque cardiogênico por grave disfunção ventricular esquerda."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-352605","number":"352605","sourceNumber":"352605","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Jurandir, 54 anos, vem à consulta após ter sofrido um infarto há 2 meses. Ficou\nhospitalizado uma semana e recebeu alta.\nTrouxe o ecocardiograma que realizou antes da alta\nhospitalar. Relata estar usando apenas o AAS e o clopidogrel após o almoço. Os outros remédios,\nsuspendeu após um mês e perdeu o receituário. Referia dispneia aos grandes esforços, negava dor\ntorácica ou dispneia paroxística noturna. Ao exame físico, estava normocorado e eupneico.\n\nAusculta cardiopulmonar sem alterações e sem edema de MMII. PA:142x85mmHg nos 2 braços,\nFC:88bpm, FR:14irpm, Sat:98% em AA. Ecocardiograma: hipocinesia segmentar de ventrículo\nesquerdo. FE:52%. Qual a conduta mais adequada para Jurandir?","options":{"A":"Manter o AAS até finalização dos exames.","B":"Associar Rosuvastatina, Carvedilol e enalapril.","C":"Associar Rosuvastatina e avaliar a pressão em nova consulta.","D":"Caso tenha colocado Stent, associar sinvastina ao AAS e clopidogrel."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-331150","number":"331150","sourceNumber":"331150","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente feminino de 35 anos, internada para cirurgia plástica, apresenta dor torácica e\npontada em região precordial. Paciente faz uso de anticoncepcional oral há 5 anos. Nega outras\ncomorbidades. Exame físico inalterado. ECG sem alterações. Troponina I com resultado de\n0,09ng/mL (VR < 0,04ng/mL). A conduta mais apropriada no momento é","options":{"A":"considerar o resultado um falso positivo e observar.","B":"seguir seriando marcadores de necrose miocárdica para definição de conduta definitiva.","C":"proceder à anticoagulação, à antiagregação e ao cateterismo em 48 horas.","D":"proceder à estabilização clínica e ao teste de esforço assim que possível.","E":"proceder à anticoagulação e à angiotomografia."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-311481","number":"311481","sourceNumber":"311481","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A dor torácica é uma causa frequente de encaminhamento de crianças e adolescentes\npara o cardiologista pediátrico, embora\nraramente esteja relacionada a problemas cardíacos nessa\nfaixa etária, gera extrema preocupação dos pais, levando o pediatra muitas vezes a encaminhar o\npaciente ao especialista. Ante o exposto, analise as afirmativas abaixo. I. A dor idiopática\napresenta\ngeralmente uma evolução crônica. Os pacientes com costocondrite manifestam dor relacionada à\natividade física prévia ou infecção respiratória. Pode ser de leve a moderada intensidade,\ngeralmente unilateral, que piora com a movimentação e a respiração; II. A dor musculoesquelética\nocorre geralmente por contusão na musculatura do dorso, peitoral e ombro após exercício ou\ntrauma e está relacionada com a prática de esportes, lutas ou acidentes; III. A dor psicogênica é\nmais comum em adolescentes e frequentemente desencadeada por uma situação de estresse,\ncomo morte ou separação na família, fracasso escolar ou abuso sexual; IV. A dor do tipo anginosa\nocorre em aperto, desencadeada por execício, emoção, frio, excesso alimentar localizada no\nprecórdio ou na área subesternal com irradiação para o pescoço mandíbula, braços, dorso ou\nabdome; V. Dor anginosa com exame cardiológico anormal (exame físico, Rx de tórax ou ECG);\nHistória familiar de miocardiopatia hipertrófica, síndrome do QT longo ou outra doença cardíaca\nhereditária. Além de família muito ansiosa em paciente com dor crônica e recorrente, são\nindicações de encaminhamento ao cardiologista pediátrico; A alternativa que contém todas as\nafirmativas corretas é:","options":{"A":"I","B":"V","C":"II e IV","D":"I, III e V","E":"I, II, III, IV e V"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-269750","number":"269750","sourceNumber":"269750","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Uma mulher com 50 anos de idade, antecedente de asma brônquica grave e\ntuberculose em tratamento há 8 meses, chega\npara atendimento no Pronto-Socorro com queixa de\nfalta de ar de longa data. Ao exame físico, a paciente apresenta bom estado geral, corada,\nhidratada, frequência cardíaca de 88 bpm, pressão arterial de 130x70mmHg e saturação de O? de\n90%. Ela apresenta B2 hiperfonética e um sopro diastólico no 3º espaço intercostal esquerdo, que\naumenta com a inspiração. O nome dado a este sopro é:","options":{"A":"Carey Coombs","B":"De Miguel Couto","C":"Austin Flint","D":"Gallavardin","E":"Graham Steell"},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-269759","number":"269759","sourceNumber":"269759","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à síndrome coronariana aguda, é CORRETO afirmar que:","options":{"A":"Quando a obstrução da luz coronária é parcial, mas grave suficiente para levar à morte de\ncardiomiócitos por isquemia miocárdica e elevação de marcadores de necrose miocárdica a\ncondição é chamada de infarto agudo do miocárdio com supra desnivelamento de segmento ST.","B":"O Eletrocardiograma (ECG) pode não apresentar qualquer alteração em 50% dos casos de\nsíndrome coronariana aguda sem supra desnivelamento do segmento ST.","C":"Os marcadores de necrose miocárdica de eleição nos dias de hoje são a CPK, a CK-MB e a\nTroponina, sendo a CPK a mais específica para o músculo cardíaco, podendo dar o diagnóstico de\ninfarto quando analisada isoladamente.","D":"A alteração mais precoce que ocorre no eletrocardiograma de um paciente com síndrome\ncoronariana aguda com elevação do segmento ST é o aparecimento de onda Q patológica.","E":"A Intervenção Coronariana Percutânea (ICP) facilitada é aquela realizada em até 180 minutos\napós o fibrinolítico e constitui-se na melhor opção para obtenção da reperfusão coronariana."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-276688","number":"276688","sourceNumber":"276688","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, hipertenso e diabético, dá entrada na sala de\nemergência referindo dor precordial de forte intensidade há aproximadamente 3 horas, sem\nirradiação, associado a náuseas e vômitos; ao exame encontra-se gemente, orientado, diaforético,\njugulares túrgidas, SpO2 de 96%, PA 109x71 mmHg e afebril. O ECG de 12 derivações mostra\ndiscreto infradesnivelamento nas derivações DIII, AVF, AVR e V1. Assinale dentre as alternativas\nabaixo a que descreve a abordagem correta para o caso.","options":{"A":"Iniciar dupla antiagregação plaquetária (AAS + clopidogrel), hidratação com salina isotônica,\nheparinização plena e início precoce de estatinas.","B":"Iniciar dupla antiagregação plaquetária (AAS + clopidogrel), morfina e nitrato sublingual.","C":"Iniciar dupla antiagregação plaquetária (AAS + clopidogrel), morfina e nitrato sublingual e\nsubmeter o paciente à cineangiocoronariografia de urgência, pois em pacientes diabéticos os\nquadros de infarto possuem risco elevado para complicações.","D":"Iniciar antiagregação plaquetária somente com AAS na primeira abordagem, devido risco de\nsangramento durante cineangiocoronariografia após uso de clopidogrel.","E":"Iniciar dupla antiagregação plaquetária (AAS + clopidogrel) e anticoagulação com enoxaparina,\nassociar morfina e nitrato sublingual."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-269778","number":"269778","sourceNumber":"269778","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre doença aterosclerótica, é correto afirmar que:","options":{"A":"os aneurismas que ocorrem como consequência da aterosclerose formam-se mais\nfrequentemente na aorta torácica e nas artérias ilíacas comuns.","B":"as placas ateroscleróticas estáveis tendem a ter cápsulas fibrosas densas, acúmulo mínimo de\nlipídios e pouca inflamação podendo produzir sintomas relacionados com a isquemia crônica pelo\nestreitamento da luz vascular.","C":"as alterações agudas das placas ateroscleróticas são ruptura / fissura, erosão/ ulceração e\nhemorragia podendo causar complicações isquêmicas crônicas como a angina estável.","D":"em ordem decrescente os vasos mais amplamente envolvidos pela aterosclerose são as artérias\ncoronárias, as artérias carótidas internas, os vasos do polígono de Willis, a aorta abdominal\ninferior\ne as artérias poplíteas.","E":"a isquemia miocárdica leva a perda de função dentro de 10 minutos, mas causa necrose\nsomente após 2 horas."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-269797","number":"269797","sourceNumber":"269797","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um paciente de 54 anos, com antecedente de cirurgia de revascularização miocárdica\nhá 1 ano, hipertenso e dislipidêmico,\nprocura atendimento no pronto-socorro em decorrência de\ncansaço, falta de ar e edema em membros inferiores. Ao exame físico, apresenta pressão arterial\nde 120/72mmHg, frequência cardíaca de 64bpm, turgescência jugular de 8cm que aumenta com a\ninspiração seguida por descenso rápido, pulmões limpos, bulhas cardíacas hipofonéticas e sem\nsopros, edema de tornozelos +/3+ com Sinal de Cacifo positivo. O diagnóstico mais provável do\npaciente é:","options":{"A":"Insuficiência cardíaca biventricular.","B":"Endocardite de Libman-Sacks.","C":"Síndrome da veia cava superior.","D":"Estenose dos enxertos coronarianos.","E":"Pericardite constritiva."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-230901","number":"230901","sourceNumber":"230901","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 62 anos admitido no pronto socorro com história de há 3 horas evoluindo\ncom dor torácica de forte intensidade seguida\nde torpor. Ao exame físico: Mal estado geral com\nGlasgow 12 e extremidades frias e pegajosas. Frequência cardíaca de 36 btm/min. PA:\n70x30mmHg. Ausculta pulmonar: MV+ bilateralmente, com crepitações bibasais com frequência\nrespiratória de 25iRPM. Abdome: inocente. ECG realizado na urgência mostra o seguinte traçado.\nEsse ECG indica um:","options":{"A":"infarto agudo do miocárdio, com supra de ST, com indicação de cateterismo de urgência.","B":"bloqueio átrio ventricular total, com indicação de implantação de marcapasso transcutânea.","C":"infarto agudo do miocárdio, sem supra de ST, com indicação de dupla agregação e CATE\neletivo.","D":"bloqueio átrio ventricular, MOBITZ II, secundário a infarto agudo do miocárdio, indicado fazer\natropina."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-254744","number":"254744","sourceNumber":"254744","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo feminino, 55 anos, diabética, apresentou episódio de síncope\nacompanhada de diaforese enquanto andava do\nquarto para a sala em casa. Ao exame físico,\nencontra-se em regular estado geral, Glasgow 14, apenas desorientada, PA 100 x 60 em ambos os\nbraços. Pulsos finos, mas simétricos. AC: bulhas cardíacas normofonéticas, sem sopros ou\ndesdobramentos. FC: 65 bpm. AP: murmúrio vesicular presente, sem ruídos adventícios. Glicemia\ncapilar de 210. O ECG do atendimento encontra-se a seguir: Esta paciente deve:","options":{"A":"Ser liberada para casa para investigação ambulatorial.","B":"Ser submetida a teste de esforço cardíaco na urgência.","C":"Coletar troponina para investigar IAM sem supra de ST.","D":"Ter um marca-passo transvenoso implantado imediatamente.","E":"Ser encaminhada imediatamente para cateterismo devido a IAM com supra de ST."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-254747","number":"254747","sourceNumber":"254747","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente, 42 anos, professora de educação física, comparece à consulta devido a\nedema assimétrico de membros inferiores, que\nnotou há 2 dias. Inicialmente achou tratar-se de um\ntrauma ocorrido durante uma aula, mas o edema e a dor aumentaram. Nega internações ou\ntratamento médico recentes, uso de anticoncepcionais ou outros medicamentos, doenças crônicas\nou febre recente, bem como viagens. Ao exame físico, apresenta IMC 23, ausculta cardiopulmonar\nnormal. PA:125x80. FC:90bpm. FR:20irpm. Edema em MID, panturrilha endurecida e dolorosa à\npalpação. Cacifo+. MID mais quente que o esquerdo. Pulsos presentes e simétricos. Sem\nalterações significativas na pele. MIE sem edemas. Diante deste quadro, é correto afirmar:","options":{"A":"Trata-se de quadro com probabilidade intermediária para TVP, devendo ser solicitado D-dímero.","B":"Trata-se de quadro com baixa probabilidade para TVP, devendo ser solicitado doppler.","C":"O quadro é sugestivo de trombose arterial, devendo ser solicitado o doppler.","D":"O único fator de risco adquirido apresentado foi o trauma.","E":"Descarta-se TVP, pois não há nenhum fator de risco."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-215918","number":"215918","sourceNumber":"215918","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"A aterosclerose caracteriza-se pele presença de lesões da íntima das artérias de médio\ne grande calibre e as lesões são chamadas de\nateromas ou placas ateroscleróticas. Sobre a\naterosclerose e suas consequências, é correto afirmar que:","options":{"A":"o estilo de vida tem uma influência fundamental na patogênese da aterosclerose, e essa\ninfluência é determinada em conjunto por genes de ocorrência populacional cujos efeitos não\npodem ser minimizados pela mudança do estilo de vida.","B":"dentre os componentes da placa de ateroma, macrófagos de fenótipo M2 são uma das\nprincipais subpopulações de células presentes na lesão.","C":"placas de ateromas com necrose e calcificação apresentam alterações definidas como esclerose\nmedial de Monckeberg.","D":"níveis elevados de homocisteína causadas pelo baixo consumo de folatos e vitaminas B12,\npossuem forte relação com doenças das\nartérias coronárias e é um dos fatores de risco associados\na doença cardíaca isquêmica e aterosclerose.","E":"a lesão endotelial relacionada a patogênese da aterosclerose está relacionada primariamente a\nfatores que levam às consequências graves desta doença, tais como a trombose e embolia."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-181956","number":"181956","sourceNumber":"181956","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 70 anos, hipertenso de longa data,em tratamento irregular, dá entrada no\nPS com dor aguda de forte intensidade em\nregião anterior do tórax irradiando para região dorsal\nacompanhado de dispneia. Relata que a dor iniciou já de forte intensidade, ao exame PA 177 X 90\nmmHg ,FC 102 BPM e ECG mostrou com padrão de sobrecarga das câmaras esquerdas. A\nconduta inicial a ser tomada é:","options":{"A":"iniciar bloqueador de canais de cálcio SL para reduzir a PA.","B":"após ECG ,fazer TC de Tórax para descartar tamponamento cardíaco.","C":"diurético tiazídico +betabloqueador.","D":"trombolítico se tiver menos de 12 h de dor.","E":"nitroprussiato de sódio + Metoprolol."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-159922","number":"159922","sourceNumber":"159922","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Quanto ao risco equivalente da doença coronariana, NÃO se pode considerar:","options":{"A":"Doença cerebrovascular.","B":"Diabete mellitus.","C":"Insuficiencia venosa.","D":"Estenose de carótida.","E":"Aneurisma de aorta abdominal."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-159879","number":"159879","sourceNumber":"159879","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente sexo feminino, 33 anos, previamente hígida, dá entrada no setor de urgência e\nemergência vitima de acidente automobilístico de grande impacto. Apresenta trauma torácico,\nabdominal e fraturas de ossos longos. Evolui com quadro de hipotensão grave, turgência jugular e\npulso paradoxal. Ausculta pulmonar com murmúrio vesicular reduzido no 1/3 inferior esquerdo.\n\nConsiderando o diagnóstico mais provável, a opção terapêutica de escolha seria:","options":{"A":"uso de agentes Inotrópicos","B":"transfusão de concentrados de hemácias","C":"Pericardiocentese","D":"Toracocentese","E":"Drenagem torácica"},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-156711","number":"156711","sourceNumber":"156711","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Com relação aos betabloqueadores (Bb) na cardiopatia isquêmica crônica, é\nCORRETO afirmar que:","options":{"A":"Devem ser evitados nos pacientes com disfunção ventricular.","B":"Podem ser utilizados com segurança nos pacientes com distúrbios de condução av.","C":"Doentes portadores de asma não apresentam restrição ao seu uso.","D":"A suspensão abrupta da droga em pacientes com uso crônico pode precipitar isquemia\nmiocárdica.","E":"Podem ser utilizados com segurança nos pacientes com doença vascular periférica."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-86506","number":"86506","sourceNumber":"86506","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Sobre a PTI (Púrpura Trombocitopênica Imunológica), é correto afirmar que:","options":{"A":"é uma doença de natureza autoimune caracterizada pela redução na contagem de plaquetas.\n\nAlém disso, o hemograma costuma mostrar importantes alterações nas séries vermelhas e\nleucocitárias, assim como baixo valor de PDW.","B":"esplenectomia deve ser considerada como medida terapêutica de primeira linha na maioria dos\ncasos, porque as complicações com o uso de esteroides são maiores que a remoção do baço.","C":"no exame físico dos pacientes, geralmente observa-se púrpura, esplenomegalia e\nlinfonodomegalia. Sangramento espontâneo ocorre frequentemente com plaquetas abaixo de\n50.000/mm³.","D":"na análise do esfregaço periférico, é frequente o encontro de macroplaquetas. No mielograma,\nnota-se número aumentado de megacariócitos, além\nde alterações frequentes nas outras linhagens\nhematopoiéticas.","E":"a PTI pode ser secundária a outras doenças, como Lúpus eritematoso sistêmico, doenças\nlinfoproliferativas, doenças autoimunes da tireoide, miastenia gravis, infecções pelo vírus da\nhepatite C."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-335247","number":"335247","sourceNumber":"335247","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação à Síndrome Coronariana Aguda (SCA), é correto afirmar:","options":{"A":"A terapia fibrinolítica é crucial para salvar vidas, tanto na síndrome coronariana aguda com\nsupradesnivelamento do segmento ST, quanto na SCA sem supra de ST.","B":"Cerca de um terço dos pacientes com IAM não têm dor no peito. Esses pacientes tendem a ser\nidosos, do sexo feminino, diabéticos e correm maior risco de morte subsequente.","C":"Paciente com dor torácica típica, mas com marcadores de necrose miocárdicas normais e sem\nsupradesnivelamento do segmento ST, exclui-se infarto agudo do miocárdio.","D":"O deslocamento dinâmico do segmento ST é a alteração eletrocardiográfica mais sensível para\na síndrome coronariana aguda.","E":"Se o nível de LDL- colesterol do paciente for baixo, não há recomendação de estatina na\nsíndrome coronariana aguda."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-326424","number":"326424","sourceNumber":"326424","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente do sexo masculino de 62 anos de idade, hipertenso e dislipidêmico, chega ao\nserviço de emergência do Hospital Nova Esperança com dor torácica; surgiu no repouso e já dura\nmais de 1 hora. A dor é retroesternal com irradiação para ambos os ombros. A dor é descrita como\npressão difusa, associada também a náusea e sudorese fria. Um fator de melhora da dor é se\nencolher em decúbito lateral esquerdo. Ao exame físico é observado a diaforese, frequência\ncardíaca de 105 bpm, pressão arterial 150x 88 mmHg. Com base na história do paciente, qual dado\ntem menos correlação com síndrome coronariana aguda?","options":{"A":"Sudorese.","B":"Náusea.","C":"Melhora com decúbito lateral esquerdo.","D":"Dor retroesternal e como pressão difusa.","E":"Irradiação para ambos os ombros."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-344835","number":"344835","sourceNumber":"344835","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Nos países industrializados, o infarto agudo do miocárdio (IAM) é um dos diagnósticos\nmais comuns em pacientes hospitalizados e a taxa\nde mortalidade em 1 ano após o IAM é de cerca\nde 15%. Dessa forma, é incorreto afirmar:","options":{"A":"Os níveis de troponinas podem continuar elevados por 7 a 10 dias após um IAM.","B":"O infarto do ventrículo direito (VD) acompanhado de insuficiência de VD pode clinicamente ser\nexpresso por distensão das veias jugulares, sinal de Kussmaul e hepatomegalia.","C":"O cateterismo das câmaras cardíacas direitas costuma revelar um padrão hemodinâmico distinto\nsemelhante à pericardite constritiva.","D":"Os nitratos são mais eficazes do que os diuréticos na redução da pré-carga por meio de\nvenodilatação, sem diminuir o volume plasmático total.","E":"A contagem de leucócitos aumenta mais lentamente do que a velocidade de\nhemossedimentação."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-326431","number":"326431","sourceNumber":"326431","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Um homem de 60 anos de idade chega ao ambulatório de cardiologia do Hospital Nova\nEsperança com queixa de dor torácica ao esforço moderado e dispneia leve quando sobe ladeiras.\nAo exame verificamos sopro messosistólico. Após ausculta cuidadosa temos certeza de trata-se de\nsopro estenose aórtica ou da forma obstrutiva de miocardiopatia hipertrófica. Qual manobra está\nadequadamente associada a achado clínico que sugere que esse sopro é devido à miocardiopatia\nhipertrófica obstrutiva, em oposição à estenose de valva aórtica?","options":{"A":"Manobra de preensão da mão ? diminuição da intensidade do sopro.","B":"Iniciar a administração venosa de milrinona ? aumento do sopro sistólico.","C":"Palpação de pulso carotídeo ? pulso carotídeo diminuído e tardio.","D":"Agachamento ? aumento da intensidade do sopro.","E":"Manobra de valsava ? aumento da intensidade do sopro."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-345590","number":"345590","sourceNumber":"345590","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente com dor torácica intensa é diagnosticado com dissecção aguda de aorta.\nSobre essa comorbidade, assinale a alternativa INCORRETA.","options":{"A":"Na classificação de Stanford tipo B, apenas a aorta descendente está acometida.","B":"Nas dissecções do tipo B, o tratamento cirúrgico emergencial é indicado para todos os casos.","C":"Pacientes que se apresentam com hipotensão devem ser pesquisados para tamponamento\ncardíaco ou hemotórax.","D":"Hipertensão arterial, aorta bicúspide e síndrome de Ehler-Danlos são condições predisponentes\nà dissecção.","E":"O ecocardiograma trans torácico é muito sensível e específico na dissecção do tipo A."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-264567","number":"264567","sourceNumber":"264567","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Para o acompanhamento do paciente hipertenso, a avaliação do risco cardiovascular é\nde fundamental importância para orientar a\nconduta terapêutica e o prognóstico de forma\npersonalizada. Para a estratificação do risco cardiovascular, é necessário pesquisar a presença dos\nfatores de risco, das doenças cardiovasculares e das lesões em órgão-alvo. A classificação do risco\ncardiovascular de cada pessoa deve ser avaliada pelo cálculo do escore de Framingham. Quanto a\neste escore, é correto afirmar:","options":{"A":"Considera-se um risco de 15% para a ocorrência de evento cardiovascular em 10 anos como\nbaixo risco.","B":"O cálculo do escore é o mesmo para homens e mulheres nas respectivas faixas etárias.","C":"A presença de tabagismo tem maior pontuação no sexo masculino.","D":"A dosagem de triglicerídeos acima de 300 mg/dL tem pontuação de 2 no escore para ambos os\nsexos.","E":"O cálculo do escore não é necessário se o usuário apresentar apenas um fator de risco\nbaixo/intermediário, por baixo risco de evento cardiovascular."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-240940","number":"240940","sourceNumber":"240940","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente de 50 anos, hipertenso, tabagista, diabético procura a unidade de pronto\natendimento da cidade de Campina Grande\ncom queixa de dor em epigástrio, em aperto, associado\na sudorese. No exame físico apresentava ritmo cardíaco regular, 2T, BNF e sem sopros. PA 130 x\n80 mmHg e saturação periférica de oxigênio de 91% em ar ambiente. O paciente refere que os\nsintomas iniciaram há aproximadamente 90 minutos. Na UPA tem tenecteplase. O único serviço\nque tem angioplastia é em João Pessoa e o tempo estimado de viagem é de 120 minutos, pois as\nestradas estão congestionadas. Não apresenta contraindicação a trombolíticos. Em relação ao\ncaso, marque a alternativa INCORRETA.","options":{"A":"Apresentações atípicas são mais comuns em mulheres, idosos e diabéticos.","B":"Caso a trombólise tenha sucesso, não é recomendada a transferência para coronariografia de\nrotina eletivamente nas primeiras horas após o atendimento.","C":"A terapia de reperfusão está indicada a todos os pacientes com história de dor torácica com até\n12 horas do início dos sintomas na presença de supra de ST persistente ou bloqueio de ramo\nesquerdo novo.","D":"O clopidogrel é o único dos inibidores P2Y12 estudado para uso durante a terapia fibrinolítica.","E":"Deve-se dosar o perfil lipídico na admissão dos pacientes, ou até nas primeiras 24 horas do\nevento agudo. Após esse período ocorrem\nalterações do perfil lipídico, aumento dos triglicerídeos e\nredução do LDL."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-208015","number":"208015","sourceNumber":"208015","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em relação às Síndromes Coronarianas Agudas (SCA), assinale a alternativa ERRADA:","options":{"A":"O ECG na avaliação dos pacientes é um \"divisor de águas\".","B":"O trombo associado à angina instável/infarto agudo do miocárdio sem supra de ST é vermelho e\ncomposto predominantemente de células sanguíneas, envolto em uma malha de fibrina, enquanto o\ntrombo nos pacientes com infarto agudo do miocárdio com supra de ST é branco e composto\nprincipalmente de plaquetas.","C":"A dor da SCA geralmente é retroesternal, irradiando-se, frequentemente, para ambos os lados\ndo tórax anterior, com predileção pelo lado esquerdo.","D":"O ECG está apto a nos auxiliar por demonstrar o tipo de lesão envolvida (trombo branco ou\nvermelho) e qual a artéria culpada.","E":"Os cinco principais mecanismos fisiopatológicos envolvidos nas SCA são: trombose, obstrução\nmecânica (placa aterosclerótica), obstrução dinâmica (espasmo), inflamação e aumento da\ndemanda miocárdica (angina secundária)."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-218144","number":"218144","sourceNumber":"218144","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente tabagista, sedentário e diabético de 60 anos de idade refere dor retrosternal\nde forte intensidade, súbita, acompanhada de\ndispneia, palidez e sudorese fria. O ECG evidenciou\nsupradesnivelamento do segmento ST em DII, DIII e AVF, associado a Bloqueio Atrioventricular\nTotal (BAVT). Na cineangiocoronariografia deste paciente foi encontrada oclusão de 100% de qual\nartéria?","options":{"A":"Primeira marginal.","B":"Artéria coronária direita.","C":"Artéria circunflexa.","D":"Artéria descendente anterior.","E":"Tronco da coronária esquerda."},"answer":"B","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-185321","number":"185321","sourceNumber":"185321","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Em adição ao uso de aspirina e estatina, qual das seguintes abordagens é considerada\nmais apropriada para uma mulher de 67 anos, com\npressão arterial de 155 x 90 mmHg e angina\nestável que evidencia no teste ergométrico alterações de repolarização inespecíficas e reversíveis\nem parede inferolateral?","options":{"A":"Cineangiocoronariografia.","B":"Angiotomografia coronariana.","C":"Cintilografia cardíaca de estresse anual.","D":"Associar clopidogrel.","E":"Iniciar betabloqueador."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-187650","number":"187650","sourceNumber":"187650","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Paciente feminina, 68 anos, diabética, refere angústia, opressão em região cervical e\nfraqueza em MMII há 2 horas. A admissão, apresenta-se lúcida, hipertensa (PA 150/80 mmHg),\ntaquicárdica, com pulsação visível no precordio. Rx de tórax sem alteração. Pulsos simétricos e\nnormais. O ECG ACIMA foi efetuando à admissão.","options":{"A":"Trata-se de paciente com quadro de taquicardia supraventricular com condução aberrante,\nestável, devendo receber adenosina Intravenosa.","B":"Trata-se de paciente com infarto agudo do miocárdio em evolução, de localização infero-lateral,\ncom indicação para trombólise.","C":"Trata-se de paciente com quadro de taquicardia supraventricular com condução aberrante,\ninstável, devendo ser cardiovertida.","D":"Trata-se de paciente com infarto agudo do miocárdio em evolução, de localização antero-lateral,\nextenso, com indicação para trombólise.","E":"Trata-se de paciente com dissecção de aorta Tipo II, devendo ser submetida à angiotomografia\ne intervenção endovascular."},"answer":"D","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-187680","number":"187680","sourceNumber":"187680","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 49 anos, obeso, portador de insuficiência cardíaca, hipertenso e\ndiabético,dislipidêmico, apresenta-se com dispneia,\ndor torácica opressiva em hemitórax esquerdo,\nirradiando-se para membro superior esquerdo. Está consciente, orientado, dispneico, PA = 150/100\nmmHg, FC 102 bpm, crepitando até o terço médio de ambos os pulmões. Enchimento capilar\nadequado. ECG normal. Qual a melhor abordagem terapêutica para este caso?","options":{"A":"AAS, Clopidogrel, Enoxaparina, Nitroglicerina IV, Furosemida.","B":"AAS, Betabloqueador, Enoxaparina, Dobutamina, Furosemida.","C":"AAS, Clopidogrel, Captopril, Furosemida.","D":"Clopidogrel, Nitroprussiato de sódio, Dobutamina.","E":"Furosemida isoladamente."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-161943","number":"161943","sourceNumber":"161943","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem de 64 anos, diabético, tabagista e hipertenso, admitido na emergência com\nquadro de precordialgia de forte\nintensidade com irradiação para dorso acompanhado de sudorese,\ntontura e vômitos. A dor iniciou há 50 minutos. Ao exame: agitação psicomotora, PA 180X90, PA no\nbraço direito: 120x80; FC: 110, ECG: supradesnivelamento em DII, DII e AVF, assinale a alternativa\nCORRETA:","options":{"A":"Administrados após IAM, os inibidores de enzima conversora da angiotensina (IECA) conferem\nredução de mortalidade apenas nos pacientes\ncom disfunção do ventrículo esquerdo.","B":"Em pacientes com taquicardia ventricular (TV) na fase aguda do IAM a lidocaína profilática deve\nser utilizada de rotina","C":"O uso de nitratos no curto e em longo prazo no IAM mostrou benefício na diminuição da\nmortalidade.","D":"A pericardite pós- IAM precoce deve ser tratada com corticoide afim de evitar aneurisma de\nventrículo esquerdo.","E":"Em pacientes com comprometimento significativo da função ventricular esquerda ou com\nalterações da condução AV, os antagonistas dos canais de cálcio devem ser evitados."},"answer":"E","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-134902","number":"134902","sourceNumber":"134902","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"NÃO é uma causa de trombose de repetição em pacientes jovens:","options":{"A":"Deficiência de proteína C.","B":"Anticorpo antifosfolípide.","C":"Deficiência de homocisteína.","D":"Deficiência de antitrombina III.","E":"Hemoglobinúria paroxística noturna (HPN)."},"answer":"C","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-23-109051","number":"109051","sourceNumber":"109051","collectionBlock":"med:med-clinica-medica-med-clm-23","collectionLabel":"MED · MED CLM 23","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 23","subtopic":"","stem":"Homem, 18 anos, vítima de queimaduras de segundo e terceiro graus durante incêndio,\nencontra-se com 50% de superfície corporal queimada. Apresenta, nos exames laboratoriais,\n\n90.000 de plaquetas e aumento do TAP, PTT e TT. O tempo de trombina desse paciente deverá\nestar alargado em virtude de:","options":{"A":"Hipofibrinogemia.","B":"Aumento importante do PTTa.","C":"Plaquetopenia significativa.","D":"Deficiências dos fatores de coagulação vitamina K-dependentes.","E":"Distribuição anormal das plaquetas."},"answer":"A","source":"Clinica médica/MED CLM 23/MED CLM 23.txt","sourceLabel":"MED · MED CLM 23","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 23","MED"],"answerSource":"explicit","commentDeferred":true}]};
